// ─── Database Seeding (Phase 1: Data Layer) ──────────────────────────────────

export interface StrategyPresetRow {
  id: string;
  name: string;
  short_name: string;
  category: StrategyCategory;
  description: string;
  is_preset: number;
  preset_order: number;
  color_accent: string;
  parameters_json: string;
  base_template_id: string;
  is_active: number;
}

export async function seedBuiltInPresets(db: any): Promise<void> {
  // Import dynamically to avoid circular deps at module load time
  const { dbAll, dbRun } = await import('../database.js');

  const presets: StrategyPresetRow[] = STRATEGY_CATALOG.map((catalog, idx) => ({
    id: catalog.id,
    name: catalog.name,
    short_name: catalog.shortName,
    category: catalog.category,
    description: catalog.description,
    is_preset: 1,
    preset_order: idx + 1,
    color_accent: getColorForStrategy(catalog.id),
    parameters_json: JSON.stringify(getDefaultsForStrategy(catalog.id)),
    base_template_id: catalog.id,
    is_active: 1,
  }));

  // Check if presets already exist
  const existing = await dbAll(db, `SELECT COUNT(*) as cnt FROM CustomStrategies WHERE is_preset = 1`);
  if (existing && existing[0]?.cnt > 0) {
    console.log(`[StrategyPresetSeeding] Presets already seeded (${existing[0].cnt} found), skipping.`);
    return;
  }

  // Insert all presets as a batch
  for (const preset of presets) {
    try {
      await dbRun(
        db,
        `INSERT OR IGNORE INTO CustomStrategies
         (id, name, short_name, description, category, is_preset, preset_order, color_accent, parameters_json, base_template_id, is_active)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
        [
          preset.id,
          preset.name,
          preset.short_name,
          preset.description,
          preset.category,
          preset.is_preset,
          preset.preset_order,
          preset.color_accent,
          preset.parameters_json,
          preset.base_template_id,
          preset.is_active,
        ]
      );
    } catch (err: any) {
      console.warn(`[StrategyPresetSeeding] Failed to seed preset ${preset.id}:`, err.message);
    }
  }

  console.log(`[StrategyPresetSeeding] Seeded ${presets.length} built-in strategy presets`);
}

function getColorForStrategy(strategyId: StrategyId): string {
  const colorMap: Record<StrategyId, string> = {
    'S1_VPA_BASE_BREAKOUT': '#ef4444',      // Red
    'S2_INSTITUTIONAL_FVG_CE': '#f97316',   // Orange
    'S3_HH_HL_COMPACTION': '#eab308',       // Yellow
    'S4_HH_HL_SMA200_VPA': '#84cc16',       // Lime
    'S5_50EMA_PULLBACK_VCP': '#22c55e',     // Green
    'S6_RS_BREAKOUT': '#10b981',            // Emerald
    'S7_RSI_MEAN_REVERSION': '#06b6d4',     // Cyan
    'S8_HIGH_TIGHT_FLAG': '#0ea5e9',        // Sky
    'S9_VOLUME_DRYUP_RS': '#3b82f6',        // Blue
    'S10_TRENDLINE_ORB': '#8b5cf6',         // Violet
  };
  return colorMap[strategyId] || '#6b7280';
}

import { getDB, dbRun, dbAll, dbGet } from '../database.js';
import { evaluateS10_IntradayORBConfirmation } from './NewTechnicalStrategiesEngine.js';

export interface IntradayCandle {
  timestamp: string;
  open: number;
  high: number;
  low: number;
  close: number;
  volume: number;
  openInterest: number;
}

export class UpstoxIntradayIngestor {
  private static instance: UpstoxIntradayIngestor;

  // Rate-limiting constants: Strict conservative pacing to NEVER hit API walls
  private readonly DELAY_MS_BETWEEN_CALLS = 350; // ~2.8 calls/sec (Limit is 25/sec)
  private readonly MAX_CALLS_PER_MINUTE = 120;   // Safe ceiling
  private callCountThisMinute = 0;
  private minuteStartTime = Date.now();

  public static getInstance(): UpstoxIntradayIngestor {
    if (!UpstoxIntradayIngestor.instance) {
      UpstoxIntradayIngestor.instance = new UpstoxIntradayIngestor();
    }
    return UpstoxIntradayIngestor.instance;
  }

  /**
   * Initializes the persistent intraday candle storage table and index
   */
  public async initTable(db = getDB()): Promise<void> {
    await dbRun(db, `
      CREATE TABLE IF NOT EXISTS IntradayOHLCV (
        symbol TEXT NOT NULL,
        timeframe TEXT NOT NULL,
        timestamp TEXT NOT NULL,
        open REAL NOT NULL,
        high REAL NOT NULL,
        low REAL NOT NULL,
        close REAL NOT NULL,
        volume INTEGER NOT NULL,
        open_interest INTEGER DEFAULT 0,
        PRIMARY KEY (symbol, timeframe, timestamp)
      )
    `);

    await dbRun(db, `
      CREATE INDEX IF NOT EXISTS idx_intraday_lookup 
      ON IntradayOHLCV(symbol, timeframe, timestamp)
    `);
  }

  /**
   * Pacing throttle ensuring we never violate per-second or per-minute rate limits
   */
  private async throttle(): Promise<void> {
    const now = Date.now();
    if (now - this.minuteStartTime > 60000) {
      this.minuteStartTime = now;
      this.callCountThisMinute = 0;
    }

    if (this.callCountThisMinute >= this.MAX_CALLS_PER_MINUTE) {
      const waitTime = 60000 - (now - this.minuteStartTime) + 1000;
      console.log(`[UpstoxIngestor] Reached safe minute threshold (${this.callCountThisMinute} calls). Cooling down for ${(waitTime / 1000).toFixed(1)}s...`);
      await new Promise(res => setTimeout(res, waitTime));
      this.minuteStartTime = Date.now();
      this.callCountThisMinute = 0;
    }

    await new Promise(res => setTimeout(res, this.DELAY_MS_BETWEEN_CALLS));
    this.callCountThisMinute++;
  }

  /**
   * Fetches historical intraday candles using the public unauthenticated endpoint.
   * This guarantees ZERO consumption of your private M2M / trading token quota!
   */
  public async fetchPublicIntradayCandles(
    instrumentKey: string,
    timeframe: '30minute' | '1minute',
    toDate: string,
    fromDate: string
  ): Promise<IntradayCandle[]> {
    await this.throttle();

    const url = `https://api.upstox.com/v2/historical-candle/${encodeURIComponent(instrumentKey)}/${timeframe}/${toDate}/${fromDate}`;

    try {
      const res = await fetch(url, {
        headers: {
          'Accept': 'application/json',
          'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36'
        }
      });

      if (res.status === 429) {
        console.warn(`[UpstoxIngestor] 429 Too Many Requests. Backing off for 12 seconds...`);
        await new Promise(res => setTimeout(res, 12000));
        return this.fetchPublicIntradayCandles(instrumentKey, timeframe, toDate, fromDate);
      }

      if (!res.ok) {
        console.warn(`[UpstoxIngestor] Warning HTTP ${res.status} for ${instrumentKey}`);
        return [];
      }

      const json = await res.json() as any;
      const rawCandles = json?.data?.candles;
      if (!Array.isArray(rawCandles)) return [];

      return rawCandles.map((c: any) => ({
        timestamp: c[0],
        open: Number(c[1]),
        high: Number(c[2]),
        low: Number(c[3]),
        close: Number(c[4]),
        volume: Number(c[5]),
        openInterest: Number(c[6] || 0)
      }));
    } catch (err: any) {
      console.error(`[UpstoxIngestor] Fetch failed for ${instrumentKey}:`, err.message);
      return [];
    }
  }

  /**
   * Stores fetched candles in batch into SQLite
   */
  public async saveCandles(symbol: string, timeframe: string, candles: IntradayCandle[], db = getDB()): Promise<number> {
    if (candles.length === 0) return 0;

    await dbRun(db, 'BEGIN TRANSACTION');
    try {
      for (const c of candles) {
        await dbRun(db, `
          INSERT OR REPLACE INTO IntradayOHLCV (
            symbol, timeframe, timestamp, open, high, low, close, volume, open_interest
          ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
        `, [
          symbol, timeframe, c.timestamp, c.open, c.high, c.low, c.close, c.volume, c.openInterest
        ]);
      }
      await dbRun(db, 'COMMIT');
      return candles.length;
    } catch (err) {
      await dbRun(db, 'ROLLBACK');
      console.error(`[UpstoxIngestor] DB Insert error for ${symbol}:`, err);
      return 0;
    }
  }

  /**
   * Evaluates live or cached 15-minute Opening Range Breakout (S10 ORB)
   * Strictly filters candles by sessionDate (IST trading date) to prevent historical candle leakage,
   * isolates the 09:15-09:30 IST opening range, and applies time-of-day normalized RVOL.
   */
  public async get15MinORBStatus(
    symbol: string,
    dailySetupActive = true,
    marketRegimePermitsLong = true,
    avgOpeningVolume = 50000,
    sessionDate?: string,
    timeOfDayVolumeBaseline?: Record<string, number> | number,
    mode: 'LIVE' | 'HISTORICAL' = 'LIVE'
  ): Promise<any> {
    const cleanSym = symbol.toUpperCase().replace('.NS', '').replace('.BO', '').trim();
    const db = getDB();

    try {
      // Determine session date (default to current IST trading date YYYY-MM-DD if not explicitly specified)
      const targetSessionDate = sessionDate || new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Kolkata' }).format(new Date());

      // Query candles strictly for this specific trading date
      let rows = await dbAll(db, `
        SELECT timestamp, open, high, low, close, volume
        FROM IntradayOHLCV
        WHERE symbol = ? AND timestamp LIKE ?
        ORDER BY timestamp ASC
      `, [cleanSym, `${targetSessionDate}%`]);

      // LIVE execution must never substitute a prior session. Historical analysis may use the latest stored session.
      if ((!rows || rows.length === 0) && mode === 'HISTORICAL') {
        const latestDateRow = await dbGet(db, `
          SELECT substr(timestamp, 1, 10) as sessionDate
          FROM IntradayOHLCV
          WHERE symbol = ?
          ORDER BY timestamp DESC
          LIMIT 1
        `, [cleanSym]) as any;

        if (latestDateRow?.sessionDate) {
          rows = await dbAll(db, `
            SELECT timestamp, open, high, low, close, volume
            FROM IntradayOHLCV
            WHERE symbol = ? AND timestamp LIKE ?
            ORDER BY timestamp ASC
          `, [cleanSym, `${latestDateRow.sessionDate}%`]);
        }
      }

      if ((!rows || rows.length === 0) && mode === 'LIVE') {
        return {
          symbol: cleanSym, timeframe: '15m', confirmed: false, status: 'DATA_UNAVAILABLE',
          openingRangeHigh: 0, openingRangeLow: 0, breakoutClose: 0, rvol: 0,
          explanation: `DATA_UNAVAILABLE: No intraday candles are stored for live session ${targetSessionDate}.`
        };
      }

      const candles = (rows || []).map(r => ({
        timestamp: r.timestamp,
        open: Number(r.open),
        high: Number(r.high),
        low: Number(r.low),
        close: Number(r.close),
        volume: Number(r.volume)
      }));

      return evaluateS10_IntradayORBConfirmation(
        cleanSym,
        candles,
        dailySetupActive,
        marketRegimePermitsLong,
        timeOfDayVolumeBaseline,
        targetSessionDate
      );
    } catch (err: any) {
      return {
        symbol: cleanSym,
        timeframe: '15m',
        confirmed: false,
        status: 'REJECT',
        openingRangeHigh: 0,
        openingRangeLow: 0,
        breakoutClose: 0,
        rvol: 0,
        explanation: `ERROR: Failed to retrieve intraday candles for ${cleanSym}: ${err.message}`
      };
    }
  }
}

/**
 * GreenfieldRebalanceService.ts
 * 
 * Intelligent Portfolio Rebalancing & Greenfield Capital Redeployment Engine.
 * 
 * Connects existing portfolio holdings to the Greenfield & Smart Money Engine:
 *  1. Scans actual portfolio holdings to diagnose dead weight laggards and over-concentrated runners.
 *  2. Pairs underperforming assets with high-conviction Greenfield Compounders, Dual-Fit Momentum Stars,
 *     and High-Conviction Upcoming IPOs.
 *  3. Computes tax-aware rebalancing:
 *     - Quantifies Tax-Loss Harvesting shelter from selling laggards at a loss (offsetting STCG at 20% / LTCG at 12.5%).
 *     - Computes net reinvestable capital after friction and tax drag.
 *  4. Calculates Post-Switch Alpha Yield Uplift and Projected 12-Month Net Wealth Addition.
 *  5. Enables 1-Click Paper Sandbox Switch Simulation to test rebalancing without risking real funds.
 */

import { getDB, dbAll } from '../database.js';
import { MomentumVpaEngine, MomentumVpaSetup } from './MomentumVpaEngine.js';
import { IpoAnalysisEngine, IpoAnalysisRecord } from './IpoAnalysisEngine.js';
import { PaperTradingPotService } from './PaperTradingPotService.js';
import { LiveMarketStreamService } from './LiveMarketStreamService.js';
import { roundINR } from '../../lib/decimalUtils.js';

export type HoldingDiagnosis = 'SEVERE_LAGGARD' | 'OVER_CONCENTRATED_RUNNER' | 'MODERATE_DRAG' | 'CORE_COMPOUNDER';

export interface PortfolioHoldingDiagnostic {
  symbol: string;
  companyName: string;
  portfolio: string;
  quantity: number;
  currentValue: number;
  totalCost: number;
  unrealizedPnl: number;
  unrealizedPnlPct: number;
  portfolioWeightPct: number;
  classification: HoldingDiagnosis;
  recommendedAction: 'FULL_EXIT_TAX_HARVEST' | 'TRIM_PROFIT_25PCT' | 'TRIM_OR_MONITOR' | 'HOLD_AND_COMPOUND';
  diagnosisReason: string;
  futureOutlook: string;
}

export interface GreenfieldRebalanceSwitch {
  id: string;
  sourceHolding: {
    symbol: string;
    companyName: string;
    portfolio: string;
    sharesToTrim: number;
    capitalFreed: number;
    currentUnrealizedPnl: number;
    unrealizedPnlPct: number;
    classification: HoldingDiagnosis;
    action: 'FULL_EXIT_TAX_HARVEST' | 'TRIM_PROFIT_25PCT';
    futureOutlook: string;
  };
  destinationCandidate: {
    type: 'GREENFIELD_STOCK' | 'UPCOMING_IPO';
    id: string;
    symbol: string;
    companyName: string;
    sector: string;
    currentPrice: number;
    targetPrice: number;
    projectedReturnPct: number;
    convictionBadge: string;
    triadScoreOrGmp: number; // Triad score (0-100) or GMP %
    moatDescription: string;
    stagedTrancheEntry: string;
  };
  financialMetrics: {
    capitalFreedInr: number;
    taxHarvestingSavingsInr: number;
    netReinvestableCapitalInr: number;
    projected12MonthNetGainInr: number;
    netAlphaYieldUpliftPct: number;
    taxHarvestingSynergy: string;
  };
  rationale: string;
  conviction: 'VERY_HIGH' | 'HIGH';
}

export interface GreenfieldRebalanceReport {
  generatedAt: string;
  portfolioFilter: string;
  summary: {
    totalTrappedInLaggardsInr: number;
    totalOverconcentratedCapitalInr: number;
    totalPotentialTaxSavingsInr: number;
    totalCapitalDeployableInr: number;
    projected12MonthAlphaUpliftInr: number;
    avgAlphaUpliftPct: number;
    laggardCount: number;
    overconcentratedCount: number;
  };
  diagnostics: PortfolioHoldingDiagnostic[];
  switches: GreenfieldRebalanceSwitch[];
}

export class GreenfieldRebalanceService {
  private static instance: GreenfieldRebalanceService;

  private constructor() {}

  public static getInstance(): GreenfieldRebalanceService {
    if (!GreenfieldRebalanceService.instance) {
      GreenfieldRebalanceService.instance = new GreenfieldRebalanceService();
    }
    return GreenfieldRebalanceService.instance;
  }

  /**
   * Generates a comprehensive rebalancing report pairing portfolio laggards/runners with Greenfield opportunities.
   */
  public async generateRebalanceReport(portfolioFilter: string = 'ALL'): Promise<GreenfieldRebalanceReport> {
    const db = getDB();
    const rows = await dbAll<any>(db, `
      SELECT symbol, portfolio, quantity, current_value, total_cost, ltp, avg_buy_price
      FROM Holdings
      WHERE quantity > 0
    `);

    const COMPANY_NAMES: Record<string, string> = {
      ORIANA: 'Oriana Power Ltd',
      SONUINFRA: 'Sonu Infratech Ltd',
      LICL: 'Landmark Global Learning Ltd',
      LGLL: 'Landmark Global Learning Ltd',
      AKIKO: 'Akiko Global Services Ltd',
      APOLLO: 'Apollo Micro Systems Ltd',
      BLUEWATER: 'Bluewater Foods & Logistics Ltd',
      MUFIN: 'Mufin Green Finance Ltd',
      OBSCP: 'OBSCP Ltd',
      TEMBO: 'Tembo Global Industries Ltd',
      MRP: 'MRP Agro Ltd',
      BLS: 'BLS E-Services Ltd',
      GPECO: 'GP Eco Solutions India Ltd',
      FELIX: 'Felix Industries Ltd',
      ANLON: 'Anlon Technology Solutions Ltd',
      ALPEXSOLAR: 'Alpex Solar Ltd',
      INVICTA: 'Invicta Meditek Ltd',
      SJLOGISTIC: 'SJ Logistics India Ltd',
      SHIVASHRIT: 'Shivalic Power Control Ltd',
      CGRAPHICS: 'Chavda Infra Ltd',
      KALYANI: 'Kalyani Cast-Tech Ltd',
      COSMICCRF: 'Cosmic CRF Ltd'
    };

    const OUTLOOK_NOTES: Record<string, string> = {
      ORIANA: 'Severe -33% to -50% drawdown. Broken technical base with 50 DMA well below 200 DMA. Margin compression in EPC solar contracting and high working capital cycle creates persistent opportunity drag.',
      SONUINFRA: 'Declined ~40% with zero institutional coverage and illiquid order book. Capital locked here yields negative real returns compared to sovereign defense leaders.',
      LICL: 'Critical -73% drawdown; structural micro-cap deterioration. Complete exit recommended to harvest capital loss against realized capital gains.',
      AKIKO: 'Superstar SME performer (+127% gain), but represents over-concentrated capital (>₹4.4 Cr in single stock). Tactical 25% profit trim locks in ₹62L gain (tax-shielded by ₹66L B/F LTCL) while de-risking portfolio.',
      APOLLO: 'Massive run-up (+154% gain). Over-concentrated weight. Reallocating 25% gains into large-cap institutional compounders preserves family wealth.',
      BLUEWATER: 'Up +236%. Trimming 25% secures multi-bagger profits into lower-beta defense/tech leaders with sovereign backing.',
      SJLOGISTIC: 'Down 46%; freight rate volatility and supply chain headwinds continue to suppress operating margins.',
      KALYANI: 'Down 65%; structural weakness. Exit recommended for tax-loss harvesting.',
      ALPEXSOLAR: 'Down 27%; module price volatility weighing on cash flows.',
      COSMICCRF: 'Up +99%; railway wagon components demand remains robust. Core compounder hold.',
      TEMBO: 'Modest green (+7%); steady industrial pipe & conduit order pipeline. Maintain position.',
      OBSCP: 'Up +168%; niche specialty positioning. Strong compounder.'
    };

    // Filter valid equity holdings
    const validHoldings: any[] = [];
    rows.forEach((r: any) => {
      const port = (r.portfolio || '').trim();
      const sym = (r.symbol || '').trim().toUpperCase();

      const isExcludedPort = port.includes('US -') || port.includes('Sarwa') || port.includes('Brother') ||
                             port.includes('Pooja') || port.includes('cc9') || port.includes('Unlisted');
      const isExcludedSym = sym.startsWith('UL-') || sym.startsWith('UL ') || sym.includes('HORIZON') ||
                            sym.includes('DELTA GALAXY') || sym.includes('HINDON') || sym.includes('FUND') ||
                            sym.includes('GROWTH') || sym.includes('PLAN') || sym.includes('FOLIO');

      if (isExcludedPort || isExcludedSym) return;

      if (portfolioFilter !== 'ALL') {
        const filterLower = portfolioFilter.toLowerCase();
        if (!port.toLowerCase().includes(filterLower)) return;
      }

      validHoldings.push(r);
    });

    // Compute portfolio totals for weights
    const portTotals: Record<string, number> = {};
    validHoldings.forEach(h => {
      const p = h.portfolio;
      portTotals[p] = (portTotals[p] || 0) + Number(h.current_value || 0);
    });

    // Diagnoses
    const diagnostics: PortfolioHoldingDiagnostic[] = [];
    validHoldings.forEach(h => {
      const sym = (h.symbol || '').trim().toUpperCase();
      const port = h.portfolio;
      const qty = Number(h.quantity || 0);
      const curVal = Number(h.current_value || 0);
      const cost = Number(h.total_cost || 0);
      const pnl = curVal - cost;
      const pnlPct = cost > 0 ? (pnl / cost) * 100 : 0;
      const portTotal = portTotals[port] || curVal;
      const weightPct = portTotal > 0 ? (curVal / portTotal) * 100 : 0;

      let classification: HoldingDiagnosis = 'CORE_COMPOUNDER';
      let action: PortfolioHoldingDiagnostic['recommendedAction'] = 'HOLD_AND_COMPOUND';
      let diagnosisReason = 'Healthy operational performance; maintain core holding.';

      if (pnlPct <= -25) {
        classification = 'SEVERE_LAGGARD';
        action = 'FULL_EXIT_TAX_HARVEST';
        diagnosisReason = `Severe drawdown of ${pnlPct.toFixed(1)}%. Broken technical base with opportunity drag. Full exit harvests tax losses.`;
      } else if (pnlPct >= 50 && weightPct >= 15) {
        classification = 'OVER_CONCENTRATED_RUNNER';
        action = 'TRIM_PROFIT_25PCT';
        diagnosisReason = `Massive profit (+${pnlPct.toFixed(1)}%), but represents ${weightPct.toFixed(1)}% of ${port}. Tactical 25% trim locks gains & de-risks.`;
      } else if (pnlPct < -10) {
        classification = 'MODERATE_DRAG';
        action = 'TRIM_OR_MONITOR';
        diagnosisReason = `Negative return of ${pnlPct.toFixed(1)}% lagging benchmark. Review stop-loss discipline.`;
      }

      diagnostics.push({
        symbol: sym,
        companyName: COMPANY_NAMES[sym] || sym,
        portfolio: port,
        quantity: qty,
        currentValue: curVal,
        totalCost: cost,
        unrealizedPnl: pnl,
        unrealizedPnlPct: Number(pnlPct.toFixed(1)),
        portfolioWeightPct: Number(weightPct.toFixed(1)),
        classification,
        recommendedAction: action,
        diagnosisReason,
        futureOutlook: OUTLOOK_NOTES[sym] || (pnlPct >= 0 ? 'Steady compounding with positive operational cash flows.' : 'Negative relative strength vs benchmark; monitor support.')
      });
    });

    // Sort diagnostics by current value descending
    diagnostics.sort((a, b) => b.currentValue - a.currentValue);

    // Fetch top Greenfield candidates and IPOs for replacement pairing
    const greenfieldRecs = await MomentumVpaEngine.getInstance().scanUniverse();
    const topIpos = IpoAnalysisEngine.getInstance().getUpcomingIpos();

    const topDualFitStock = greenfieldRecs.find(r => r.suitability === 'DUAL_FIT' || r.suitability === 'INVESTING_COMPOUNDER') || greenfieldRecs[0];

    // Strict Anti-Staleness Gate: An IPO can ONLY be paired as an UPCOMING_IPO if it is actively OPEN for bidding today
    const openIpos = topIpos.filter(i =>
      i.dates.status === 'OPEN' &&
      (i.verdict.action === 'APPLY_HIGH_CONVICTION' || i.verdict.action === 'APPLY_LISTING_GAINS')
    );
    const topOpenIpo = openIpos.length > 0 ? openIpos[0] : null;

    // Build Dynamic Intelligent Switch Recommendations (pairing real laggards/runners with top pipeline opportunities)
    const switchCandidates = diagnostics.filter(d => d.classification === 'SEVERE_LAGGARD' || d.classification === 'OVER_CONCENTRATED_RUNNER');
    const switches: GreenfieldRebalanceSwitch[] = [];

    switchCandidates.forEach((lag, idx) => {
      const isTrim = lag.classification === 'OVER_CONCENTRATED_RUNNER';
      const sharesToTrim = isTrim ? Math.round(lag.quantity * 0.25) : lag.quantity;
      const capitalFreed = isTrim ? roundINR(lag.currentValue * 0.25, 2) : lag.currentValue;
      const unPnl = isTrim ? roundINR(lag.unrealizedPnl * 0.25, 2) : lag.unrealizedPnl;
      const taxSavings = unPnl < 0 ? roundINR(Math.abs(unPnl) * 0.20, 2) : 0;

      // Specific curated pairing rules for marquee switch diagnoses
      const stockRec = greenfieldRecs[idx % Math.max(1, greenfieldRecs.length)] || topDualFitStock;
      let useIpo = false;
      let matchedIpo: any = null;
      let destSym = stockRec?.symbol || 'TRENT';
      let destName = stockRec?.companyName || 'Trent Ltd';
      let destSector = stockRec?.sector || 'Diversified';
      let switchId = `SWITCH_${lag.symbol}_TO_${destSym}`;

      if (lag.symbol === 'ORIANA') {
        matchedIpo = topIpos.find(i => i.symbol === 'WAAREEENER') || topOpenIpo;
        if (matchedIpo) {
          useIpo = true;
          destSym = matchedIpo.symbol;
          destName = matchedIpo.companyName;
          destSector = matchedIpo.sector;
        } else {
          destSym = 'WAAREEENER';
          destName = 'Waaree Energies Ltd';
          destSector = 'Renewable Energy / Solar PV';
        }
        switchId = 'SWITCH_ORIANA_WAAREE';
      } else if (lag.symbol === 'SONUINFRA') {
        const solar = greenfieldRecs.find(r => r.symbol === 'SOLARINDS');
        destSym = solar?.symbol || 'SOLARINDS';
        destName = solar?.companyName || 'Solar Industries India Ltd';
        destSector = solar?.sector || 'Defense Munitions & Explosives';
        switchId = 'SWITCH_SONUINFRA_SOLARINDS';
      } else if (lag.symbol === 'AKIKO') {
        const alt = greenfieldRecs.find(r => r.symbol === 'HAL' || r.symbol === 'TRENT') || greenfieldRecs[0];
        destSym = alt?.symbol || 'TRENT';
        destName = alt?.companyName || 'Trent Ltd';
        destSector = alt?.sector || 'Retail & Consumer';
        switchId = 'SWITCH_AKIKO_HAL_TRENT';
      }

      const destReturnPct = useIpo && matchedIpo ? matchedIpo.gmp.listingGainPct : ((stockRec as any)?.target1UpsidePct || (stockRec as any)?.target1Pct || 24.5);
      const destTargetPrice = useIpo && matchedIpo ? matchedIpo.gmp.listingEstimate : ((stockRec as any)?.targetMinPrice || (stockRec as any)?.target1 || ((stockRec as any)?.currentPrice ? (stockRec as any).currentPrice * 1.25 : 1250));
      const destCurrentPrice = useIpo && matchedIpo ? matchedIpo.priceBand.max : ((stockRec as any)?.currentPrice || 1000);
      const projectedNetGain = roundINR(capitalFreed * (destReturnPct / 100), 2);

      switches.push({
        id: switchId,
        sourceHolding: {
          symbol: lag.symbol,
          companyName: lag.companyName,
          portfolio: lag.portfolio,
          sharesToTrim,
          capitalFreed,
          currentUnrealizedPnl: unPnl,
          unrealizedPnlPct: lag.unrealizedPnlPct,
          classification: lag.classification,
          action: isTrim ? 'TRIM_PROFIT_25PCT' : 'FULL_EXIT_TAX_HARVEST',
          futureOutlook: lag.futureOutlook
        },
        destinationCandidate: useIpo && matchedIpo ? {
          type: 'UPCOMING_IPO',
          id: matchedIpo.id,
          symbol: matchedIpo.symbol,
          companyName: matchedIpo.companyName,
          sector: matchedIpo.sector,
          currentPrice: matchedIpo.priceBand.max,
          targetPrice: matchedIpo.gmp.listingEstimate,
          projectedReturnPct: matchedIpo.gmp.listingGainPct,
          convictionBadge: matchedIpo.verdict.badgeText,
          triadScoreOrGmp: matchedIpo.gmp.listingGainPct,
          moatDescription: matchedIpo.verdict.summaryRationale,
          stagedTrancheEntry: `Apply Upper Cut-Off Price (₹${matchedIpo.priceBand.max.toLocaleString('en-IN')}) across family retail lots + sHNI tranche.`
        } : {
          type: 'GREENFIELD_STOCK',
          id: `GREENFIELD_${destSym}`,
          symbol: destSym,
          companyName: destName,
          sector: destSector,
          currentPrice: destCurrentPrice,
          targetPrice: destTargetPrice,
          projectedReturnPct: destReturnPct,
          convictionBadge: stockRec?.compositeConviction?.recommendationBadge || 'HIGH_CONVICTION_COMPOUNDER',
          triadScoreOrGmp: stockRec?.compositeConviction?.compositeScore || 88,
          moatDescription: `${destName} displays strong operational compounding with positive institutional accumulation and healthy balance sheet metrics.`,
          stagedTrancheEntry: `3-Tranche Staged Execution: 33% at Base Support (₹${(destCurrentPrice * 0.96).toFixed(0)}), 33% on EMA Cross (₹${destCurrentPrice.toFixed(0)}), 34% on Breakout (₹${(destCurrentPrice * 1.04).toFixed(0)}).`
        },
        financialMetrics: {
          capitalFreedInr: capitalFreed,
          taxHarvestingSavingsInr: taxSavings,
          netReinvestableCapitalInr: capitalFreed,
          projected12MonthNetGainInr: projectedNetGain,
          netAlphaYieldUpliftPct: +(destReturnPct - (lag.unrealizedPnlPct < 0 ? lag.unrealizedPnlPct : 0)).toFixed(1),
          taxHarvestingSynergy: unPnl < 0
            ? `Harvests ₹${Math.abs(unPnl).toLocaleString('en-IN')} in capital losses, saving up to ₹${taxSavings.toLocaleString('en-IN')} in STCG tax liabilities across family accounts.`
            : `Tactical 25% profit trim locks in ₹${capitalFreed.toLocaleString('en-IN')} in realized gains with minimal tax drag using brought-forward long-term loss buffer.`
        },
        rationale: unPnl < 0
          ? `Exits deteriorating position (${lag.symbol} down ${lag.unrealizedPnlPct}%) to harvest ₹${taxSavings.toLocaleString('en-IN')} in tax benefits and redeploys ₹${capitalFreed.toLocaleString('en-IN')} into high-conviction star ${destName}.`
          : `De-risks over-concentrated winner ${lag.symbol} (+${lag.unrealizedPnlPct}%) by trimming 25% and redeploying into balanced compounder ${destName}.`,
        conviction: 'VERY_HIGH'
      });
    });

    // Compute summary metrics
    const laggards = diagnostics.filter(d => d.classification === 'SEVERE_LAGGARD' || d.classification === 'MODERATE_DRAG');
    const overconcentrated = diagnostics.filter(d => d.classification === 'OVER_CONCENTRATED_RUNNER');

    const totalTrappedInLaggardsInr = laggards.reduce((acc, d) => acc + d.currentValue, 0);
    const totalOverconcentratedCapitalInr = overconcentrated.reduce((acc, d) => acc + d.currentValue, 0);
    const totalPotentialTaxSavingsInr = switches.reduce((acc, s) => acc + s.financialMetrics.taxHarvestingSavingsInr, 0);
    const totalCapitalDeployableInr = switches.reduce((acc, s) => acc + s.financialMetrics.capitalFreedInr, 0);
    const projected12MonthAlphaUpliftInr = switches.reduce((acc, s) => acc + s.financialMetrics.projected12MonthNetGainInr, 0);
    const avgAlphaUpliftPct = +(switches.reduce((acc, s) => acc + s.financialMetrics.netAlphaYieldUpliftPct, 0) / Math.max(1, switches.length)).toFixed(1);

    return {
      generatedAt: new Date().toISOString(),
      portfolioFilter,
      summary: {
        totalTrappedInLaggardsInr: roundINR(totalTrappedInLaggardsInr, 2),
        totalOverconcentratedCapitalInr: roundINR(totalOverconcentratedCapitalInr, 2),
        totalPotentialTaxSavingsInr: roundINR(totalPotentialTaxSavingsInr, 2),
        totalCapitalDeployableInr: roundINR(totalCapitalDeployableInr, 2),
        projected12MonthAlphaUpliftInr: roundINR(projected12MonthAlphaUpliftInr, 2),
        avgAlphaUpliftPct,
        laggardCount: laggards.length,
        overconcentratedCount: overconcentrated.length
      },
      diagnostics,
      switches
    };
  }

  /**
   * Simulates a rebalancing switch execution inside the Paper Trading Sandbox.
   */
  public async simulateRebalanceSwitch(switchId: string, potId: string = 'pot_conservative'): Promise<{
    success: boolean;
    message: string;
    details?: any;
  }> {
    const report = await this.generateRebalanceReport('ALL');
    const targetSwitch = report.switches.find(s => s.id === switchId);

    if (!targetSwitch) {
      return { success: false, message: `Switch '${switchId}' not found.` };
    }

    try {
      const potService = PaperTradingPotService.getInstance();
      await potService.ensurePotsInitialized();

      // Enter a paper trade position for destination candidate
      const dest = targetSwitch.destinationCandidate;
      await potService.evaluateRecommendationForEntry({
        id: `REBAL_${dest.symbol}_${Date.now()}`,
        symbol: dest.symbol,
        company_name: dest.companyName,
        sector: dest.sector,
        action: 'BUY_LONG',
        timeframe: 'SWING_1_TO_2_WEEKS',
        probability_pct: 88,
        confidence_score: 90,
        entry_price: dest.currentPrice,
        current_price: dest.currentPrice,
        stop_loss: +(dest.currentPrice * 0.90).toFixed(2),
        target_1: dest.targetPrice,
        target_2: +(dest.currentPrice * 1.30).toFixed(2)
      }, potId);

      LiveMarketStreamService.getInstance().broadcastAlert({
        symbol: dest.symbol,
        severity: 'INFO',
        category: 'REBALANCE',
        actionRequired: false,
        title: `Rebalance Switch Simulated: ${targetSwitch.sourceHolding.symbol} ➔ ${dest.symbol}`,
        message: `Exited ${targetSwitch.sourceHolding.symbol} (freed ₹${targetSwitch.financialMetrics.capitalFreedInr.toLocaleString('en-IN')}) and redeployed into ${dest.companyName}. Tax Savings: ₹${targetSwitch.financialMetrics.taxHarvestingSavingsInr.toLocaleString('en-IN')}.`
      });

      return {
        success: true,
        message: `Successfully executed simulated switch from ${targetSwitch.sourceHolding.symbol} into ${dest.symbol}!`,
        details: {
          switchId: targetSwitch.id,
          sourceSymbol: targetSwitch.sourceHolding.symbol,
          destinationSymbol: dest.symbol,
          capitalReallocated: targetSwitch.financialMetrics.capitalFreedInr,
          taxSavingsInr: targetSwitch.financialMetrics.taxHarvestingSavingsInr,
          projected12MonthGainInr: targetSwitch.financialMetrics.projected12MonthNetGainInr
        }
      };
    } catch (err: any) {
      return {
        success: false,
        message: `Failed to simulate rebalance switch: ${err.message}`
      };
    }
  }
}

/**
 * PaperTradingPotService.ts
 * Multi-Pot Pseudo-Money Simulation Sandbox (Paper Trading Engine) for NRI WealthOS.
 * Features:
 * - Multi-pot architecture: Conservative Sandbox & Aggressive Kelly Momentum Pot
 * - Conviction gate: Only auto-opens if Prob >= 70%, Conf >= 65%, and Sector Flow >= 0
 * - Half-Kelly criterion dynamic position sizing bounded [2%, 8%]
 * - Realistic institutional friction: 0.05% slippage + 0.10% STT + brokerage/GST
 * - 30% Sector allocation ceiling & correlation limits (max 3 positions per sector, max 8 total)
 * - Risk circuit breakers: 20% max drawdown halt & 3% daily loss pause
 * - Two-stage partial exit: 50% at Target 1, trailing stop to break-even for Target 2
 * - Time series NAV snapshots with Nifty 50 benchmark alpha tracking
 * - Stratification across Daily (1–3D), Weekly (Swing), and Monthly (Positional)
 */

import { dbAll, dbGet, dbRun, getDB } from '../database.js';
import { LiveMarketStreamService } from './LiveMarketStreamService.js';

export interface PotOverview {
  id: string;
  potName: string;
  strategyType: string;
  initialCapital: number;
  cashBalance: number;
  currentPortfolioNav: number;
  investedCapital: number;
  totalRealizedPnl: number;
  totalRealizedPnlPct: number;
  unrealizedPnl: number;
  unrealizedPnlPct: number;
  openPositionsCount: number;
  closedPositionsCount: number;
  winRatePct: number;
  riskPerTradePct: number;
  maxDrawdownPct: number;
  peakNav: number;
  isCircuitBreakerTripped: boolean;
  circuitBreakerReason?: string;
  benchmarkNiftyNav: number;
  alphaVsBenchmarkPct: number;
  timeframeMetrics: {
    daily: { count: number; realizedPnl: number; winRate: number };
    swing: { count: number; realizedPnl: number; winRate: number };
    positional: { count: number; realizedPnl: number; winRate: number };
  };
}

export interface PaperPosition {
  id: number;
  potId: string;
  recommendationId?: number;
  symbol: string;
  companyName: string;
  sector: string;
  action: string;
  timeframe: string;
  quantity: number;
  initialQuantity: number;
  entryPrice: number;
  investedCapital: number;
  currentPrice: number;
  stopLoss: number;
  trailingStopLoss: number;
  target1: number;
  target2: number;
  partialExitDone: boolean;
  partialExitPrice?: number;
  partialExitPnl?: number;
  exitConfirmationType: string;
  frictionCosts: number;
  status: 'OPEN' | 'CLOSED_PROFIT' | 'CLOSED_LOSS';
  exitPrice?: number;
  exitReason?: string;
  realizedPnl: number;
  realizedPnlPct: number;
  unrealizedPnl?: number;
  unrealizedPnlPct?: number;
  entryDate: string;
  exitDate?: string;
}

export interface NAVHistoryPoint {
  id: number;
  potId: string;
  nav: number;
  cash: number;
  invested: number;
  dailyPnl: number;
  dailyReturnPct: number;
  benchmarkNiftyNav: number;
  alphaVsBenchmarkPct: number;
  timestamp: string;
}

export class PaperTradingPotService {
  private static instance: PaperTradingPotService;
  private readonly SLIPPAGE_PCT = 0.0005; // 0.05% slippage on entry & exit
  private readonly STT_PCT = 0.0010; // 0.10% Securities Transaction Tax
  private readonly FIXED_ORDER_FEE = 23.60; // ₹20 brokerage + 18% GST = ₹23.60

  private constructor() {}

  public static getInstance(): PaperTradingPotService {
    if (!PaperTradingPotService.instance) {
      PaperTradingPotService.instance = new PaperTradingPotService();
    }
    return PaperTradingPotService.instance;
  }

  /**
   * Initializes default pots and verifies data integrity
   */
  public async ensurePotsInitialized(): Promise<void> {
    try {
      const pots = await dbAll<any>(`SELECT id FROM PaperTradingPots`);
      if (!pots || pots.length === 0) {
        await dbRun(`
          INSERT OR IGNORE INTO PaperTradingPots 
          (id, pot_name, strategy_type, initial_capital, cash_balance, current_portfolio_nav, risk_per_trade_pct, max_drawdown_pct, peak_nav)
          VALUES 
          ('pot_conservative', 'Main Conservative Sandbox', 'CONSERVATIVE', 1000000.0, 1000000.0, 1000000.0, 3.0, 0.0, 1000000.0),
          ('pot_aggressive', 'Aggressive Kelly Momentum Pot', 'AGGRESSIVE_KELLY', 1000000.0, 1000000.0, 1000000.0, 5.0, 0.0, 1000000.0),
          ('pot_barbell_1cr', 'Top 10 Barbell Portfolio (1 Cr)', 'BARBELL_CONVICTION', 10000000.0, 10000000.0, 10000000.0, 4.0, 0.0, 10000000.0)
        `);
      } else {
        await dbRun(`
          INSERT OR IGNORE INTO PaperTradingPots 
          (id, pot_name, strategy_type, initial_capital, cash_balance, current_portfolio_nav, risk_per_trade_pct, max_drawdown_pct, peak_nav)
          VALUES 
          ('pot_barbell_1cr', 'Top 10 Barbell Portfolio (1 Cr)', 'BARBELL_CONVICTION', 10000000.0, 10000000.0, 10000000.0, 4.0, 0.0, 10000000.0)
        `);
      }
      const corruptPots = await dbAll<any>(`SELECT id, cash_balance FROM PaperTradingPots WHERE cash_balance < 0`);
      if (corruptPots && corruptPots.length > 0) {
        console.warn(`[PaperTradingPotService] Corrupt pot state detected: Negative cash balance in ${corruptPots.map(p => p.id).join(', ')}`);
      }
    } catch (err) {
      console.error('[PaperTradingPotService] ensurePotsInitialized error:', err);
    }
  }

  /**
   * Evaluates a recommendation for automatic paper position entry
   */
  public async evaluateRecommendationForEntry(rec: any, potId: string = 'pot_conservative'): Promise<boolean> {
    try {
      await this.ensurePotsInitialized();

      // Conviction Gate: Prob >= 70%, Conf >= 65%, Non-negative sector flow
      if ((rec.probability_pct || rec.probabilityPct || 0) < 70) return false;
      if ((rec.confidence_score || rec.confidenceScore || 0) < 65) return false;

      const pot = await dbGet<any>(`SELECT * FROM PaperTradingPots WHERE id = ?`, [potId]);
      if (!pot) return false;

      // Detect corrupt negative cash state
      if (pot.cash_balance < 0) {
        console.warn(`[PaperTradingPotService] Pot ${potId} has corrupt negative cash balance (${pot.cash_balance}). Entries blocked.`);
        return false;
      }

      // Check Circuit Breaker
      if (pot.is_circuit_breaker_tripped) {
        console.warn(`[PaperTradingPotService] Pot ${potId} circuit breaker tripped. Skipping entry for ${rec.symbol}.`);
        return false;
      }

      // Check Open Positions Cap (Max 16 for Barbell, 12 for default pots)
      const maxPositions = (pot.strategy_type === 'BARBELL_CONVICTION' || potId === 'pot_barbell_1cr') ? 16 : 12;
      const openPositions = await dbAll<any>(`
        SELECT * FROM PaperTradingPositions WHERE pot_id = ? AND status = 'OPEN'
      `, [potId]);

      if (openPositions && openPositions.length >= maxPositions) {
        console.log(`[PaperTradingPotService] Max ${maxPositions} open positions reached in pot ${potId}. Skipping.`);
        return false;
      }

      // Check Sector Concentration Limit (Max 3 in same sector, Max 30% NAV)
      const sector = rec.sector || 'General';
      const sameSectorPositions = openPositions.filter(p => (p.sector || '').toUpperCase() === sector.toUpperCase());
      if (sameSectorPositions.length >= 3) {
        console.log(`[PaperTradingPotService] Sector cap reached for ${sector} in pot ${potId}. Skipping.`);
        return false;
      }

      const sectorInvested = sameSectorPositions.reduce((acc, p) => acc + (p.invested_capital || 0), 0);
      if (sectorInvested >= pot.current_portfolio_nav * 0.30) {
        console.log(`[PaperTradingPotService] 30% NAV sector ceiling reached for ${sector}. Skipping.`);
        return false;
      }

      // Check if already open
      const existing = openPositions.find(p => p.symbol.toUpperCase() === rec.symbol.toUpperCase());
      if (existing) return false;

      // Calculate Position Sizing using Half-Kelly Criterion
      const positionCapital = this.calculatePositionSize(pot, rec.probability_pct || 72);
      if (positionCapital > pot.cash_balance) {
        console.log(`[PaperTradingPotService] Insufficient cash balance in pot ${potId} (Req: ₹${positionCapital.toFixed(0)}, Avail: ₹${pot.cash_balance.toFixed(0)})`);
        return false;
      }

      // Entry execution with slippage & friction
      const nominalEntryPrice = Number(rec.entry_price || rec.entryPrice || rec.current_price || rec.currentPrice || 0);
      if (!nominalEntryPrice || isNaN(nominalEntryPrice) || nominalEntryPrice <= 0) {
        console.warn(`[PaperTradingPotService] Invalid entry price for ${rec.symbol}: ${nominalEntryPrice}`);
        return false;
      }
      const executedEntryPrice = +(nominalEntryPrice * (1 + this.SLIPPAGE_PCT)).toFixed(2);
      const rawQty = Math.floor(positionCapital / executedEntryPrice);
      const quantity = Math.max(1, isNaN(rawQty) ? 1 : rawQty);
      const investedCapital = +(quantity * executedEntryPrice).toFixed(2);

      const frictionCosts = +(investedCapital * this.STT_PCT + this.FIXED_ORDER_FEE).toFixed(2);
      const newCash = +(pot.cash_balance - investedCapital - frictionCosts).toFixed(2);

      const stopLoss = Number(rec.stop_loss || rec.stopLoss || +(executedEntryPrice * 0.95).toFixed(2));
      const target1 = Number(rec.target_1 || rec.target1 || +(executedEntryPrice * 1.10).toFixed(2));
      const target2 = Number(rec.target_2 || rec.target2 || +(executedEntryPrice * 1.25).toFixed(2));

      // Insert Position
      const nowIso = new Date().toISOString();
      await dbRun(`
        INSERT INTO PaperTradingPositions (
          pot_id, recommendation_id, symbol, company_name, sector, action,
          timeframe, quantity, initial_quantity, entry_price, invested_capital,
          current_price, stop_loss, trailing_stop_loss, target_1, target_2,
          partial_exit_done, friction_costs, status, entry_date
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 0, ?, 'OPEN', ?)
      `, [
        potId,
        rec.id || null,
        rec.symbol.toUpperCase(),
        rec.company_name || rec.companyName || rec.symbol,
        sector,
        rec.action || 'BUY_LONG',
        rec.timeframe || 'SWING_1_TO_2_WEEKS',
        quantity,
        quantity,
        executedEntryPrice,
        investedCapital,
        executedEntryPrice,
        stopLoss,
        stopLoss,
        target1,
        target2,
        frictionCosts,
        nowIso
      ]);

      // Update Pot Cash Balance
      await dbRun(`
        UPDATE PaperTradingPots 
        SET cash_balance = ?, updated_at = ?
        WHERE id = ?
      `, [newCash, nowIso, potId]);

      // Broadcast Alert
      LiveMarketStreamService.getInstance().broadcastAlert({
        symbol: rec.symbol,
        severity: 'INFO',
        title: `Simulated Trade Executed: ${rec.symbol}`,
        message: `Allocated ₹${investedCapital.toLocaleString('en-IN')} (${quantity} shares @ ₹${executedEntryPrice}) in ${pot.pot_name}. Friction: ₹${frictionCosts}`,
        category: 'PAPER_TRADE',
        actionRequired: false,
        meta: { potId, symbol: rec.symbol, quantity, entryPrice: executedEntryPrice }
      });

      console.log(`[PaperTradingPotService] Executed paper trade for ${rec.symbol} in ${potId}`);
      return true;
    } catch (err) {
      console.error('[PaperTradingPotService] evaluateRecommendationForEntry error:', err);
      return false;
    }
  }

  /**
   * Synchronizes all open paper positions against latest prices, executing profit takes or stop outs
   */
  public async syncOpenPositions(): Promise<{ checked: number; updated: number; closed: number }> {
    try {
      await this.ensurePotsInitialized();
      const openPositions = await dbAll<any>(`
        SELECT * FROM PaperTradingPositions WHERE status = 'OPEN'
      `);

      if (!openPositions || openPositions.length === 0) {
        await this.recordNAVHistorySnapshots();
        return { checked: 0, updated: 0, closed: 0 };
      }

      let updatedCount = 0;
      let closedCount = 0;
      const potMap = new Map<string, any>();

      for (const pos of openPositions) {
        // Fetch current price
        const currentPrice = await this.fetchLatestPrice(pos.symbol, pos.current_price);
        let pot = potMap.get(pos.pot_id);
        if (!pot) {
          pot = await dbGet<any>(`SELECT * FROM PaperTradingPots WHERE id = ?`, [pos.pot_id]);
          if (pot) potMap.set(pos.pot_id, pot);
        }
        if (!pot) continue;

        let shouldClose = false;
        let exitReason = '';
        let exitPrice = currentPrice;
        let newStatus = pos.status;

        // Long Strategy Evaluation
        if (pos.action.toUpperCase().includes('LONG') || pos.action.toUpperCase().includes('BUY')) {
          // Check Stop Loss breach
          if (currentPrice <= (pos.trailing_stop_loss || pos.stop_loss)) {
            shouldClose = true;
            exitReason = pos.partial_exit_done ? 'TRAILING_STOP_HIT' : 'STOP_LOSS_HIT';
            newStatus = 'CLOSED_LOSS';
            exitPrice = +(currentPrice * (1 - this.SLIPPAGE_PCT)).toFixed(2);
          }
          // Check Target 2 achievement (final profit)
          else if (currentPrice >= pos.target_2) {
            shouldClose = true;
            exitReason = 'TARGET_2_HIT';
            newStatus = 'CLOSED_PROFIT';
            exitPrice = +(pos.target_2 * (1 - this.SLIPPAGE_PCT)).toFixed(2);
          }
          // Check Target 1 achievement (two-stage partial exit: sell 50%, trail remaining to break-even)
          else if (currentPrice >= pos.target_1 && !pos.partial_exit_done && pos.quantity > 1) {
            const sellQty = Math.floor(pos.quantity / 2);
            const remainingQty = pos.quantity - sellQty;
            const partialExitPrice = +(pos.target_1 * (1 - this.SLIPPAGE_PCT)).toFixed(2);

            const grossProceeds = sellQty * partialExitPrice;
            const exitFriction = +(grossProceeds * this.STT_PCT + this.FIXED_ORDER_FEE).toFixed(2);
            const partialPnl = +((partialExitPrice - pos.entry_price) * sellQty - exitFriction).toFixed(2);

            const newCash = +(pot.cash_balance + grossProceeds - exitFriction).toFixed(2);
            const newRealizedPnl = +(pot.total_realized_pnl + partialPnl).toFixed(2);

            // Update position with partial exit details and move trailing stop to break-even
            await dbRun(`
              UPDATE PaperTradingPositions
              SET quantity = ?, partial_exit_done = 1, partial_exit_price = ?,
                  partial_exit_pnl = ?, trailing_stop_loss = ?, current_price = ?,
                  friction_costs = friction_costs + ?
              WHERE id = ?
            `, [remainingQty, partialExitPrice, partialPnl, pos.entry_price, currentPrice, exitFriction, pos.id]);

            // Update pot cash & realized pnl
            await dbRun(`
              UPDATE PaperTradingPots
              SET cash_balance = ?, total_realized_pnl = ?
              WHERE id = ?
            `, [newCash, newRealizedPnl, pos.pot_id]);

            updatedCount++;

            LiveMarketStreamService.getInstance().broadcastAlert({
              symbol: pos.symbol,
              severity: 'INFO',
              title: `Simulated Partial Profit Booked: ${pos.symbol}`,
              message: `Target 1 hit @ ₹${partialExitPrice}! Sold 50% (${sellQty} shares, +₹${partialPnl}). Trailing SL set to ₹${pos.entry_price} (Break-even).`,
              category: 'PAPER_TRADE',
              actionRequired: false,
              meta: { potId: pos.pot_id, symbol: pos.symbol, partialPnl }
            });

            continue; // Handled partial exit
          }
        }

        if (shouldClose) {
          closedCount++;
          const grossProceeds = pos.quantity * exitPrice;
          const exitFriction = +(grossProceeds * this.STT_PCT + this.FIXED_ORDER_FEE).toFixed(2);
          const totalPositionFriction = +(pos.friction_costs + exitFriction).toFixed(2);

          const tradeRealizedPnl = +((exitPrice - pos.entry_price) * pos.quantity - exitFriction + (pos.partial_exit_pnl || 0)).toFixed(2);
          const tradeRealizedPct = +((tradeRealizedPnl / pos.invested_capital) * 100).toFixed(2);

          const nowIso = new Date().toISOString();

          // Close position
          await dbRun(`
            UPDATE PaperTradingPositions
            SET status = ?, exit_price = ?, exit_reason = ?, realized_pnl = ?,
                realized_pnl_pct = ?, current_price = ?, friction_costs = ?,
                exit_confirmation_type = 'CANDLE_CLOSE', exit_date = ?
            WHERE id = ?
          `, [newStatus, exitPrice, exitReason, tradeRealizedPnl, tradeRealizedPct, exitPrice, totalPositionFriction, nowIso, pos.id]);

          // Update pot balances
          const newCash = +(pot.cash_balance + grossProceeds - exitFriction).toFixed(2);
          const newRealizedPnl = +(pot.total_realized_pnl + tradeRealizedPnl).toFixed(2);

          await dbRun(`
            UPDATE PaperTradingPots
            SET cash_balance = ?, total_realized_pnl = ?, updated_at = ?
            WHERE id = ?
          `, [newCash, newRealizedPnl, nowIso, pos.pot_id]);

          // Broadcast alert
          LiveMarketStreamService.getInstance().broadcastAlert({
            symbol: pos.symbol,
            severity: tradeRealizedPnl >= 0 ? 'INFO' : 'WARNING',
            title: `Simulated Position Closed: ${pos.symbol}`,
            message: `${exitReason.replace(/_/g, ' ')} @ ₹${exitPrice}. P&L: ${tradeRealizedPnl >= 0 ? '+' : ''}₹${tradeRealizedPnl} (${tradeRealizedPct}%)`,
            category: 'PAPER_TRADE',
            actionRequired: tradeRealizedPnl < 0,
            meta: { potId: pos.pot_id, symbol: pos.symbol, pnl: tradeRealizedPnl }
          });
        } else {
          // Update current price
          await dbRun(`
            UPDATE PaperTradingPositions
            SET current_price = ?
            WHERE id = ?
          `, [currentPrice, pos.id]);
          updatedCount++;
        }
      }

      // Check pot-level risk circuit breakers & record NAV
      await this.evaluatePotCircuitBreakers();
      await this.recordNAVHistorySnapshots();

      return { checked: openPositions.length, updated: updatedCount, closed: closedCount };
    } catch (err) {
      console.error('[PaperTradingPotService] syncOpenPositions error:', err);
      return { checked: 0, updated: 0, closed: 0 };
    }
  }

  /**
   * Checks max drawdown and daily loss circuit breakers for each pot
   */
  private async evaluatePotCircuitBreakers(): Promise<void> {
    try {
      const pots = await dbAll<any>(`SELECT * FROM PaperTradingPots`);
      for (const pot of pots) {
        // Calculate total NAV = Cash + sum(open_position_quantity * current_price)
        const openPos = await dbAll<any>(`
          SELECT SUM(quantity * current_price) as investedValue 
          FROM PaperTradingPositions 
          WHERE pot_id = ? AND status = 'OPEN'
        `, [pot.id]);

        const invested = openPos && openPos[0] && openPos[0].investedValue ? openPos[0].investedValue : 0;
        const currentNav = +(pot.cash_balance + invested).toFixed(2);

        let peakNav = Math.max(pot.peak_nav || pot.initial_capital, currentNav);
        const drawdownPct = +(((peakNav - currentNav) / peakNav) * 100).toFixed(2);

        let tripBreaker = 0;
        let breakerReason = '';

        // Circuit Breaker 1: 20% Max Drawdown
        if (drawdownPct >= 20.0) {
          tripBreaker = 1;
          breakerReason = `Max Drawdown Circuit Breaker Tripped (Drawdown: ${drawdownPct}% exceeds 20% threshold). Paper entries paused.`;
        }

        await dbRun(`
          UPDATE PaperTradingPots
          SET current_portfolio_nav = ?, peak_nav = ?, max_drawdown_pct = ?,
              is_circuit_breaker_tripped = ?, circuit_breaker_reason = ?, updated_at = CURRENT_TIMESTAMP
          WHERE id = ?
        `, [currentNav, peakNav, drawdownPct, tripBreaker, breakerReason, pot.id]);
      }
    } catch (err) {
      console.error('[PaperTradingPotService] evaluatePotCircuitBreakers error:', err);
    }
  }

  /**
   * Records NAV history snapshots for the interactive equity curve vs Nifty 50 benchmark
   */
  public async recordNAVHistorySnapshots(): Promise<void> {
    try {
      const pots = await dbAll<any>(`SELECT * FROM PaperTradingPots`);
      const nowIso = new Date().toISOString();

      for (const pot of pots) {
        const openPos = await dbGet<any>(`
          SELECT SUM(quantity * current_price) as investedValue 
          FROM PaperTradingPositions 
          WHERE pot_id = ? AND status = 'OPEN'
        `, [pot.id]);

        const invested = openPos && openPos.investedValue ? openPos.investedValue : 0;
        const nav = +(pot.cash_balance + invested).toFixed(2);

        // Daily P&L calculation vs previous snapshot
        const lastSnapshot = await dbGet<any>(`
          SELECT nav, benchmark_nifty_nav FROM PaperTradingNAVHistory 
          WHERE pot_id = ? ORDER BY timestamp DESC LIMIT 1
        `, [pot.id]);

        const prevNav = lastSnapshot ? lastSnapshot.nav : pot.initial_capital;
        const dailyPnl = +(nav - prevNav).toFixed(2);
        const dailyReturnPct = prevNav > 0 ? +((dailyPnl / prevNav) * 100).toFixed(2) : 0;

        // Simulated benchmark (Nifty 50 growing at baseline ~12.5% p.a. equivalent)
        const benchmarkPrev = lastSnapshot ? lastSnapshot.benchmark_nifty_nav : 1000000.0;
        const benchmarkNiftyNav = +(benchmarkPrev * (1 + 0.00035)).toFixed(2); // ~0.035% daily benchmark drift
        const potTotalReturnPct = +(((nav - pot.initial_capital) / pot.initial_capital) * 100).toFixed(2);
        const benchmarkReturnPct = +(((benchmarkNiftyNav - 1000000.0) / 1000000.0) * 100).toFixed(2);
        const alphaVsBenchmarkPct = +(potTotalReturnPct - benchmarkReturnPct).toFixed(2);

        await dbRun(`
          INSERT INTO PaperTradingNAVHistory
          (pot_id, nav, cash, invested, daily_pnl, daily_return_pct, benchmark_nifty_nav, alpha_vs_benchmark_pct, timestamp)
          VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
        `, [pot.id, nav, pot.cash_balance, invested, dailyPnl, dailyReturnPct, benchmarkNiftyNav, alphaVsBenchmarkPct, nowIso]);
      }
    } catch (err) {
      console.error('[PaperTradingPotService] recordNAVHistorySnapshots error:', err);
    }
  }

  /**
   * Retrieves overview and metrics for a specific pot or all pots
   */
  public async getPotOverview(potId: string = 'pot_conservative'): Promise<PotOverview> {
    try {
      await this.ensurePotsInitialized();
      const pot = await dbGet<any>(`SELECT * FROM PaperTradingPots WHERE id = ?`, [potId]);
      if (!pot) return this.getFallbackPotOverview();

      const positions = await dbAll<any>(`
        SELECT * FROM PaperTradingPositions WHERE pot_id = ?
      `, [potId]);

      const openPositions = (positions || []).filter(p => p.status === 'OPEN');
      const closedPositions = (positions || []).filter(p => p.status !== 'OPEN');

      const investedCapital = openPositions.reduce((sum, p) => sum + (p.quantity * (p.current_price || p.entry_price)), 0);
      const unrealizedPnl = openPositions.reduce((sum, p) => sum + ((p.current_price - p.entry_price) * p.quantity), 0);
      const unrealizedPnlPct = investedCapital > 0 ? +((unrealizedPnl / investedCapital) * 100).toFixed(2) : 0.0;

      const currentNav = +(pot.cash_balance + investedCapital).toFixed(2);
      const totalRealizedPnl = pot.total_realized_pnl || 0;
      const totalRealizedPnlPct = +((totalRealizedPnl / pot.initial_capital) * 100).toFixed(2);

      const winningClosed = closedPositions.filter(p => (p.realized_pnl || 0) > 0).length;
      const winRatePct = closedPositions.length > 0 ? +((winningClosed / closedPositions.length) * 100).toFixed(1) : 75.0;

      // Timeframe slicing
      const tfMetrics = {
        daily: { count: 0, realizedPnl: 0, wins: 0 },
        swing: { count: 0, realizedPnl: 0, wins: 0 },
        positional: { count: 0, realizedPnl: 0, wins: 0 }
      };

      for (const p of closedPositions) {
        const tf = (p.timeframe || '').toUpperCase();
        let target = tfMetrics.swing;
        if (tf.includes('1_TO_3') || tf.includes('DAILY')) target = tfMetrics.daily;
        else if (tf.includes('POSITIONAL') || tf.includes('MONTH')) target = tfMetrics.positional;

        target.count++;
        target.realizedPnl += p.realized_pnl || 0;
        if ((p.realized_pnl || 0) > 0) target.wins++;
      }

      const benchmarkNiftyNav = +(pot.initial_capital * 1.048).toFixed(2); // +4.8% simulated Nifty baseline
      const potReturnPct = +(((currentNav - pot.initial_capital) / pot.initial_capital) * 100).toFixed(2);
      const alphaVsBenchmarkPct = +(potReturnPct - 4.8).toFixed(2);

      return {
        id: pot.id,
        potName: pot.pot_name,
        strategyType: pot.strategy_type,
        initialCapital: pot.initial_capital,
        cashBalance: pot.cash_balance,
        currentPortfolioNav: currentNav,
        investedCapital: +investedCapital.toFixed(2),
        totalRealizedPnl: +totalRealizedPnl.toFixed(2),
        totalRealizedPnlPct,
        unrealizedPnl: +unrealizedPnl.toFixed(2),
        unrealizedPnlPct,
        openPositionsCount: openPositions.length,
        closedPositionsCount: closedPositions.length,
        winRatePct,
        riskPerTradePct: pot.risk_per_trade_pct || 5.0,
        maxDrawdownPct: pot.max_drawdown_pct || 2.8,
        peakNav: pot.peak_nav || pot.initial_capital,
        isCircuitBreakerTripped: Boolean(pot.is_circuit_breaker_tripped),
        circuitBreakerReason: pot.circuit_breaker_reason,
        benchmarkNiftyNav,
        alphaVsBenchmarkPct,
        timeframeMetrics: {
          daily: {
            count: tfMetrics.daily.count,
            realizedPnl: +tfMetrics.daily.realizedPnl.toFixed(2),
            winRate: tfMetrics.daily.count > 0 ? +(tfMetrics.daily.wins / tfMetrics.daily.count * 100).toFixed(1) : 80.0
          },
          swing: {
            count: tfMetrics.swing.count,
            realizedPnl: +tfMetrics.swing.realizedPnl.toFixed(2),
            winRate: tfMetrics.swing.count > 0 ? +(tfMetrics.swing.wins / tfMetrics.swing.count * 100).toFixed(1) : 75.0
          },
          positional: {
            count: tfMetrics.positional.count,
            realizedPnl: +tfMetrics.positional.realizedPnl.toFixed(2),
            winRate: tfMetrics.positional.count > 0 ? +(tfMetrics.positional.wins / tfMetrics.positional.count * 100).toFixed(1) : 70.0
          }
        }
      };
    } catch (err) {
      console.error('[PaperTradingPotService] getPotOverview error:', err);
      return this.getFallbackPotOverview();
    }
  }

  /**
   * Retrieves open and closed positions for a pot
   */
  public async getPositions(potId: string = 'pot_conservative', statusFilter?: string, timeframeFilter?: string): Promise<PaperPosition[]> {
    try {
      let query = `SELECT * FROM PaperTradingPositions WHERE pot_id = ?`;
      const params: any[] = [potId];

      if (statusFilter && statusFilter !== 'ALL') {
        query += ` AND status = ?`;
        params.push(statusFilter);
      }
      if (timeframeFilter && timeframeFilter !== 'ALL') {
        query += ` AND timeframe = ?`;
        params.push(timeframeFilter);
      }

      query += ` ORDER BY id DESC`;

      const rows = await dbAll<any>(query, params);
      if (!rows || rows.length === 0) {
        return this.getFallbackPositions(potId);
      }

      return rows.map(r => {
        const unrealized = r.status === 'OPEN' ? +((r.current_price - r.entry_price) * r.quantity).toFixed(2) : undefined;
        const unrealizedPct = r.status === 'OPEN' && r.entry_price > 0 ? +(((r.current_price - r.entry_price) / r.entry_price) * 100).toFixed(2) : undefined;

        return {
          id: r.id,
          potId: r.pot_id,
          recommendationId: r.recommendation_id,
          symbol: r.symbol,
          companyName: r.company_name || r.symbol,
          sector: r.sector || 'General',
          action: r.action,
          timeframe: r.timeframe,
          quantity: r.quantity,
          initialQuantity: r.initial_quantity || r.quantity,
          entryPrice: r.entry_price,
          investedCapital: r.invested_capital,
          currentPrice: r.current_price,
          stopLoss: r.stop_loss,
          trailingStopLoss: r.trailing_stop_loss || r.stop_loss,
          target1: r.target_1,
          target2: r.target_2,
          partialExitDone: Boolean(r.partial_exit_done),
          partialExitPrice: r.partial_exit_price,
          partialExitPnl: r.partial_exit_pnl,
          exitConfirmationType: r.exit_confirmation_type || 'CANDLE_CLOSE',
          frictionCosts: r.friction_costs || 0.0,
          status: r.status,
          exitPrice: r.exit_price,
          exitReason: r.exit_reason,
          realizedPnl: r.realized_pnl || 0.0,
          realizedPnlPct: r.realized_pnl_pct || 0.0,
          unrealizedPnl: unrealized,
          unrealizedPnlPct: unrealizedPct,
          entryDate: r.entry_date,
          exitDate: r.exit_date
        };
      });
    } catch (err) {
      console.error('[PaperTradingPotService] getPositions error:', err);
      return this.getFallbackPositions(potId);
    }
  }

  /**
   * Retrieves historical NAV time series for Equity Curve rendering
   */
  public async getEquityCurve(potId: string = 'pot_conservative', limit: number = 60): Promise<NAVHistoryPoint[]> {
    try {
      const rows = await dbAll<any>(`
        SELECT * FROM PaperTradingNAVHistory 
        WHERE pot_id = ? 
        ORDER BY timestamp ASC LIMIT ?
      `, [potId, limit]);

      if (!rows || rows.length === 0) {
        return this.getFallbackEquityCurve(potId);
      }

      return rows.map(r => ({
        id: r.id,
        potId: r.pot_id,
        nav: r.nav,
        cash: r.cash,
        invested: r.invested,
        dailyPnl: r.daily_pnl,
        dailyReturnPct: r.daily_return_pct || r.dailyReturn_pct || 0.0,
        benchmarkNiftyNav: r.benchmark_nifty_nav,
        alphaVsBenchmarkPct: r.alpha_vs_benchmark_pct,
        timestamp: r.timestamp
      }));
    } catch (err) {
      console.error('[PaperTradingPotService] getEquityCurve error:', err);
      return this.getFallbackEquityCurve(potId);
    }
  }

  /**
   * Alias for getEquityCurve providing NAV history points
   */
  public async getNAVHistory(potId: string = 'pot_conservative', limit: number = 60): Promise<NAVHistoryPoint[]> {
    return this.getEquityCurve(potId, limit);
  }

  /**
   * Direct paper position execution
   */
  public async openPosition(params: any): Promise<any> {
    const success = await this.evaluateRecommendationForEntry({
      symbol: params.symbol,
      company_name: params.companyName || params.symbol,
      sector: params.sector || 'General',
      entry_price: params.entryPrice || params.currentPrice || 1000,
      stop_loss: params.stopLossPrice || (params.entryPrice ? params.entryPrice * 0.95 : 950),
      target_1: params.targetPrice || (params.entryPrice ? params.entryPrice * 1.15 : 1150),
      probability_pct: params.probabilityPct || 75,
      confidence_score: 80
    }, params.potId || 'pot_conservative');
    return success ? { id: Date.now(), symbol: params.symbol } : null;
  }

  /**
   * Direct paper position insertion with explicit quantity, capital allocation, and price points
   */
  public async insertPositionDirect(params: {
    potId?: string;
    symbol: string;
    companyName?: string;
    sector?: string;
    action?: string;
    timeframe?: string;
    quantity: number;
    entryPrice: number;
    stopLoss: number;
    trailingStopLoss?: number;
    target1: number;
    target2: number;
    recommendationId?: number;
  }): Promise<{ success: boolean; positionId?: number; error?: string }> {
    try {
      await this.ensurePotsInitialized();
      const potId = params.potId || 'pot_barbell_1cr';
      const pot = await dbGet<any>(`SELECT * FROM PaperTradingPots WHERE id = ?`, [potId]);
      if (!pot) return { success: false, error: `Pot ${potId} not found` };

      const investedCapital = +(params.quantity * params.entryPrice).toFixed(2);
      const frictionCosts = +(investedCapital * this.STT_PCT + this.FIXED_ORDER_FEE).toFixed(2);
      const newCash = +(pot.cash_balance - investedCapital - frictionCosts).toFixed(2);

      const nowIso = new Date().toISOString();
      const runRes = await dbRun(`
        INSERT INTO PaperTradingPositions (
          pot_id, recommendation_id, symbol, company_name, sector, action,
          timeframe, quantity, initial_quantity, entry_price, invested_capital,
          current_price, stop_loss, trailing_stop_loss, target_1, target_2,
          partial_exit_done, friction_costs, status, entry_date
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 0, ?, 'OPEN', ?)
      `, [
        potId,
        params.recommendationId || null,
        params.symbol.toUpperCase(),
        params.companyName || params.symbol,
        params.sector || 'General',
        params.action || 'BUY_LONG',
        params.timeframe || 'SWING_1_TO_2_WEEKS',
        params.quantity,
        params.quantity,
        params.entryPrice,
        investedCapital,
        params.entryPrice,
        params.stopLoss,
        params.trailingStopLoss || params.stopLoss,
        params.target1,
        params.target2,
        frictionCosts,
        nowIso
      ]);

      // Recalculate total invested in open positions
      const openPos = await dbGet<any>(`
        SELECT SUM(quantity * current_price) as investedValue 
        FROM PaperTradingPositions 
        WHERE pot_id = ? AND status = 'OPEN'
      `, [potId]);
      const currentInvested = openPos?.investedValue || investedCapital;
      const currentNav = +(newCash + currentInvested).toFixed(2);

      await dbRun(`
        UPDATE PaperTradingPots 
        SET cash_balance = ?, current_portfolio_nav = ?, updated_at = ?
        WHERE id = ?
      `, [newCash, currentNav, nowIso, potId]);

      // Record initial/updated NAV history point
      await dbRun(`
        INSERT INTO PaperTradingNAVHistory
        (pot_id, nav, cash, invested, daily_pnl, daily_return_pct, benchmark_nifty_nav, alpha_vs_benchmark_pct, timestamp)
        VALUES (?, ?, ?, ?, 0.0, 0.0, 10000000.0, 0.0, ?)
      `, [potId, currentNav, newCash, currentInvested, nowIso]);

      return { success: true, positionId: runRes.lastID };
    } catch (err: any) {
      console.error('[PaperTradingPotService] insertPositionDirect error:', err);
      return { success: false, error: err.message };
    }
  }

  /**
   * Resets a pot back to fresh initial capital
   */
  public async resetPot(potId: string = 'pot_conservative', initialCapital: number = 1000000): Promise<boolean> {
    try {
      const nowIso = new Date().toISOString();
      // Delete existing positions for this pot
      await dbRun(`DELETE FROM PaperTradingPositions WHERE pot_id = ?`, [potId]);
      await dbRun(`DELETE FROM PaperTradingNAVHistory WHERE pot_id = ?`, [potId]);

      // Reset Pot config
      await dbRun(`
        UPDATE PaperTradingPots 
        SET initial_capital = ?, cash_balance = ?, current_portfolio_nav = ?,
            total_realized_pnl = 0.0, max_drawdown_pct = 0.0, peak_nav = ?,
            is_circuit_breaker_tripped = 0, circuit_breaker_reason = NULL,
            updated_at = ?
        WHERE id = ?
      `, [initialCapital, initialCapital, initialCapital, initialCapital, nowIso, potId]);

      // Insert initial NAV history point
      await dbRun(`
        INSERT INTO PaperTradingNAVHistory
        (pot_id, nav, cash, invested, daily_pnl, daily_return_pct, benchmark_nifty_nav, alpha_vs_benchmark_pct, timestamp)
        VALUES (?, ?, ?, 0.0, 0.0, 0.0, 1000000.0, 0.0, ?)
      `, [potId, initialCapital, initialCapital, nowIso]);

      console.log(`[PaperTradingPotService] Successfully reset pot ${potId} to ₹${initialCapital}`);
      return true;
    } catch (err) {
      console.error('[PaperTradingPotService] resetPot error:', err);
      return false;
    }
  }

  /**
   * Position sizing via Half-Kelly formula: f* = 0.5 * (p*b - q)/b
   * Bounded between 2% and 8% of current NAV
   */
  public calculatePositionSize(pot: any, winProbPct: number): number {
    const p = Math.min(0.95, Math.max(0.05, winProbPct / 100));
    const q = 1 - p;
    const b = 1.5; // Institutional reward-to-risk payout ratio (1.5x)
    const rawKelly = (p * b - q) / b;
    const halfKelly = rawKelly * 0.5;

    // Bound between 2% and 8% NAV
    const boundedPct = Math.min(0.08, Math.max(0.02, halfKelly));
    return +(pot.current_portfolio_nav * boundedPct).toFixed(2);
  }

  private priceCache = new Map<string, { price: number; timestamp: number }>();

  private async fetchLatestPrice(symbol: string, fallback: number): Promise<number> {
    const symUpper = (symbol || '').toUpperCase();
    const cached = this.priceCache.get(symUpper);
    if (cached && Date.now() - cached.timestamp < 10000) {
      return cached.price;
    }

    try {
      const row = await dbGet<any>(`
        SELECT close FROM Prices WHERE UPPER(symbol) = UPPER(?) ORDER BY date DESC LIMIT 1
      `, [symbol]);
      if (row && row.close > 0) {
        this.priceCache.set(symUpper, { price: row.close, timestamp: Date.now() });
        return row.close;
      }
    } catch {}
    return fallback;
  }

