  fibPositionPct: number; // 0% (swingLow) to 100% (swingHigh)
  fibPercent?: number;
  guidance: 'FAVOR_LONGS_ACCUMULATION' | 'NEUTRAL_WAIT' | 'FAVOR_SHORTS_TRIM_PROFITS';
