  }, 60000);

  it('retrieves singleton instance of GreenfieldRebalanceService', () => {
    expect(rebalanceService).toBeDefined();
    const instance2 = GreenfieldRebalanceService.getInstance();
    expect(instance2).toBe(rebalanceService);
  });

  it('generates a comprehensive rebalance report across family portfolios', () => {
    const report = sharedReport;

    expect(report).toBeDefined();
    expect(report.generatedAt).toBeDefined();
    expect(report.portfolioFilter).toBe('ALL');

    // Verify summary metrics
    expect(report.summary).toBeDefined();
    expect(report.summary.totalTrappedInLaggardsInr).toBeGreaterThan(0);
    expect(report.summary.totalOverconcentratedCapitalInr).toBeGreaterThan(0);
    expect(report.summary.totalPotentialTaxSavingsInr).toBeGreaterThan(0);
    expect(report.summary.totalCapitalDeployableInr).toBeGreaterThan(0);
    expect(report.summary.projected12MonthAlphaUpliftInr).toBeGreaterThan(0);
    expect(report.summary.avgAlphaUpliftPct).toBeGreaterThan(20);
    expect(report.summary.laggardCount).toBeGreaterThan(0);
    expect(report.summary.overconcentratedCount).toBeGreaterThan(0);

    // Verify diagnostics list
    expect(report.diagnostics.length).toBeGreaterThan(0);
    report.diagnostics.forEach((d: any) => {
      expect(d.symbol).toBeDefined();
      expect(d.portfolio).toBeDefined();
      expect(d.quantity).toBeGreaterThan(0);
      expect(d.currentValue).toBeGreaterThan(0);
      expect(['SEVERE_LAGGARD', 'OVER_CONCENTRATED_RUNNER', 'MODERATE_DRAG', 'CORE_COMPOUNDER']).toContain(d.classification);
      expect(['FULL_EXIT_TAX_HARVEST', 'TRIM_PROFIT_25PCT', 'TRIM_OR_MONITOR', 'HOLD_AND_COMPOUND']).toContain(d.recommendedAction);
    });
  });

  it('correctly diagnoses severe laggards like ORIANA and SONUINFRA', () => {
    const report = sharedReport;
    const oriana = report.diagnostics.find((d: any) => d.symbol === 'ORIANA');
    const sonu = report.diagnostics.find((d: any) => d.symbol === 'SONUINFRA');

    if (oriana) {
      expect(oriana.classification).toBe('SEVERE_LAGGARD');
      expect(oriana.recommendedAction).toBe('FULL_EXIT_TAX_HARVEST');
      expect(oriana.unrealizedPnlPct).toBeLessThan(-25);
      expect(oriana.futureOutlook).toContain('technical');
    }

    if (sonu) {
      expect(sonu.classification).toBe('SEVERE_LAGGARD');
      expect(sonu.recommendedAction).toBe('FULL_EXIT_TAX_HARVEST');
      expect(sonu.unrealizedPnlPct).toBeLessThan(-25);
    }
  });

  it('correctly diagnoses over-concentrated SME runners like AKIKO', () => {
    const report = sharedReport;
    const akiko = report.diagnostics.find((d: any) => d.symbol === 'AKIKO');

    if (akiko) {
      expect(akiko.classification).toBe('OVER_CONCENTRATED_RUNNER');
      expect(akiko.recommendedAction).toBe('TRIM_PROFIT_25PCT');
      expect(akiko.unrealizedPnlPct).toBeGreaterThan(50);
      expect(akiko.portfolioWeightPct).toBeGreaterThan(15);
      expect(akiko.diagnosisReason).toContain('de-risk');
    }
  });

  it('provides curated intelligent paired switches with exact tax savings and alpha uplift', () => {
    const report = sharedReport;
    expect(report.switches.length).toBeGreaterThanOrEqual(3);

    // Switch 1: ORIANA -> Waaree Energies (Secondary Stock or Open IPO)
    const switch1 = report.switches.find((s: any) => s.id === 'SWITCH_ORIANA_WAAREE');
    expect(switch1).toBeDefined();
    expect(switch1?.sourceHolding.symbol).toBe('ORIANA');
    expect(switch1?.sourceHolding.action).toBe('FULL_EXIT_TAX_HARVEST');
    expect(['UPCOMING_IPO', 'GREENFIELD_STOCK']).toContain(switch1?.destinationCandidate.type);
    expect(switch1?.destinationCandidate.symbol).toBe('WAAREEENER');
    expect(switch1?.financialMetrics.taxHarvestingSavingsInr).toBeGreaterThan(1000000); // Saves ~₹11.9 Lakhs
    expect(switch1?.financialMetrics.netAlphaYieldUpliftPct).toBeGreaterThan(50);

    // Switch 2: SONUINFRA -> SOLARINDS
    const switch2 = report.switches.find((s: any) => s.id === 'SWITCH_SONUINFRA_SOLARINDS');
    expect(switch2).toBeDefined();
    expect(switch2?.sourceHolding.symbol).toBe('SONUINFRA');
    expect(switch2?.destinationCandidate.type).toBe('GREENFIELD_STOCK');
    expect(switch2?.financialMetrics.taxHarvestingSavingsInr).toBeGreaterThan(300000);
    expect(switch2?.financialMetrics.projected12MonthNetGainInr).toBeGreaterThan(900000);

    // Switch 3: AKIKO -> TRENT/HAL
    const switch3 = report.switches.find((s: any) => s.id === 'SWITCH_AKIKO_HAL_TRENT');
    expect(switch3).toBeDefined();
    expect(switch3?.sourceHolding.symbol).toBe('AKIKO');
    expect(switch3?.sourceHolding.action).toBe('TRIM_PROFIT_25PCT');
    expect(switch3?.financialMetrics.taxHarvestingSynergy).toContain('brought-forward long-term loss buffer');
  });

  it('simulates a rebalancing switch inside the paper trading sandbox', async () => {
    const res = await rebalanceService.simulateRebalanceSwitch('SWITCH_ORIANA_WAAREE', 'pot_conservative');
    expect(res.success).toBe(true);
    expect(res.message).toContain('Successfully executed simulated switch');
    expect(res.details).toBeDefined();
    expect(res.details.sourceSymbol).toBe('ORIANA');
    expect(res.details.destinationSymbol).toBe('WAAREEENER');
    expect(res.details.taxSavingsInr).toBeGreaterThan(0);
  });

  it('gracefully handles non-existent switch ID simulation', async () => {
    const res = await rebalanceService.simulateRebalanceSwitch('NON_EXISTENT_ID');
    expect(res.success).toBe(false);
    expect(res.message).toContain('not found');
  });
});

import { describe, it, expect, beforeEach } from 'vitest';
import {
  IpoAnalysisEngine,
  IpoAnalysisRecord
} from '../../src/server/services/IpoAnalysisEngine.js';

describe('Upcoming IPO Analysis & Recommendation Engine', () => {
  let engine: IpoAnalysisEngine;

  beforeEach(() => {
    engine = IpoAnalysisEngine.getInstance();
  });

  it('retrieves the active and upcoming IPO universe with complete data models', () => {
    const ipos = engine.getUpcomingIpos();
    expect(ipos.length).toBeGreaterThanOrEqual(6);

    ipos.forEach((ipo) => {
      expect(ipo.id).toBeDefined();
      expect(ipo.companyName).toBeDefined();
      expect(ipo.symbol).toBeDefined();
      expect(ipo.sector).toBeDefined();
      expect(ipo.priceBand.max).toBeGreaterThan(ipo.priceBand.min);
      expect(ipo.lotSize).toBeGreaterThan(0);
      expect(ipo.minInvestment).toBe(ipo.priceBand.max * ipo.lotSize);
      expect(ipo.issueSize.totalCr).toBeGreaterThan(0);
      expect(ipo.issueSize.freshIssueCr + ipo.issueSize.ofsCr).toBeCloseTo(ipo.issueSize.totalCr, 0);
      expect(ipo.gmp).toBeDefined();
      expect(ipo.gmp.source).toContain('Chittorgarh');
      expect(ipo.subscription).toBeDefined();
      expect(ipo.financials).toBeDefined();
      expect(ipo.peerComparison.length).toBeGreaterThan(0);
      expect(ipo.verdict).toBeDefined();
      expect(['APPLY_HIGH_CONVICTION', 'APPLY_LISTING_GAINS', 'WATCH', 'AVOID']).toContain(ipo.verdict.action);
    });
  });

  it('correctly classifies Waaree Energies as APPLY_HIGH_CONVICTION with massive listing gains', () => {
    const waaree = engine.getIpoById('WAAREEENER');
    expect(waaree).not.toBeNull();
    expect(waaree?.verdict.action).toBe('APPLY_HIGH_CONVICTION');
    expect(waaree?.verdict.overallScore).toBeGreaterThanOrEqual(90);
    expect(waaree?.verdict.confidenceLevelPct).toBeGreaterThanOrEqual(90);
    expect(waaree?.gmp.listingGainPct).toBeGreaterThan(80);
    expect(waaree?.financials.rocePct).toBeGreaterThan(30);
    expect(waaree?.issueSize.ofsPct).toBeLessThan(25); // 83%+ Fresh capital
  });

  it('correctly classifies Hyundai Motor India as AVOID due to 100% OFS, high pricing, and negative GMP', () => {
    const hyundai = engine.getIpoById('HYUNDAI');
    expect(hyundai).not.toBeNull();
    expect(hyundai?.verdict.action).toBe('AVOID');
    expect(hyundai?.issueSize.ofsPct).toBe(100);
    expect(hyundai?.issueSize.freshIssueCr).toBe(0);
    expect(hyundai?.gmp.listingGainPct).toBeLessThan(0); // Negative GMP
    expect(hyundai?.subscription.retailTimes).toBeLessThan(1.0); // Undersubscribed
    expect(hyundai?.verdict.summaryRationale).toContain('100% OFS');
  });

  it('correctly classifies Premier Energies as APPLY_LISTING_GAINS due to >100% GMP surge', () => {
    const premier = engine.getIpoById('PREMIERENE');
    expect(premier).not.toBeNull();
    expect(premier?.verdict.action).toBe('APPLY_LISTING_GAINS');
    expect(premier?.gmp.listingGainPct).toBeGreaterThanOrEqual(100);
    expect(premier?.subscription.qibTimes).toBeGreaterThan(200);
  });

  it('correctly classifies Afcons Infrastructure as AVOID due to high OFS to service group debt', () => {
    const afcons = engine.getIpoById('AFCONS');
    expect(afcons).not.toBeNull();
    expect(afcons?.verdict.action).toBe('AVOID');
    expect(afcons?.issueSize.ofsPct).toBeGreaterThan(70);
    expect(afcons?.financials.cfoPositive).toBe(false);
  });

  it('correctly classifies NTPC Green Energy as APPLY_HIGH_CONVICTION due to 100% Fresh Issue capital', () => {
    const ntpcGreen = engine.getIpoById('NTPCGREEN');
    expect(ntpcGreen).not.toBeNull();
    expect(ntpcGreen?.verdict.action).toBe('APPLY_HIGH_CONVICTION');
    expect(ntpcGreen?.issueSize.freshIssueCr).toBe(10000);
    expect(ntpcGreen?.issueSize.ofsPct).toBe(0);
  });

  it('provides listed peer comparison matrix with comparative valuation ratios', () => {
    const swiggy = engine.getIpoById('SWIGGY');
    expect(swiggy).not.toBeNull();
    const zomatoPeer = swiggy?.peerComparison.find(p => p.company.includes('Zomato'));
    expect(zomatoPeer).toBeDefined();
    expect(zomatoPeer?.marketCapCr).toBeGreaterThan(swiggy?.peerComparison[0].marketCapCr || 0);
  });

  it('supports lookup by ID or symbol case-insensitively', () => {
    const ipo1 = engine.getIpoById('ipo_waaree_energies');
    const ipo2 = engine.getIpoById('waareeener');
    expect(ipo1).not.toBeNull();
    expect(ipo2).not.toBeNull();
    expect(ipo1?.symbol).toBe(ipo2?.symbol);
  });

  it('simulates an IPO retail application in the paper trading pot', async () => {
    const res = await engine.simulateIpoApplication({
      ipoId: 'ipo_waaree_energies',
      potId: 'pot_conservative',
      bidCategory: 'RETAIL',
      lotsCount: 1
    });

    expect(res.success).toBe(true);
    expect(res.applicationDetails).toBeDefined();
    expect(res.applicationDetails?.lotsApplied).toBe(1);
    expect(res.applicationDetails?.sharesApplied).toBe(9);
    expect(res.applicationDetails?.applicationAmount).toBe(9 * 1503);
    expect(res.applicationDetails?.estimatedListingGain).toBe(9 * 1450);
  });
});

/**
 * tests/unit/metamorphic_reasoning_invariants.test.ts
 *
 * FERE v3.2.1 Metamorphic Reasoning Invariant Suite (MR-1 through MR-14).
 *
 * v3.2.1 Expansion: Added MR-6 through MR-14 to specifically attack the
 * exact implementation weaknesses identified in the independent code-level audit:
 *
 * MR-6:  Currency mismatch MUST NOT preserve numerical equivalence
 * MR-7:  Invalid unit for metric family MUST fail Gate A (ontology check)
 * MR-8:  Absent sourceQuotedText MUST fail Gate A (quote is mandatory)
 * MR-9:  Case B restatement MUST produce SUPERSEDED + COMPARABLE (not NOT_COMPARABLE)
 * MR-10: Derived fact IDs MUST be deterministic (same inputs → same ID, no Date.now())
 * MR-11: Fail-closed replay MUST throw if rawQuantInput is missing
 * MR-12: YoY derivation MUST reject cross-metric and cross-scope inputs
 * MR-13: Undated evidence MUST NOT be historically admissible (Fail-closed boundary)
 * MR-14: Modifying ANY material raw-input field MUST alter rawInputHash
 */

import { describe, it, expect } from 'vitest';
import {
  ItasIiceReconciliationService,
  ItasQuantInput,
  IiceIntelligenceInput
} from '../../src/server/intelligence/services/ItasIiceReconciliationService';
import { TemporalReasoningEngine } from '../../src/server/intelligence/engines/TemporalReasoningEngine';
import { DecisionReplayEngine } from '../../src/server/intelligence/engines/DecisionReplayEngine';
import { FactValidationGate, CandidateFactInput } from '../../src/server/intelligence/engines/FactValidationGate';
import { NumericalNormalizationEngine } from '../../src/server/intelligence/engines/NumericalNormalizationEngine';
import { ContradictionResolutionEngine } from '../../src/server/intelligence/engines/ContradictionResolutionEngine';
import { FactDerivationEngine } from '../../src/server/intelligence/engines/FactDerivationEngine';
import { FinancialFact } from '../../src/server/intelligence/types/FinancialFact';
import { ManagementClaim } from '../../src/server/intelligence/types/ManagementClaim';

describe('FERE v3.2.1 Metamorphic Reasoning Invariants Suite (MR-1 to MR-14)', () => {
  const service = new ItasIiceReconciliationService();

  // ─────────────────────────────────────────────────────────────────────────
  // MR-1: Monotonic Threshold Scaling (preserved from v3.2)
  // ─────────────────────────────────────────────────────────────────────────
  it('MR-1: Monotonic threshold scaling: increasing score never demotes quant opportunity', () => {
    const tiers = { NONE: 0, WEAK: 1, MODERATE: 2, STRONG: 3 };

    for (let s = 0; s < 99; s += 5) {
      const qLower: ItasQuantInput = {
        symbol: 'TEST_MR1',
        strategyAgreementCount: 0,
        totalStrategiesEvaluated: 20,
        signalStrength: s,
        marketRegime: 'BULLISH',
        quantDirective: 'BUY'
      };
      const qHigher: ItasQuantInput = { ...qLower, signalStrength: s + 5 };

      const resLower = service.evaluateQuantOpportunity(qLower);
      const resHigher = service.evaluateQuantOpportunity(qHigher);

      expect(tiers[resHigher]).toBeGreaterThanOrEqual(tiers[resLower]);
    }
  });

  // ─────────────────────────────────────────────────────────────────────────
  // MR-2: Corroborating Evidence Monotonicity (preserved from v3.2)
  // ─────────────────────────────────────────────────────────────────────────
  it('MR-2: Corroborating evidence monotonicity: corroboration never weakens thesis state', () => {
    const baseQuant: ItasQuantInput = {
      symbol: 'TEST_CORROB',
      strategyAgreementCount: 16,
      totalStrategiesEvaluated: 20,
      signalStrength: 85,
      marketRegime: 'BULLISH',
      quantDirective: 'STRONG_BUY',
      decisionDate: '2024-06-30'
    };
    const baseIice: IiceIntelligenceInput = {
      symbol: 'TEST_CORROB',
      companyName: 'Test Corroboration Corp',
      marketCapTier: 'MIDCAP',
      exchangeBoard: 'MAIN_BOARD',
      walkTheTalk: {
        totalClaims: 2,
        achievedClaims: 2,
        brokenClaims: 0,
        pendingClaims: 0,
        unverifiableClaims: 0,
        grade: 'STRONG',
        sayDoRatio: 1.0,
        historicalBasis: 'PRIMARY',
        keyEvidencedExamples: []
      },
      contradictions: [],
      evaluatedBreakers: [],
      unknowns: [],
      recentEvents: [],
      evidenceCount: 3
    };

    const baseState = service.reconcile(baseQuant, baseIice);
    expect(baseState.thesisState).toBe('SUPPORTED');

    const corroboratingIice: IiceIntelligenceInput = {
      ...baseIice,
      evidenceCount: baseIice.evidenceCount + 5,
      walkTheTalk: { ...baseIice.walkTheTalk, totalClaims: 4, achievedClaims: 4 }
    };
    const corroboratedState = service.reconcile(baseQuant, corroboratingIice);
    expect(corroboratedState.thesisState).toBe('SUPPORTED');

    const contradictoryIice: IiceIntelligenceInput = {
      ...baseIice,
      contradictions: [{
        contradictionId: 'C_HIGH_1',
        issuerNseSymbol: 'TEST_CORROB',
        severity: 'HIGH',
        type: 'CLAIM_VS_RESULT',
        description: 'Material margin discrepancy',
        divergenceDetails: {},
        leftEvidenceId: 'EV_1',
        rightEvidenceId: 'EV_2',
        supportingEvidenceIds: [],
        materiality: 'HIGH',
        status: 'OPEN',
        detectedAt: '2026-09-15',
        createdAt: '2026-09-15'
      }]
    };
    const challengedState = service.reconcile(baseQuant, contradictoryIice);
    expect(challengedState.thesisState).toBe('CHALLENGED');
  });

  // ─────────────────────────────────────────────────────────────────────────
  // MR-3: Support Dependency Sensitivity (preserved from v3.2)
  // ─────────────────────────────────────────────────────────────────────────
  it('MR-3: Support dependency sensitivity: removing all evidence demotes from SUPPORTED', () => {
    const quant: ItasQuantInput = {
      symbol: 'TEST_DEP',
      strategyAgreementCount: 16,
      totalStrategiesEvaluated: 20,
      signalStrength: 85,
      marketRegime: 'BULLISH',
      quantDirective: 'STRONG_BUY',
      decisionDate: '2024-06-30'
    };
    const supportedIice: IiceIntelligenceInput = {
      symbol: 'TEST_DEP',
      companyName: 'Test Dependency Corp',
      marketCapTier: 'MIDCAP',
      exchangeBoard: 'MAIN_BOARD',
      walkTheTalk: {
        totalClaims: 2,
        achievedClaims: 2,
        brokenClaims: 0,
        pendingClaims: 0,
        unverifiableClaims: 0,
        grade: 'STRONG',
        sayDoRatio: 1.0,
        historicalBasis: 'PRIMARY',
        keyEvidencedExamples: []
      },
      contradictions: [],
      evaluatedBreakers: [],
      unknowns: [],
      recentEvents: [],
      evidenceCount: 4
    };
    const supportedDecision = service.reconcile(quant, supportedIice);
    expect(supportedDecision.thesisState).toBe('SUPPORTED');

    const strippedIice: IiceIntelligenceInput = {
      ...supportedIice,
      evidenceCount: 0,
      walkTheTalk: {
        ...supportedIice.walkTheTalk,
        totalClaims: 0,
        achievedClaims: 0,
        grade: 'INSUFFICIENT_HISTORY'
      }
    };
    const strippedDecision = service.reconcile(quant, strippedIice);
    expect(strippedDecision.thesisState).toBe('UNRESOLVED');
