      rawInputFacts: [
        {
          factId: 'FACT_001', issuerSymbol: 'TATASTEEL', metric: 'REVENUE',
          metricFamily: 'REVENUE', value: 1250, unit: 'INR_CRORE',
          scope: 'CONSOLIDATED', measurementType: 'FLOW',
