      {kind:"INDEX_MEMBERSHIP",sourceId:"idx-abc",sourceType:"exchange",availableAt:"2020-01-06T10:00:00+05:30",
       indexName:"NIFTY50",symbol:"ABC",effectiveFrom:"2020-01-06"}
