    const sizing = calculateAdaptivePositionSize({
      portfolioEquity: 10000000, entryPrice: 1000, stopPrice: 990,
      riskFraction: 0.005, maxPortfolioFraction: 0.20, advValue: 100000000,
      allowUnconstrainedConcentrationForResearch: true
    });
    expect(sizing.capitalPctOfPortfolio).toBeGreaterThan(8.0);
  });

  it('23. TC-QUALITY-003: Empirical redundancy reduces correlated consensus score', () => {
    const input = {
      strategyCount: 2, independentBuckets: 2, relativeStrengthPercentile: 90, volumeRatio: 2.0,
      regimeScore: 1, liquidityScore: 1, eventRiskScore: 1, forensicScore: 1, valuationScore: 1, riskReward: 3.5
    };
    const correlatedFactor = calculateEvidenceAdjustment(['S1','S9'], 10).redundancyFactor;
    const independentFactor = calculateEvidenceAdjustment(['S6','S18'], 10).redundancyFactor;
    const correlated = calculateSignalQuality(input, undefined, correlatedFactor);
    const independent = calculateSignalQuality(input, undefined, independentFactor);
    expect(correlatedFactor).toBeLessThan(1);
    expect(correlated).toBeLessThan(independent);
  });

  it('24. TC-AUDIT-003: Tampering with auditable fields invalidates the record hash', async () => {
    const { generateSignalAuditRecord } = await import('../../src/server/services/SignalQualityOverlay.js');
    const decision: any = { approved: true, status: 'APPROVED', qualityScore: 80, independentBucketsCount: 2, activeBuckets: ['BUCKET_A_TREND','BUCKET_B_VOLUME_ACCUMULATION'], rejectionReasons: [] };
    const record = generateSignalAuditRecord({ symbol: 'TESTAUDIT', companyName: 'Test', strategyIds: ['S6','S18'], regime: 'BULLISH_EXPANSION', relativeStrengthPercentile: 90, volumeRatio: 2, riskReward: 3, gapRiskTooHigh: false, sectorExposurePct: 5, portfolioExposurePct: 5, overlayDecision: decision });
    expect(verifySignalAuditRecord(record)).toBe(true);
    const fields: (keyof typeof record)[] = ['symbol','regime','signalQualityScore','volumeRatio','riskReward','executionTicketAllowed'];
    for (const field of fields) {
      const tampered: any = { ...record };
      tampered[field] = typeof tampered[field] === 'number' ? tampered[field] + 1 : (typeof tampered[field] === 'boolean' ? !tampered[field] : `${tampered[field]}-TAMPERED`);
      expect(verifySignalAuditRecord(tampered)).toBe(false);
    }
  });

  it('25. TC-STATE-003: Capital preservation accepts numeric and object inputs', () => {
    expect(evaluateCapitalPreservationState(100, 94).currentState).toBe('DEFENSIVE');
    expect(evaluateCapitalPreservationState({ peakToTroughDrawdownPct: 8.0 }).currentState).toBe('CAPITAL_PRESERVATION');
    expect(evaluateCapitalPreservationState({ dailyLossPct: 6.0 }).currentState).toBe('MODEL_REVIEW');
  });

});

/**
 * Institutional Smart Money Concepts (SMC 13 Pillars) Engine Test Suite
 * Tests mathematical rigor, swing structure, liquidity sweeps, order blocks,
 * fair value gaps, displacement, premium/discount zones, and checklist scoring.
 */

import { describe, test, expect } from 'vitest';
import {
  SmartMoneyConceptsEngine,
  Candle
} from '../../src/server/services/SmartMoneyConceptsEngine.js';

describe('Institutional Smart Money Concepts (SMC) Engine - 13 Pillars', () => {
  const smc = SmartMoneyConceptsEngine.getInstance();

  // Helper to construct candle sequences easily
  function createCandle(
    index: number,
    open: number,
    high: number,
    low: number,
    close: number,
    volume: number = 100000
  ): Candle {
    const d = new Date(2026, 0, index + 1);
    return {
      date: d.toISOString().split('T')[0],
      open,
      high,
      low,
      close,
      volume
    };
  }

  // ─────────────────────────────────────────────────────────────────────────
  // PILLAR 1: Market Structure (HH, HL, LH, LL, BOS, CHOCH, MSS)
  // ─────────────────────────────────────────────────────────────────────────
  test('Pillar 1: Identifies Swing Highs, Swing Lows, and Structure Progression', () => {
    // 15 candles creating a clear Swing High at bar 4 (price 120) and Swing Low at bar 8 (price 90)
    const candles: Candle[] = [
      createCandle(0, 100, 105, 98, 104),
      createCandle(1, 104, 110, 102, 108),
      createCandle(2, 108, 115, 106, 114),
      createCandle(3, 114, 118, 112, 116),
      createCandle(4, 116, 125, 115, 122), // Swing High peak = 125
      createCandle(5, 122, 123, 110, 112),
      createCandle(6, 112, 114, 104, 105),
      createCandle(7, 105, 106, 95, 96),
      createCandle(8, 96, 98, 88, 92),     // Swing Low trough = 88
      createCandle(9, 92, 102, 90, 100),
      createCandle(10, 100, 108, 98, 106),
      createCandle(11, 106, 115, 104, 112),
      createCandle(12, 112, 120, 110, 118),
      createCandle(13, 118, 128, 116, 126), // Breaks 125 -> Bullish BOS!
      createCandle(14, 126, 130, 124, 129)
    ];

    const swings = smc.detectSwings(candles, 2);
    expect(swings.length).toBeGreaterThanOrEqual(2);

    const swingHigh = swings.find(s => s.type === 'SWING_HIGH');
    const swingLow = swings.find(s => s.type === 'SWING_LOW');
    expect(swingHigh).toBeDefined();
    expect(swingLow).toBeDefined();
    expect(swingHigh!.price).toBe(125);
    expect(swingLow!.price).toBe(88);

    const breaks = smc.detectStructureBreaks(candles, swings);
    const breakEvent = breaks.find(b => (b.type === 'BOS' || b.type === 'CHOCH') && b.direction === 'BULLISH');
    expect(breakEvent).toBeDefined();
    expect(breakEvent!.brokenPrice).toBe(125);
  });

  // ─────────────────────────────────────────────────────────────────────────
  // PILLAR 2: Liquidity Mapping (BSL, SSL, Equal Highs EQH, Equal Lows EQL)
  // ─────────────────────────────────────────────────────────────────────────
  test('Pillar 2: Identifies Buy-side Liquidity (BSL) and Sell-side Liquidity (SSL) Pools', () => {
    const candles: Candle[] = [
      createCandle(0, 500, 510, 495, 505),
      createCandle(1, 505, 530, 502, 528), // Peak 1 = 530
      createCandle(2, 528, 529, 510, 512),
      createCandle(3, 512, 515, 480, 482), // Trough = 480
      createCandle(4, 482, 510, 481, 508),
      createCandle(5, 508, 530.5, 505, 527), // Peak 2 = 530.5 (Equal High with Peak 1 within 0.15%)
      createCandle(6, 527, 528, 515, 518),
      createCandle(7, 518, 522, 510, 514)
    ];

    const swings = smc.detectSwings(candles, 1);
    const pools = smc.identifyLiquidityPools(candles, swings);

    expect(pools.length).toBeGreaterThanOrEqual(2);
    const bslPool = pools.find(p => p.type === 'BSL' || p.type === 'EQH');
    const sslPool = pools.find(p => p.type === 'SSL');

    expect(bslPool).toBeDefined();
    expect(sslPool).toBeDefined();
    expect(bslPool!.price).toBeGreaterThan(520);
    expect(sslPool!.price).toBeLessThanOrEqual(485);
  });

  // ─────────────────────────────────────────────────────────────────────────
  // PILLAR 3: Liquidity Sweep / Takeout (Wick Manipulation before Real Move)
  // ─────────────────────────────────────────────────────────────────────────
  test('Pillar 3: Validates Wick Sweep of SSL with Body Rejection Inside the Pool', () => {
    // Bar 2 forms SSL at 400.
    // Bar 5 sweeps SSL: low dips to 392 (wick penetration), but close is 404 (closes back above 400).
    const candles: Candle[] = [
      createCandle(0, 420, 425, 415, 418),
      createCandle(1, 418, 420, 400, 402), // Prior low = 400
      createCandle(2, 402, 405, 400, 403), // SSL pool established at 400
      createCandle(3, 403, 415, 402, 412),
      createCandle(4, 412, 414, 402, 404),
      createCandle(5, 404, 406, 392, 405), // Wick sweep! low=392 < 400, close=405 >= 400
      createCandle(6, 405, 422, 404, 420)  // Immediate displacement upward
    ];

    const pools = [
      {
        id: 'POOL_SSL_TEST',
        type: 'SSL' as const,
        price: 400,
        rangeHigh: 402,
        rangeLow: 398,
        date: '2026-01-02',
        status: 'UNTOUCHED' as const,
        description: 'Test SSL pool'
      }
    ];

    const sweeps = smc.detectSweeps(candles, pools);
    expect(sweeps.length).toBeGreaterThanOrEqual(1);

    const sweep = sweeps[0];
    expect(sweep.direction).toBe('BULLISH'); // Swept SSL -> Bullish setup
    expect(sweep.extremePrice).toBe(392);
    expect(sweep.sweptPrice).toBe(400);
    expect(sweep.reversalConfirmed).toBe(true);
  });

  // ─────────────────────────────────────────────────────────────────────────
  // PILLAR 4: Order Blocks (Bullish OB & Bearish OB with Displacement Validation)
  // ─────────────────────────────────────────────────────────────────────────
  test('Pillar 4: Detects High Quality Bullish Order Block with Mean Threshold', () => {
    // Bar 2 is bearish (open 100, close 95).
    // Bar 3 and 4 have massive upward displacement (95 -> 112) with volume surge.
    const candles: Candle[] = [
      createCandle(0, 102, 104, 100, 101, 100000),
      createCandle(1, 101, 102, 98, 99, 110000),
      createCandle(2, 99, 100, 94, 95, 120000), // Last bearish candle before strong run
      createCandle(3, 95, 106, 95, 105, 400000), // Huge displacement candle
      createCandle(4, 105, 114, 104, 112, 450000), // Follow-through
      createCandle(5, 112, 113, 108, 109, 150000)
    ];

    const obs = smc.detectOrderBlocks(candles, []);
    const bullishOb = obs.find(o => o.type === 'BULLISH_OB');

    expect(bullishOb).toBeDefined();
    expect(bullishOb!.topPrice).toBe(100);
    expect(bullishOb!.bottomPrice).toBe(94);
    // Mean threshold is midpoint between 99 and 95 = 97
    expect(bullishOb!.meanThreshold).toBeCloseTo(97, 1);
    expect(bullishOb!.causedDisplacement).toBe(true);
    expect(bullishOb!.qualityScore).toBeGreaterThanOrEqual(60);
  });

  // ─────────────────────────────────────────────────────────────────────────
  // PILLAR 5: Breaker Blocks (Failed OB Flipped into Opposite S/R)
  // ─────────────────────────────────────────────────────────────────────────
  test('Pillar 5: Transforms Mitigated/Violated Order Block into a Breaker Block', () => {
    // Bar 1 creates Bullish OB [90 - 95].
    // Later bar 4 crashes through 90 down to 82, flipping it to a Bearish Breaker Block!
    const candles: Candle[] = [
      createCandle(0, 94, 96, 92, 93),
      createCandle(1, 93, 95, 90, 91, 100000), // Bearish candle
      createCandle(2, 91, 104, 91, 103, 350000), // Strong displacement up (OB formed)
      createCandle(3, 103, 104, 98, 99, 120000),
      createCandle(4, 99, 100, 82, 84, 450000), // Violent crash penetrating through 90!
      createCandle(5, 84, 88, 83, 86, 120000)
    ];

    const obs = smc.detectOrderBlocks(candles, []);
    const breaker = obs.find(o => o.type === 'BREAKER');
    expect(breaker).toBeDefined();
    expect(breaker!.status).toBe('FAILED_INTO_BREAKER');
  });

  // ─────────────────────────────────────────────────────────────────────────
  // PILLAR 6: Fair Value Gaps (FVG 3-Candle Imbalance & Mitigation Tracking)
  // ─────────────────────────────────────────────────────────────────────────
  test('Pillar 6: Detects Bullish FVG (Candle 1 High < Candle 3 Low)', () => {
    // Candle 1: High = 102
    // Candle 2: Big expansion up (102 -> 115)
    // Candle 3: Low = 108
    // Imbalance gap exists between 102 and 108!
    const candles: Candle[] = [
      createCandle(0, 98, 102, 96, 100),  // Candle 1: high = 102
      createCandle(1, 100, 116, 100, 115), // Candle 2: big displacement
      createCandle(2, 115, 120, 108, 118), // Candle 3: low = 108 (Gap: 102 to 108)
      createCandle(3, 118, 119, 114, 116)
    ];

    const fvgs = smc.detectFairValueGaps(candles);
    const bullishFvg = fvgs.find(f => f.type === 'BULLISH_FVG');

    expect(bullishFvg).toBeDefined();
    expect(bullishFvg!.bottomPrice).toBe(102);
    expect(bullishFvg!.topPrice).toBe(108);
    expect(bullishFvg!.consequentEncroachment).toBeCloseTo(105, 1); // Midpoint
    expect(bullishFvg!.status).toBe('OPEN');
  });

  // ─────────────────────────────────────────────────────────────────────────
  // PILLAR 7: Displacement Engine (Body Ratio >= 60%, Volume Surge >= 1.25x)
  // ─────────────────────────────────────────────────────────────────────────
  test('Pillar 7: Computes Candle Displacement Metrics Accurately', () => {
    // Open 100, High 106, Low 99.5, Close 105.5
    // Body = 5.5, Range = 6.5 -> Body Ratio = 84.6% >= 60%
    // Volume = 300,000 vs avg 150,000 -> 2.0x >= 1.25x
    const candle = createCandle(0, 100, 106, 99.5, 105.5, 300000);
    const avgVol = 150000;

    const displacement = smc.calculateDisplacement(candle, avgVol);
    expect(displacement.isDisplacement).toBe(true);
    expect(displacement.direction).toBe('BULLISH');
    expect(displacement.bodyToRangeRatio).toBeGreaterThanOrEqual(0.75);
    expect(displacement.volumeMultiplier).toBe(2.0);
  });

  // ─────────────────────────────────────────────────────────────────────────
  // PILLAR 8: Premium vs. Discount (Fibonacci 50% Equilibrium Dealing Range)
  // ─────────────────────────────────────────────────────────────────────────
  test('Pillar 8: Identifies Discount Zone (<50%) and Premium Zone (>50%)', () => {
    // Dealing range: Low = 100, High = 200, Equilibrium = 150
    // Current price = 130 (Fib 30% -> DISCOUNT zone, optimal for institutional longs)
    const candles: Candle[] = [
      createCandle(0, 120, 125, 100, 110), // Low 100
      createCandle(1, 110, 200, 108, 195), // High 200
      createCandle(2, 195, 198, 128, 130)  // CMP = 130
    ];

    const pd = smc.calculatePremiumDiscount(candles, 10);
    expect(pd.rangeLow).toBe(100);
    expect(pd.rangeHigh).toBe(200);
    expect(pd.equilibrium50).toBe(150);
    expect(pd.fibPercent).toBeCloseTo(30, 0);
    expect(pd.currentZone).toBe('DISCOUNT');
    expect(pd.recommendedBias).toBe('LOOK_FOR_LONGS');
  });

  // ─────────────────────────────────────────────────────────────────────────
  // PILLAR 9: Inducement (IDM Retail Trap Identification)
  // ─────────────────────────────────────────────────────────────────────────
  test('Pillar 9: Flags Inducement Swing Traps Ahead of Major Liquidity Pools', () => {
    const candles: Candle[] = [
      createCandle(0, 500, 520, 495, 515),
      createCandle(1, 515, 550, 510, 545), // Major High 550
      createCandle(2, 545, 548, 480, 485), // Major Low 480
      createCandle(3, 485, 502, 483, 498), // Minor bounce / IDM swing at 502
      createCandle(4, 498, 500, 475, 478)  // Sweeps past 480 to 475
    ];

    const swings = smc.detectSwings(candles, 1);
    const pools = smc.identifyLiquidityPools(candles, swings);
    const idmPool = pools.find(p => p.type === 'INDUCEMENT' || p.type === 'SSL');
    expect(idmPool).toBeDefined();
  });

  // ─────────────────────────────────────────────────────────────────────────
  // PILLAR 10: SMT Divergence (Intermarket Non-Confirmation)
  // ─────────────────────────────────────────────────────────────────────────
  test('Pillar 10: Detects Bullish SMT Divergence (Stock Holds HL while Benchmark Makes LL)', () => {
    // 12 bars to satisfy 10-bar lookback
    const stockCandles: Candle[] = [];
    const benchmarkCandles: Candle[] = [];

    for (let i = 0; i < 12; i++) {
      stockCandles.push(createCandle(i, 100, 105, 95, 100));
      benchmarkCandles.push(createCandle(i, 20000, 20100, 19900, 20000));
    }

    // Bar 11 (last candle): Stock sweeps lower low to 90 (< 95), Benchmark holds higher low at 19950 (>= 19900)
    stockCandles[11] = createCandle(11, 98, 100, 90, 96);
    benchmarkCandles[11] = createCandle(11, 20000, 20100, 19950, 20050);

    const smt = smc.detectSmtDivergence(stockCandles, benchmarkCandles, 'TCS', 'NIFTY50');
    expect(smt.detected).toBe(true);
    expect(smt.type).toBe('BULLISH_SMT');
    expect(smt.description).toContain('Bullish SMT Divergence');
  });

  // ─────────────────────────────────────────────────────────────────────────
  // PILLAR 11: 10-Second SMC Checklist (10-Point Scoring Algorithm)
  // ─────────────────────────────────────────────────────────────────────────
  test('Pillar 11: Evaluates 10-Second Institutional Checklist Strictly', () => {
    const syntheticCandles = smc.generateSyntheticCandles('RELIANCE', 60);
    const analysis = smc.analyzeStock('RELIANCE', syntheticCandles);

    expect(analysis.checklist).toBeDefined();
    expect(analysis.checklist.score).toBeGreaterThanOrEqual(0);
    expect(analysis.checklist.score).toBeLessThanOrEqual(10);
    expect(analysis.checklist.items).toHaveProperty('htfStructureConfirmed');
    expect(analysis.checklist.items).toHaveProperty('liquiditySwept');
    expect(analysis.checklist.items).toHaveProperty('favorableLocation');
    expect(analysis.checklist.items).toHaveProperty('displacementOccurred');
    expect(analysis.checklist.items).toHaveProperty('structureConfirmedMssOrBos');
    expect(analysis.checklist.items).toHaveProperty('logicalInvalidationStop');
    expect(analysis.checklist.items).toHaveProperty('riskRewardGe2');
  });

  // ─────────────────────────────────────────────────────────────────────────
  // PILLAR 12 & 13: Full SMC Trade Model (Entry, Stop Loss beyond Sweep, Targets, R:R)
  // ─────────────────────────────────────────────────────────────────────────
  test('Pillar 12 & 13: Generates High-Probability Trade Model with Proper R:R', () => {
    const syntheticCandles = smc.generateSyntheticCandles('INFY', 60);
    const analysis = smc.analyzeStock('INFY', syntheticCandles);

    expect(analysis.tradeModel).toBeDefined();
    expect(analysis.tradeModel.setupType).toBeDefined();

    if (analysis.tradeModel.setupType === 'HIGH_PROBABILITY_LONG') {
      expect(analysis.tradeModel.stopLoss).toBeLessThan(analysis.cmp);
      expect(analysis.tradeModel.target1).toBeGreaterThan(analysis.cmp);
      expect(analysis.tradeModel.target2).toBeGreaterThan(analysis.tradeModel.target1);
      expect(analysis.tradeModel.riskRewardRatio).toBeGreaterThanOrEqual(1.5);
      expect(analysis.tradeModel.triggerReason).toContain('SMC Long Setup');
    }
  });

  // ─────────────────────────────────────────────────────────────────────────
  // INTEGRATION: analyzeSymbol and scanUniverse Work Reliably
  // ─────────────────────────────────────────────────────────────────────────
  test('Integration: scanUniverse runs multi-scrip scan and returns sorted results', async () => {
    const symbols = ['RELIANCE', 'TCS', 'HDFCBANK'];
    const results = await smc.scanUniverse(symbols);

    expect(results.length).toBe(3);
    for (const r of results) {
      expect(r.symbol).toBeDefined();
      expect(r.cmp).toBeGreaterThan(0);
      expect(r.checklist.score).toBeGreaterThanOrEqual(0);
      expect(r.marketStructure).toBeDefined();
      expect(r.premiumDiscount).toBeDefined();
    }

    // Must be sorted descending by Checklist Score, then by R:R
    for (let i = 0; i < results.length - 1; i++) {
      const a = results[i];
      const b = results[i + 1];
      if (a.checklist.score === b.checklist.score) {
        expect(a.tradeModel.riskRewardRatio).toBeGreaterThanOrEqual(b.tradeModel.riskRewardRatio);
      } else {
        expect(a.checklist.score).toBeGreaterThanOrEqual(b.checklist.score);
      }
    }
  });
});

/**
 * test_cc9_cohort_verification.test.ts
 *
 * Verification test suite for cc9 Portfolio Indian Equities Cohort.
 * Verifies that all 48 Indian stock dossiers conform 100% to:
 * 1. FERE v3.2.1 Canonical Dossier Architecture (11 canonical JSON files per issuer)
 * 2. Gate A Fact Validation (all checks valid, strict numerical binding, 2-15 char tickers including LT & NH)
 * 3. Cold-Storage Deterministic Replay Invariance (isMatch === true, zero divergence)
 * 4. Reconciliation Engine Semantics (ITAS + IICE thesis states and allocation directives)
 * 5. Intelligence Governance & Contradiction Vetoes (PAYTM Section 35A veto, RBLBANK asset quality divergence)
 * 6. SQLite Storage Lineage (cc9_cohort.db integrity)
 */

import { describe, it, expect } from 'vitest';
import * as fs from 'fs';
import * as path from 'path';
import sqlite3 from 'sqlite3';
import { FactValidationGate } from '../../src/server/intelligence/engines/FactValidationGate.js';
import { DecisionReplayEngine } from '../../src/server/intelligence/engines/DecisionReplayEngine.js';

const CC9_DIR = path.resolve(process.cwd(), 'data/cc9_cohort');
const DB_PATH = path.resolve(CC9_DIR, 'cc9_cohort.db');

export const EXPECTED_48_SYMBOLS = [
  'SOLARINDS', 'LAURUSLABS', 'HIRECT', 'UNOMINDA', 'BHARTIARTL', 'POLYCAB',
  'FEDERALBNK', 'JGCHEM', 'MAZDOCK', 'LT', 'CDSL', 'RELIANCE',
  'HDFCBANK', 'AZAD', 'ETERNAL', 'DIVISLAB', 'GANECOS', 'HAL',
  'RAJRATAN', 'PAYTM', 'GROWW', 'PIDILITIND', 'ZENTEC', 'NH',
  'HOMEFIRST', 'BAJFINANCE', 'BLUEJET', 'M&M', 'BEL', 'APLAPOLLO',
  'CGPOWER', 'GOKEX', 'SBIFUN', 'EPL', 'DIXON', 'OLECTRA',
  'SBIN', 'RBLBANK', 'BANKBARODA', 'KPITTECH', 'ARE&M', 'TATACONSUM',
  'BAJAJHFL', 'TATAPOWER', 'TINNARUBR', 'TATAMOTORS', 'MEESHO', 'FRATELLIVI'
];

const CANONICAL_DOSSIER_FILES = [
  'company.json',
  'source-manifest.json',
  'evidence.json',
  'facts.json',
  'claims.json',
  'events.json',
  'contradictions.json',
  'breaker-evaluation.json',
  'itas-input.json',
  'thesis.json',
  'investment-brief.json'
];

describe('cc9 Portfolio Indian Equities FERE v3.2.1 Cohort Verification Suite', () => {
  it('Cohort Universe: Exactly 48 Indian listed equities present in cc9_cohort directory', () => {
    expect(fs.existsSync(CC9_DIR)).toBe(true);

    const entries = fs.readdirSync(CC9_DIR).filter((e) => {
      const fullPath = path.join(CC9_DIR, e);
      return fs.statSync(fullPath).isDirectory();
    });

    expect(entries.sort()).toEqual([...EXPECTED_48_SYMBOLS].sort());
    expect(entries.length).toBe(48);
  });

  it('Dossier Completeness: All 48 issuers contain all 11 canonical JSON files', () => {
    for (const sym of EXPECTED_48_SYMBOLS) {
      const symbolDir = path.join(CC9_DIR, sym);
      for (const requiredFile of CANONICAL_DOSSIER_FILES) {
        const filePath = path.join(symbolDir, requiredFile);
        expect(fs.existsSync(filePath), `Missing ${requiredFile} for ${sym}`).toBe(true);
        const stat = fs.statSync(filePath);
        expect(stat.size).toBeGreaterThan(0);
      }
    }
  });

  it('ISIN & Country Invariant: All 48 issuers have Indian ISINs (INE prefix) and Indian headquarters', () => {
    for (const sym of EXPECTED_48_SYMBOLS) {
      const companyPath = path.join(CC9_DIR, sym, 'company.json');
      const company = JSON.parse(fs.readFileSync(companyPath, 'utf8'));

      expect(company.symbol).toBe(sym);
      expect(company.isin.startsWith('INE'), `${sym} ISIN must start with INE`).toBe(true);
      expect(company.headquarters.toLowerCase().includes('india'), `${sym} HQ must be in India`).toBe(true);
    }
  });

  it('Gate A Conformance: Every canonical fact in every dossier passes all Gate A deterministic checks', () => {
    for (const sym of EXPECTED_48_SYMBOLS) {
      const factsPath = path.join(CC9_DIR, sym, 'facts.json');
      const facts = JSON.parse(fs.readFileSync(factsPath, 'utf8'));
      expect(facts.length).toBeGreaterThan(0);

      for (const fact of facts) {
        const report = FactValidationGate.validate({
          factId: fact.factId,
          issuerSymbol: fact.issuerSymbol,
          metric: fact.metric,
          metricFamily: fact.metricFamily,
          value: fact.value,
          unit: fact.unit,
          scope: fact.scope,
          measurementType: fact.measurementType,
          asOfDate: fact.asOfDate,
          sourceEvidenceId: fact.sourceEvidenceId,
          sourceQuotedText: fact.sourceQuotedText
        });

        expect(report.isValid, `Fact ${fact.factId} for ${sym} failed Gate A: ${report.rejectionReasons.join('; ')}`).toBe(true);
        expect(report.rejectionReasons.length).toBe(0);
        expect(report.checks.datesChronologicallySound).toBe(true);
        expect(report.checks.unitConsistentWithFamily).toBe(true);
        expect(report.checks.deterministicMetricContextBinding).toBe(true);
        expect(report.metricBinding?.bindingStrength).toBe('HIGH');
      }
    }
  });

  it('Cold-Storage Deterministic Replay: All 48 briefs replay identically with zero state hash drift', () => {
    for (const sym of EXPECTED_48_SYMBOLS) {
      const briefPath = path.join(CC9_DIR, sym, 'investment-brief.json');
      const brief = JSON.parse(fs.readFileSync(briefPath, 'utf8'));

      const snapshot = brief.decisionState.decisionSnapshot;
      expect(snapshot).toBeDefined();
      expect(snapshot.canonicalStateHash).toBeDefined();
      expect(snapshot.rawInputHash).toBeDefined();
      expect(snapshot.decisionDate).toBeDefined();
      expect(snapshot.rawInputFacts).toBeDefined();
      expect(snapshot.rawInputClaims).toBeDefined();
      expect(snapshot.rawInputBreakers).toBeDefined();

      const replayResult = DecisionReplayEngine.replayFromColdStorage(snapshot);
      expect(replayResult.isMatch, `Replay failed for ${sym}: divergences = ${replayResult.divergences.join('; ')}`).toBe(true);
      expect(replayResult.divergences.length).toBe(0);
      expect(replayResult.reconstructedHash).toBe(snapshot.canonicalStateHash);
    }
  });

  it('Intelligence Governance Veto: PAYTM triggered regulatory contradiction and is BROKEN / HARD_EXCLUSION_VETO', () => {
    const briefPath = path.join(CC9_DIR, 'PAYTM', 'investment-brief.json');
    const brief = JSON.parse(fs.readFileSync(briefPath, 'utf8'));

    expect(brief.decisionState.intelligenceRisk).toBe('CRITICAL');
    expect(brief.decisionState.thesisState).toBe('BROKEN');
    expect(brief.decisionState.portfolioPolicy.directive).toBe('HARD_EXCLUSION_VETO');
    expect(brief.decisionState.portfolioPolicy.targetSizingCapRatio).toBe(0.0);
  });

  it('Intelligence Governance Veto: RBLBANK triggered asset quality contradiction and is CHALLENGED / PROHIBITED_ENTRY', () => {
    const briefPath = path.join(CC9_DIR, 'RBLBANK', 'investment-brief.json');
    const brief = JSON.parse(fs.readFileSync(briefPath, 'utf8'));

    expect(brief.decisionState.intelligenceRisk).toBe('HIGH');
    expect(brief.decisionState.thesisState).toBe('CHALLENGED');
    expect(brief.decisionState.portfolioPolicy.directive).toBe('PROHIBITED_ENTRY');
    expect(brief.decisionState.portfolioPolicy.targetSizingCapRatio).toBe(0.0);
  });

  it('Reconciliation Invariant: Remaining 46 issuers maintain clean risk and SUPPORTED thesis state', () => {
    const nonVetoedSymbols = EXPECTED_48_SYMBOLS.filter((s) => s !== 'PAYTM' && s !== 'RBLBANK');
    for (const sym of nonVetoedSymbols) {
      const briefPath = path.join(CC9_DIR, sym, 'investment-brief.json');
      const brief = JSON.parse(fs.readFileSync(briefPath, 'utf8'));

      expect(brief.decisionState.intelligenceRisk).toBe('LOW');
      expect(brief.decisionState.thesisState).toBe('SUPPORTED');
      expect(brief.decisionState.portfolioPolicy.directive).toBe('CAPPED_ALLOCATION');
      expect(brief.decisionState.portfolioPolicy.targetSizingCapRatio).toBe(0.5);
    }
  });

  it('SQLite Cohort Database Integrity: Evidence, Claims, Events, and Contradictions are populated', async () => {
    expect(fs.existsSync(DB_PATH)).toBe(true);

    const db = new sqlite3.Database(DB_PATH);
    const getCount = (table: string): Promise<number> => {
      return new Promise((resolve, reject) => {
        db.get(`SELECT COUNT(*) as cnt FROM ${table}`, (err, row: any) => {
          if (err) reject(err);
          else resolve(row.cnt);
        });
      });
    };

    const evidenceCount = await getCount('EvidenceInventory');
    const claimsCount = await getCount('ManagementClaims');
    const eventsCount = await getCount('IntelligenceEvents');
    const contraCount = await getCount('Contradictions');

    expect(evidenceCount).toBeGreaterThanOrEqual(48);
    expect(claimsCount).toBe(48);
    expect(eventsCount).toBe(48);
    expect(contraCount).toBe(2);

    await new Promise<void>((resolve) => db.close(() => resolve()));
  });

  it('Master Summary & Execution Report: Conforming and complete for all 48 issuers', () => {
    const summaryPath = path.join(CC9_DIR, 'all_cc9_summary.json');
    const reportPath = path.join(CC9_DIR, 'CC9_COHORT_EXECUTION_REPORT.md');

    expect(fs.existsSync(summaryPath)).toBe(true);
    expect(fs.existsSync(reportPath)).toBe(true);

    const summary = JSON.parse(fs.readFileSync(summaryPath, 'utf8'));
    expect(summary.length).toBe(48);

    const reportContent = fs.readFileSync(reportPath, 'utf8');
    for (const sym of EXPECTED_48_SYMBOLS) {
      expect(reportContent.includes(sym), `Report missing mention of ${sym}`).toBe(true);
    }
  });
});

import { describe, it, expect } from 'vitest';
const {
  verifyCitation,
  verifyAssertionCitation,
  isHeadingOrBoilerplate,
} = require('../../pipeline/citation-verifier.cjs');

describe('Step 2: Citation Semantics Hardening — Heading Found is Not Operational Evidence', () => {
  const sampleSectionText = `
MANAGEMENT DISCUSSION & ANALYSIS
OVERVIEW
In 2023, India's economy was on an upward trajectory, closing the year with a GDP of USD 3.73 Trn and a GDP per capita of USD 2,610, outpacing the global average growth rate of 3.2%.
The manufacturing sector saw robust growth, aided by initiatives like the Production-Linked Incentive (PLI) scheme.
OUTLOOK FOR 2024-25
The prospects of rising investment activity remain bright owing to upturn in the private capex cycle becoming steadily broad-based.
`;

  it('proves headings and titles are identified as non-substantive boilerplate', () => {
    const headings = [
      'Management Discussion and Analysis',
      'MANAGEMENT DISCUSSION & ANALYSIS',
      "Directors' Report",
      "Board's Report",
      'OVERVIEW',
      'GLOBAL ECONOMIC OVERVIEW',
      'Macroeconomic Overview',
      'INDUSTRY STRUCTURE AND DEVELOPMENTS',
      'Outlook for 2024-25',
      'Future Outlook',
      'Financial Review',
      'Cautionary Statements',
      'Annual Report 2023-24',
    ];

    for (const h of headings) {
      expect(isHeadingOrBoilerplate(h)).toBe(true);
    }
  });

  it('strictly rejects heading-only quotes as INSUFFICIENT_EVIDENCE for operational assertions', () => {
    const headingCandidate = 'MANAGEMENT DISCUSSION & ANALYSIS';

    // Even though the heading literally exists in the section, it must be REJECTED as assertion evidence!
    const result = verifyAssertionCitation('managementOutlook', headingCandidate, sampleSectionText);

    expect(result.isValid).toBe(false);
    expect(result.label).toBe('INSUFFICIENT_EVIDENCE_HEADING_ONLY');
    expect(result.reason).toContain('not sufficient evidence for operational assertion');
  });

  it('strictly rejects section title "Outlook for 2024-25" as assertion evidence without substantive body text', () => {
    const titleOnly = 'OUTLOOK FOR 2024-25';
    const result = verifyAssertionCitation('demandTone', titleOnly, sampleSectionText);

    expect(result.isValid).toBe(false);
    expect(result.label).toBe('INSUFFICIENT_EVIDENCE_HEADING_ONLY');
  });

  it('successfully validates genuine, substantive supporting operational spans', () => {
    const substantiveSpan =
      "In 2023, India's economy was on an upward trajectory, closing the year with a GDP of USD 3.73 Trn and a GDP per capita of USD 2,610, outpacing the global average growth rate of 3.2%.";

    const result = verifyAssertionCitation('demandTone', substantiveSpan, sampleSectionText);

    expect(result.isValid).toBe(true);
    expect(result.label).toBe('EXACT');
    expect(result.similarityScore).toBeGreaterThanOrEqual(0.95);
  });
});

import { describe, it, expect, beforeEach } from 'vitest';
import sqlite3 from 'sqlite3';
import { ClaimLedgerService } from '../../src/server/intelligence/services/ClaimLedgerService.js';
import { ManagementClaim } from '../../src/server/intelligence/types/ManagementClaim.js';

describe('Phase 1B: Claim Ledger & Credibility Scorecard Lifecycle', () => {
  let db: sqlite3.Database;
  let service: ClaimLedgerService;

  beforeEach(async () => {
    db = new sqlite3.Database(':memory:');
    service = new ClaimLedgerService(db);

    await new Promise<void>((resolve, reject) => {
      db.run(`
        CREATE TABLE ManagementClaims (
          claim_id TEXT PRIMARY KEY,
          symbol TEXT NOT NULL,
          issuer_bse_code TEXT,
          period TEXT NOT NULL,
          category TEXT NOT NULL,
          statement TEXT NOT NULL,
          target_metric TEXT,
          baseline_value REAL,
          expected_value REAL,
          expected_outcome TEXT,
          expected_timeframe TEXT,
          evidence_id TEXT NOT NULL,
          status TEXT NOT NULL DEFAULT 'OPEN',
          actual_outcome_metric REAL,
          actual_outcome_description TEXT,
          resolution_evidence_id TEXT,
          resolved_at TEXT,
          claim_date TEXT,
          expected_period_start TEXT,
          expected_period_end TEXT,
          evaluation_date TEXT,
          evaluation_basis TEXT,
          evaluation_evidence_id TEXT,
          created_at DATETIME DEFAULT CURRENT_TIMESTAMP
        );
      `, (err) => {
        if (err) reject(err);
        else resolve();
      });
    });
  });

  it('correctly records an open claim with evidence lineage and temporal bounds', async () => {
    const claim: Omit<ManagementClaim, 'createdAt'> = {
      claimId: 'CLM_SOLAR_001',
      issuerNseSymbol: 'SOLARINDS',
      period: 'FY24',
      category: 'CAPACITY',
      statement: 'Defense ammunition capacity to expand from 10,000 to 25,000 units by Q4-FY25.',
      targetMetric: 'CAPACITY_UNITS',
      baselineValue: 10000,
      expectedValue: 25000,
      expectedOutcome: '+150% ammunition capacity',
      expectedTimeframe: 'Q4-FY25',
      claimDate: '2024-05-15',
      expectedPeriodStart: '2024-04-01',
      expectedPeriodEnd: '2025-03-31',
      evidenceId: 'EV_DOC_SOLAR_AR24_P42',
      status: 'OPEN'
    };

    await service.recordClaim(claim);
    const claims = await service.getClaimsForIssuer('SOLARINDS');

    expect(claims).toHaveLength(1);
    expect(claims[0].claimId).toBe('CLM_SOLAR_001');
    expect(claims[0].status).toBe('OPEN');
    expect(claims[0].expectedValue).toBe(25000);
    expect(claims[0].expectedPeriodEnd).toBe('2025-03-31');
  });

  it('correctly transitions claim to ACHIEVED and computes STRONG credibility', async () => {
    // 1. First claim achieved
    await service.recordClaim({
      claimId: 'CLM_TCS_001',
      issuerNseSymbol: 'TCS',
      period: 'FY24-Q1',
      category: 'MARGIN',
      statement: 'Operating margins to hold above 25% for full year.',
      evidenceId: 'EV_TCS_01',
      status: 'OPEN'
    });
    await service.resolveClaim(
      'CLM_TCS_001',
      26.0,
      'Full year operating margin reached 26.2%',
      'EV_TCS_RES_01',
      'ACHIEVED'
    );

    // 2. Second claim achieved
    await service.recordClaim({
      claimId: 'CLM_TCS_002',
      issuerNseSymbol: 'TCS',
      period: 'FY24-Q2',
      category: 'GROWTH',
      statement: 'TCV deal bookings to exceed $10 Billion per quarter.',
      evidenceId: 'EV_TCS_02',
      status: 'OPEN'
    });
    await service.resolveClaim(
      'CLM_TCS_002',
      12.2,
      'Quarterly TCV bookings reached $12.2 Billion',
      'EV_TCS_RES_02',
      'ACHIEVED'
    );

    const scorecard = await service.getCredibilityScorecard('TCS');

    expect(scorecard.totalClaims).toBe(2);
    expect(scorecard.achievedCount).toBe(2);
    expect(scorecard.missedCount).toBe(0);
    expect(scorecard.grade).toBe('STRONG');
  });

  it('correctly flags MISSED claims and drops credibility to WEAK/MIXED', async () => {
    // 1. First claim missed
    await service.recordClaim({
      claimId: 'CLM_TEST_001',
      issuerNseSymbol: 'TESTCORP',
      period: 'FY24',
      category: 'DEBT',
      statement: 'Net debt will be reduced to zero by end of fiscal year.',
      evidenceId: 'EV_01',
      status: 'OPEN',
      expectedPeriodEnd: '2024-03-31'
    });
    await service.resolveClaim(
      'CLM_TEST_001',
      1500,
      'Net debt increased from ₹1,200 Cr to ₹1,500 Cr',
      'EV_RES_01',
      'MISSED',
      '2024-05-15'
    );

    // 2. Second claim missed
    await service.recordClaim({
      claimId: 'CLM_TEST_002',
      issuerNseSymbol: 'TESTCORP',
      period: 'FY24',
      category: 'MARGIN',
      statement: 'EBITDA margin expected at 20%',
      evidenceId: 'EV_02',
      status: 'OPEN',
      expectedPeriodEnd: '2024-03-31'
    });
    await service.resolveClaim(
      'CLM_TEST_002',
      11.5,
      'EBITDA margin collapsed to 11.5%',
      'EV_RES_02',
      'MISSED',
      '2024-05-15'
    );

    const scorecard = await service.getCredibilityScorecard('TESTCORP');

    expect(scorecard.missedCount).toBe(2);
    expect(scorecard.grade).toBe('WEAK');
  });

  it('enforces temporal constraint: rejects marking claim MISSED before expectedPeriodEnd', async () => {
    await service.recordClaim({
      claimId: 'CLM_FUTURE_001',
      issuerNseSymbol: 'FUTURE',
      period: 'FY25',
      category: 'GROWTH',
      statement: 'Targeting 20% export growth by FY26.',
      expectedPeriodEnd: '2026-03-31',
      evidenceId: 'EV_FUTURE_01',
      status: 'OPEN'
    });

    // Attempt premature resolution in 2024
    await expect(
      service.resolveClaim(
        'CLM_FUTURE_001',
        null,
        'Export growth lagging in early quarters',
        'EV_EARLY_NOTE',
        'MISSED',
        '2024-09-15'
      )
    ).rejects.toThrow(/before expected period end/);
  });

  it('returns INSUFFICIENT_HISTORY when claims evaluated are less than threshold', async () => {
    await service.recordClaim({
      claimId: 'CLM_SOLO_001',
      issuerNseSymbol: 'SOLO',
      period: 'FY24',
      category: 'GROWTH',
      statement: 'Targeting 15% revenue growth.',
      evidenceId: 'EV_01',
      status: 'OPEN'
    });

    const scorecard = await service.getCredibilityScorecard('SOLO');
    expect(scorecard.grade).toBe('INSUFFICIENT_HISTORY');
  });
});

import { describe, it, expect, beforeEach } from 'vitest';
import sqlite3 from 'sqlite3';
import { ContradictionEngine } from '../../src/server/intelligence/services/ContradictionEngine.js';
import { ManagementClaim } from '../../src/server/intelligence/types/ManagementClaim.js';

describe('Phase 1B: Contradiction Engine Invariants', () => {
  let db: sqlite3.Database;
  let engine: ContradictionEngine;

  beforeEach(async () => {
    db = new sqlite3.Database(':memory:');
    engine = new ContradictionEngine(db);

    await new Promise<void>((resolve, reject) => {
      db.run(`
        CREATE TABLE Contradictions (
          contradiction_id TEXT PRIMARY KEY,
          symbol TEXT NOT NULL,
          issuer_bse_code TEXT,
          severity TEXT NOT NULL,
          contradiction_type TEXT NOT NULL,
          claim_id TEXT,
          event_id TEXT,
          description TEXT NOT NULL,
          divergence_json TEXT,
          supporting_evidence_ids TEXT NOT NULL,
          status TEXT NOT NULL DEFAULT 'OPEN',
          materiality TEXT NOT NULL DEFAULT 'THESIS_RELEVANT',
          left_evidence_id TEXT,
          right_evidence_id TEXT,
          detected_at TEXT,
          resolved_at TEXT,
          resolution_note TEXT,
          created_at DATETIME DEFAULT CURRENT_TIMESTAMP
        );
      `, (err) => {
        if (err) reject(err);
        else resolve();
      });
    });
  });

  it('detects a CLAIM_VS_RESULT contradiction when management guidance is missed', () => {
    const claim: ManagementClaim = {
      claimId: 'CLM_GUIDANCE_01',
      issuerNseSymbol: 'SOLARINDS',
      period: 'FY24',
      category: 'MARGIN',
      statement: 'EBITDA margin expected to remain resilient above 24%.',
      targetMetric: 'EBITDA_MARGIN',
      expectedValue: 24.0,
      expectedOutcome: 'Margin >= 24%',
      evidenceId: 'EV_CONCALL_Q3',
      status: 'MISSED',
      actualOutcomeMetric: 18.2,
      actualOutcomeDescription: 'Audited EBITDA margin dropped to 18.2%',
      resolutionEvidenceId: 'EV_AUDITED_FY24',
      createdAt: new Date().toISOString()
    };

    const contradiction = engine.evaluateClaimContradiction(claim);

    expect(contradiction).not.toBeNull();
    expect(contradiction?.type).toBe('CLAIM_VS_RESULT');
    expect(contradiction?.severity).toBe('HIGH');
    expect(contradiction?.materiality).toBe('HIGH');
    expect(contradiction?.leftEvidenceId).toBe('EV_CONCALL_Q3');
    expect(contradiction?.rightEvidenceId).toBe('EV_AUDITED_FY24');
    expect(contradiction?.supportingEvidenceIds).toContain('EV_CONCALL_Q3');
    expect(contradiction?.supportingEvidenceIds).toContain('EV_AUDITED_FY24');
  });

  it('[Legacy ContradictionEngine] marks governance missed contradiction with default MEDIUM severity', () => {
    const claim: ManagementClaim = {
      claimId: 'CLM_GOV_01',
      issuerNseSymbol: 'TESTCORP',
      period: 'FY24',
      category: 'GOVERNANCE',
      statement: 'Zero promoter share pledge and clean auditor signoff guaranteed.',
      evidenceId: 'EV_AR_01',
      status: 'MISSED',
      actualOutcomeDescription: 'Promoter pledged 35% of holding; auditor resigned citing disclosure gaps',
      resolutionEvidenceId: 'EV_BSE_FILING_01',
      createdAt: new Date().toISOString()
    };

    const contradiction = engine.evaluateClaimContradiction(claim);

    expect(contradiction).not.toBeNull();
    expect(contradiction?.severity).toBe('MEDIUM');
    expect(contradiction?.leftEvidenceId).toBe('EV_AR_01');
    expect(contradiction?.rightEvidenceId).toBe('EV_BSE_FILING_01');
  });

  it('does NOT create a contradiction for ACHIEVED claims', () => {
    const claim: ManagementClaim = {
      claimId: 'CLM_ACHIEVED_01',
      issuerNseSymbol: 'SOLARINDS',
      period: 'FY24',
      category: 'GROWTH',
      statement: 'Revenue to cross ₹6,000 Cr.',
      evidenceId: 'EV_01',
      status: 'ACHIEVED',
      actualOutcomeDescription: 'Revenue recorded at ₹6,450 Cr',
      createdAt: new Date().toISOString()
    };

    const contradiction = engine.evaluateClaimContradiction(claim);
    expect(contradiction).toBeNull();
  });

  it('records and retrieves contradictions from the database with multi-evidence columns cleanly', async () => {
    const claim: ManagementClaim = {
      claimId: 'CLM_PERSIST_01',
      issuerNseSymbol: 'APARINDS',
      period: 'FY24',
      category: 'DEBT',
      statement: 'Deleveraging to continue; debt to fall by 50%.',
      evidenceId: 'EV_APAR_01',
      status: 'MISSED',
      actualOutcomeDescription: 'Short-term debt rose by 20% to fund raw material working capital',
      resolutionEvidenceId: 'EV_APAR_RES_01',
      createdAt: new Date().toISOString()
    };

    const contradiction = engine.evaluateClaimContradiction(claim)!;
    await engine.recordContradiction(contradiction);

    const retrieved = await engine.getContradictionsForIssuer('APARINDS');
    expect(retrieved).toHaveLength(1);
    expect(retrieved[0].claimId).toBe('CLM_PERSIST_01');
    expect(retrieved[0].status).toBe('OPEN');
    expect(retrieved[0].leftEvidenceId).toBe('EV_APAR_01');
    expect(retrieved[0].rightEvidenceId).toBe('EV_APAR_RES_01');
  });

  it('rejects saving contradiction if either leftEvidenceId or rightEvidenceId is missing', async () => {
    const invalidContra: any = {
      contradictionId: 'INVALID_01',
      issuerNseSymbol: 'TEST',
      severity: 'HIGH',
      type: 'CLAIM_VS_RESULT',
      description: 'Invalid contradiction lacking dual evidence',
      leftEvidenceId: 'EV_01',
      rightEvidenceId: '', // missing
      supportingEvidenceIds: [],
      status: 'OPEN',
      materiality: 'HIGH'
    };

    await expect(engine.recordContradiction(invalidContra)).rejects.toThrow(/Both leftEvidenceId and rightEvidenceId are required/);
  });
});

import { describe, it, expect } from 'vitest';
import { NEoWaveEngine, OHLCVBar } from '../../src/server/quant/NEoWaveEngine.js';

describe('Elliott Wave & NEoWave Corrective Pullback Completion Engine', () => {
  const engine = NEoWaveEngine.getInstance();

  function makeBar(date: string, open: number, high: number, low: number, close: number, volume = 100000): OHLCVBar {
    return { date, open, high, low, close, volume };
  }

  it('1. Correctly detects a completed Zigzag A-B-C pullback with 0-B breakout and faster-time reversal', () => {
    // Generate synthetic price bars:
    // Wave 1: 100 -> 200 (10 bars)
    // Wave A: 200 -> 150 (6 bars)
    // Wave B: 150 -> 175 (5 bars, 50% retrace of A)
    // Wave C: 175 -> 130 (7 bars, 0.9x of A, golden pocket of 100-200)
    // Reversal Thrust: 130 -> 180 (3 bars, faster than Wave C duration)
    const bars: OHLCVBar[] = [];
    let d = 1;
    const addBars = (start: number, end: number, count: number) => {
      const step = (end - start) / count;
      for (let i = 0; i < count; i++) {
        const val = start + step * (i + 1);
        bars.push(makeBar(`2026-08-${String(d++).padStart(2, '0')}`, val - 1, val + 2, val - 2, val));
      }
    };

    // Prior impulse 100 -> 200 (10 bars)
    addBars(100, 200, 10);
    // Wave A: 200 -> 150 (6 bars)
    addBars(200, 150, 6);
    // Wave B: 150 -> 175 (5 bars)
    addBars(150, 175, 5);
    // Wave C: 175 -> 130 (7 bars)
    addBars(175, 130, 7);
    // Reversal Thrust: 130 -> 182 (3 bars)
    addBars(130, 182, 3);

    const indicator = engine.detectCorrectivePatternCompletion(bars, undefined, 'TEST_ZIGZAG');

    expect(indicator.isCompleted).toBe(true);
    expect(['CONFIRMED_COMPLETED', 'EARLY_REVERSAL']).toContain(indicator.completionStatus);
    expect(['ZIGZAG_ABC', 'WAVE_2_GOLDEN_POCKET']).toContain(indicator.correctivePatternType);
    expect(indicator.confidenceScore).toBeGreaterThanOrEqual(75);
    expect(indicator.confirmationGates.zeroBLineBroken).toBe(true);
    expect(indicator.confirmationGates.goldenPocketSupportHeld).toBe(true);
    expect(indicator.invalidationLevel).toBeLessThanOrEqual(135);
    expect(indicator.target1Upside).toBeGreaterThan(180);
    expect(indicator.riskRewardRatio).toBeGreaterThan(0.5);
  });

  it('2. Correctly detects Wave (2) Golden Pocket Pullback (50-61.8% Retracement)', () => {
    const bars: OHLCVBar[] = [];
    let d = 1;
    const addBars = (start: number, end: number, count: number) => {
      const step = (end - start) / count;
      for (let i = 0; i < count; i++) {
        const val = start + step * (i + 1);
        bars.push(makeBar(`2026-08-${String(d++).padStart(2, '0')}`, val - 2, val + 3, val - 3, val));
      }
    };

    // Wave 1: 1000 -> 1600 (10 bars, gain = 600)
    addBars(1000, 1600, 10);
    // Wave A: 1600 -> 1350 (6 bars)
    addBars(1600, 1350, 6);
    // Wave B: 1350 -> 1480 (5 bars)
    addBars(1350, 1480, 5);
    // Wave C: 1480 -> 1250 (7 bars, 1250 is ~58% retracement of 600 point Wave 1)
    addBars(1480, 1250, 7);
    // Reversal kickoff: 1250 -> 1520 (4 bars)
    addBars(1250, 1520, 4);

    const indicator = engine.detectCorrectivePatternCompletion(bars, undefined, 'WAVE2_STOCK');

    expect(indicator.isCompleted).toBe(true);
    expect(indicator.correctivePatternType).toBe('WAVE_2_GOLDEN_POCKET');
    expect(indicator.confirmationGates.goldenPocketSupportHeld).toBe(true);
    expect(indicator.invalidationLevel).toBeLessThanOrEqual(1260);
    expect(indicator.invalidationLevel).toBeGreaterThan(1000); // Strictly above Wave 1 origin
  });

  it('3. Correctly detects Wave (4) Alternation Shallow Pullback holding above Wave 1 apex', () => {
    const bars: OHLCVBar[] = [];
    let d = 1;
    const addBars = (start: number, end: number, count: number) => {
      const step = (end - start) / count;
      for (let i = 0; i < count; i++) {
        const val = start + step * (i + 1);
        bars.push(makeBar(`2026-08-${String(d++).padStart(2, '0')}`, val - 2, val + 3, val - 3, val));
      }
    };

    // Wave 1 apex at 500 (100 -> 500)
    // Wave 3 thrust: 400 -> 1200 (length 800)
    addBars(400, 1200, 10);
    // Wave A of 4: 1200 -> 1020 (6 bars)
    addBars(1200, 1020, 6);
    // Wave B of 4: 1020 -> 1120 (5 bars)
    addBars(1020, 1120, 5);
    // Wave C of 4: 1120 -> 980 (7 bars, shallow pullback ~27.5% of Wave 3, holding well above 500)
    addBars(1120, 980, 7);
    // Wave 5 Kickoff: 980 -> 1150 (3 bars)
    addBars(980, 1150, 3);

    const indicator = engine.detectCorrectivePatternCompletion(bars, undefined, 'WAVE4_STOCK');

    expect(indicator.isCompleted).toBe(true);
    expect(indicator.correctivePatternType).toBe('WAVE_4_ALTERNATION');
    expect(indicator.confirmationGates.ruleOfAlternationValid).toBe(true);
    expect(indicator.invalidationLevel).toBeGreaterThanOrEqual(500); // No overlap with Wave 1 apex
  });

  it('4. Marks pattern as INVALIDATED when price violates structural base', () => {
    const bars: OHLCVBar[] = [];
    let d = 1;
    const addBars = (start: number, end: number, count: number) => {
      const step = (end - start) / count;
      for (let i = 0; i < count; i++) {
        const val = start + step * (i + 1);
        bars.push(makeBar(`2026-08-${String(d++).padStart(2, '0')}`, val - 1, val + 1, val - 1, val));
      }
    };

    // Prior impulse: 100 -> 200
    addBars(100, 200, 10);
    // Wave A: 200 -> 150
    addBars(200, 150, 5);
    // Wave B: 150 -> 170
    addBars(150, 170, 4);
    // Catastrophic Wave C breakdown breaching origin: 170 -> 75 (below 100)
    addBars(170, 75, 8);

    const indicator = engine.detectCorrectivePatternCompletion(bars, undefined, 'BROKEN_STOCK');

    expect(indicator.isCompleted).toBe(false);
    expect(indicator.completionStatus).toBe('INVALIDATED');
    expect(indicator.confidenceScore).toBeLessThanOrEqual(25);
  });

  it('5. Marks pattern as DEVELOPING when Wave C is ongoing and 0-B trendline is unbroken', () => {
    const bars: OHLCVBar[] = [];
    let d = 1;
    const addBars = (start: number, end: number, count: number) => {
      const step = (end - start) / count;
      for (let i = 0; i < count; i++) {
        const val = start + step * (i + 1);
        bars.push(makeBar(`2026-08-${String(d++).padStart(2, '0')}`, val - 1, val + 1, val - 1, val));
      }
    };

    // Prior impulse: 100 -> 200
    addBars(100, 200, 10);
    // Wave A: 200 -> 160
    addBars(200, 160, 5);
    // Wave B: 160 -> 185
    addBars(160, 185, 4);
    // Wave C actively falling: 185 -> 145 (no reversal bounce)
    addBars(185, 145, 6);

    const indicator = engine.detectCorrectivePatternCompletion(bars, undefined, 'FALLING_STOCK');

    expect(indicator.isCompleted).toBe(false);
    expect(indicator.completionStatus).toBe('DEVELOPING');
    expect(indicator.confirmationGates.zeroBLineBroken).toBe(false);
  });

  it('6. Seamlessly surfaces correctiveIndicator inside analyzeNEoWave()', () => {
    const bars: OHLCVBar[] = [];
    let d = 1;
    const addBars = (start: number, end: number, count: number) => {
      const step = (end - start) / count;
      for (let i = 0; i < count; i++) {
        const val = start + step * (i + 1);
        bars.push(makeBar(`2026-08-${String(d++).padStart(2, '0')}`, val - 1, val + 2, val - 2, val));
      }
    };

    // Zigzag setup
    addBars(100, 200, 10);
    addBars(200, 150, 6);
    addBars(150, 175, 5);
    addBars(175, 130, 7);
    addBars(130, 182, 3);

    const analysis = engine.analyzeNEoWave('TATATECH', bars);

    expect(analysis.correctiveIndicator).toBeDefined();
    expect(analysis.correctiveIndicator?.isCompleted).toBe(true);
    expect(analysis.currentPattern).toBe('CORRECTION_WAVE_C_COMPLETION');
    expect(analysis.wavePivots.some(p => p.label === '(C)')).toBe(true);
  });
});

import { describe, it, expect } from 'vitest';
import fs from 'fs';
import path from 'path';

describe('Workstream A: Evidence Inventory Issuer Isolation & Anti-Fallback Test', () => {
  const batchScriptPath = path.resolve(__dirname, '../../ingestion/batch_discover_evidence.cjs');
  const discoverPyPath = path.resolve(__dirname, '../../ingestion/discover_evidence.py');
  const pilotCodesPath = path.resolve(__dirname, '../../ingestion/pilot_bse_codes.json');

  it('prohibits universal hard-coded fallback BSE code (500325) in discovery runners', () => {
    const batchCode = fs.readFileSync(batchScriptPath, 'utf8');
    const pyCode = fs.readFileSync(discoverPyPath, 'utf8');

    // Asserts no line falls back to 500325 or universal scrip code
    expect(batchCode).not.toMatch(/s\.bse_code\s*\|\|\s*['"]500325['"]/);
    expect(batchCode).not.toMatch(/fallback\s*=\s*['"]500325['"]/i);
    expect(pyCode).not.toMatch(/default\s*=\s*['"]500325['"]/);
  });

  it('guarantees mutually exclusive, issuer-specific exchange codes across pilot companies', () => {
    expect(fs.existsSync(pilotCodesPath)).toBe(true);
    const codes = JSON.parse(fs.readFileSync(pilotCodesPath, 'utf8'));

    const seenBseCodes = new Set<string>();
    const multiMapped = [];

    for (const [sym, info] of Object.entries<any>(codes)) {
      if (info && info.bseCode) {
        if (seenBseCodes.has(info.bseCode)) {
          multiMapped.push({ symbol: sym, bseCode: info.bseCode });
        }
        seenBseCodes.add(info.bseCode);
      }
    }

    // Every distinct issuer must have a unique BSE code
    expect(multiMapped).toHaveLength(0);
    // Specifically verify 20MICRONS is 533022, NOT 500325
    expect(codes['20MICRONS'].bseCode).toBe('533022');
    expect(codes['3MINDIA'].bseCode).toBe('523395');
    expect(codes['63MOONS'].bseCode).toBe('526881');
  });

  it('strictly marks unresolvable issuers as SEARCH_FAILED with IDENTIFIER_UNRESOLVED', () => {
    const batchCode = fs.readFileSync(batchScriptPath, 'utf8');
    expect(batchCode).toContain('IDENTIFIER_UNRESOLVED');
    expect(batchCode).toContain('SEARCH_FAILED');
  });
});

