        metricFamily: 'REVENUE' as const,
        value: -20,
        unit: 'INR_CRORE',
        currency: 'INR',
        scope: 'CONSOLIDATED' as const,
        measurementType: 'FLOW' as const,
        sourceEvidenceId: 'EV_NEG_PAT',
        sourceQuotedText: quote,
      };

      const result = FactValidationGate.validate(revenueFact);

      expect(result.isValid).toBe(false);
    });

    it('accepts PAT binding to the negative PAT mention', () => {
      const quote =
        'During FY24, consolidated PAT was -₹20 Cr due to exceptional charges.';

      const patFact = {
        factId: 'FACT_CORRECT_PAT',
        issuerSymbol: 'TEST',
        metric: 'PAT',
        metricFamily: 'REVENUE' as const,
        value: -20,
        unit: 'INR_CRORE',
        currency: 'INR',
        scope: 'CONSOLIDATED' as const,
        measurementType: 'FLOW' as const,
        sourceEvidenceId: 'EV_NEG_PAT',
        sourceQuotedText: quote,
      };

      const result = FactValidationGate.validate(patFact);

      expect(result.isValid).toBe(true);
    });

    it('does not let a nearby Revenue mention rescue a PAT fact', () => {
      const quote =
        'Revenue was ₹180 Cr, while EBITDA was ₹180 Cr.';

      const patFact = {
        factId: 'FACT_WRONG_PAT',
        issuerSymbol: 'TEST',
        metric: 'PAT',
        metricFamily: 'REVENUE' as const,
        value: 180,
        unit: 'INR_CRORE',
        currency: 'INR',
        scope: 'CONSOLIDATED' as const,
        measurementType: 'FLOW' as const,
        sourceEvidenceId: 'EV_MULTI_01',
        sourceQuotedText: quote,
      };

      const result = FactValidationGate.validate(patFact);

      expect(result.isValid).toBe(false);
    });

    it('REGRESSION: Revenue cannot bind to negative PAT numeric mention', () => {
      const quote =
        'During FY24, consolidated PAT was -₹20 Cr due to exceptional charges.';

      const result = FactValidationGate.validate({
        factId: 'REG_NEG_PAT_AS_REVENUE',
        issuerSymbol: 'TEST',
        metric: 'REVENUE',
        metricFamily: 'REVENUE',
        value: -20,
        unit: 'INR_CRORE',
        currency: 'INR',
        scope: 'CONSOLIDATED',
        measurementType: 'FLOW',
        sourceEvidenceId: 'EV_NEG_PAT',
        sourceQuotedText: quote,
      });

      expect(result.isValid).toBe(false);
    });

    it('REGRESSION: PAT cannot bind to Revenue numeric mention', () => {
      const quote =
        'During FY24, consolidated Revenue was ₹180 Cr.';

      const result = FactValidationGate.validate({
        factId: 'REG_REVENUE_AS_PAT',
        issuerSymbol: 'TEST',
        metric: 'PAT',
        metricFamily: 'REVENUE',
        value: 180,
        unit: 'INR_CRORE',
        currency: 'INR',
        scope: 'CONSOLIDATED',
        measurementType: 'FLOW',
        sourceEvidenceId: 'EV_REV_ONLY',
        sourceQuotedText: quote,
      });

      expect(result.isValid).toBe(false);
    });
  });
});

/**
 * tests/unit/test_phase2_batches_1_and_2_verification.test.ts
 *
 * Independent Audit & Verification Test for IICE Phase 2 Batches 1 & 2 (10 Companies):
 * Batch 1: SOLARINDS, ARVSMART, NOVARTIND, BAJAJHLDNG, UNOMINDA
 * Batch 2: VMART, TATATECH, HINDCOPPER, SCI, BOROLTD
 *
 * Independent Verifications Conducted:
 * 1. Dossier Completeness: All 10 companies have complete 10-file audit packages.
 * 2. Extraction Integrity: Real documents, valid SHA-256 hashes, physical page numbers, non-empty verbatim quotes.
 * 3. Cross-Issuer Isolation: Zero cross-company citation or claim contamination.
 * 4. Temporal Semantics: Claim periods, evaluation dates, and valid basis.
 * 5. Inferred Outcomes: Correct claim lifecycle evaluations (ACHIEVED vs MISSED vs PARTIALLY_ACHIEVED).
 * 6. Dual-Evidence Symmetry: Contradictions require left/right evidence with same issuer and valid linkage.
 * 7. Breaker Trigger Accuracy: Mathematical execution of thresholds (e.g. VMART leverage > 3.0x).
 * 8. Two-Axis Reconciliation: Decoupled ITAS Quant Opportunity x IICE Intel Risk -> Reconciled Thesis State.
 * 9. Credibility Scoring Invariants: INSUFFICIENT_HISTORY for <2 evaluated claims; WEAK for multiple misses.
 */

import { describe, it, expect, beforeAll } from 'vitest';
import fs from 'fs';
import path from 'path';
import sqlite3 from 'sqlite3';

const BATCH_1_SYMBOLS = ['SOLARINDS', 'ARVSMART', 'NOVARTIND', 'BAJAJHLDNG', 'UNOMINDA'];
const BATCH_2_SYMBOLS = ['VMART', 'TATATECH', 'HINDCOPPER', 'SCI', 'BOROLTD'];
const ALL_10_SYMBOLS = [...BATCH_1_SYMBOLS, ...BATCH_2_SYMBOLS];

const COHORT_DIR = path.resolve('data', 'phase2_cohort');
const DB_PATH = path.resolve('data', 'phase2_cohort', 'iice_cohort.db');

interface CompanyDossier {
  symbol: string;
  company: any;
  sourceManifest: any[];
  evidence: any[];
  claims: any[];
  events: any[];
  contradictionPackage: any;
  contradictions: any[];
  thesis: any;
  breakerEvaluation: any[];
  itasInput: any;
  investmentBrief: any;
}

function loadDossier(symbol: string): CompanyDossier {
  const dir = path.join(COHORT_DIR, symbol);
  expect(fs.existsSync(dir), `Cohort directory for ${symbol} must exist`).toBe(true);

  const srcRaw = JSON.parse(fs.readFileSync(path.join(dir, 'source-manifest.json'), 'utf8'));
  const contraRaw = JSON.parse(fs.readFileSync(path.join(dir, 'contradictions.json'), 'utf8'));

  return {
    symbol,
    company: JSON.parse(fs.readFileSync(path.join(dir, 'company.json'), 'utf8')),
    sourceManifest: Array.isArray(srcRaw) ? srcRaw : (srcRaw.sources || []),
    evidence: JSON.parse(fs.readFileSync(path.join(dir, 'evidence.json'), 'utf8')),
    claims: JSON.parse(fs.readFileSync(path.join(dir, 'claims.json'), 'utf8')),
    events: JSON.parse(fs.readFileSync(path.join(dir, 'events.json'), 'utf8')),
    contradictionPackage: contraRaw,
    contradictions: Array.isArray(contraRaw) ? contraRaw : (contraRaw.contradictions || []),
    thesis: JSON.parse(fs.readFileSync(path.join(dir, 'thesis.json'), 'utf8')),
    breakerEvaluation: JSON.parse(fs.readFileSync(path.join(dir, 'breaker-evaluation.json'), 'utf8')),
    itasInput: JSON.parse(fs.readFileSync(path.join(dir, 'itas-input.json'), 'utf8')),
    investmentBrief: JSON.parse(fs.readFileSync(path.join(dir, 'investment-brief.json'), 'utf8'))
  };
}

describe('Independent Verification: Phase 2 Cohort Batches 1 & 2 (10 Companies)', () => {
  let dossiers: Record<string, CompanyDossier> = {};

  beforeAll(() => {
    for (const sym of ALL_10_SYMBOLS) {
      dossiers[sym] = loadDossier(sym);
    }
  });

  describe('1. File System Completeness & Schema Integrity', () => {
    it('verifies that all 10 companies have complete 10-file audit dossiers', () => {
      const requiredFiles = [
        'company.json',
        'source-manifest.json',
        'evidence.json',
        'claims.json',
        'events.json',
        'contradictions.json',
        'thesis.json',
        'breaker-evaluation.json',
        'itas-input.json',
        'investment-brief.json'
      ];

      for (const sym of ALL_10_SYMBOLS) {
        const companyDir = path.join(COHORT_DIR, sym);
        for (const file of requiredFiles) {
          const filePath = path.join(companyDir, file);
          expect(fs.existsSync(filePath), `${sym} missing ${file}`).toBe(true);
          const stat = fs.statSync(filePath);
          expect(stat.size, `${sym}/${file} must not be empty`).toBeGreaterThan(10);
        }
      }
    });

    it('verifies canonical company metadata for all 10 companies', () => {
      for (const sym of ALL_10_SYMBOLS) {
        const comp = dossiers[sym].company;
        expect(comp.symbol).toBe(sym);
        expect(comp.companyName).toBeTruthy();
        expect(comp.bseCode).toMatch(/^\d{6}$/);
        expect(comp.isin).toMatch(/^INE[A-Z0-9]{9}$/);
        expect(['LARGECAP', 'MIDCAP', 'SMALLCAP', 'MICROCAP_SME']).toContain(comp.marketCapTier);
        expect(['MAIN_BOARD', 'SME_EXCHANGE']).toContain(comp.exchangeBoard);
      }
    });
  });

  describe('2. Source & Evidence Extraction Rigor (Zero Hallucinations)', () => {
    it('verifies all source documents have authentic SHA-256 hashes, physical page counts, and filing authorities', () => {
      const sha256Regex = /^[a-f0-9]{64,66}$/;
      const validDocTypes = [
        'ANNUAL_REPORT',
        'STATUTORY_FILING',
        'CONCALL_TRANSCRIPT',
        'INVESTOR_PRESENTATION',
        'EXCHANGE_DISCLOSURE',
        'BSE_DISCLOSURE'
      ];

      for (const sym of ALL_10_SYMBOLS) {
        const sources = dossiers[sym].sourceManifest;
        expect(sources.length).toBeGreaterThanOrEqual(1);

        for (const src of sources) {
          expect(src.documentId).toMatch(/^DOC_/);
          expect(src.documentName).toBeTruthy();
          expect(validDocTypes).toContain(src.documentType);
          expect(src.documentHashSha256).toMatch(sha256Regex);
          expect(src.pageCount).toBeGreaterThan(0);
          expect(src.filingAuthority).toBeTruthy();
          expect(src.publicationDate).toMatch(/^\d{4}-\d{2}-\d{2}$/);
        }
      }
    });

    it('verifies that every evidence span is a substantive verbatim quote tied to an authentic source and page', () => {
      for (const sym of ALL_10_SYMBOLS) {
        const evidenceSpans = dossiers[sym].evidence;
        const sourceIds = new Set(dossiers[sym].sourceManifest.map(s => s.documentId));

        expect(evidenceSpans.length).toBeGreaterThanOrEqual(2);

        for (const ev of evidenceSpans) {
          expect(ev.evidenceId).toMatch(/^EV_/);
          expect(sourceIds.has(ev.documentId), `Evidence ${ev.evidenceId} links to invalid document ${ev.documentId}`).toBe(true);
          const page = ev.pagePhysical !== undefined ? ev.pagePhysical : ev.pagePhysicalNumber;
          expect(page).toBeGreaterThan(0);
          expect(ev.quotedText.length).toBeGreaterThanOrEqual(20);
        }
      }
    });

    it('verifies universal issuer isolation: zero cross-issuer evidence contamination across all 10 companies', () => {
      for (const sym of ALL_10_SYMBOLS) {
        const evidenceSpans = dossiers[sym].evidence;
        for (const ev of evidenceSpans) {
          expect(ev.issuerNseSymbol).toBe(sym);
        }

        const claims = dossiers[sym].claims;
        for (const clm of claims) {
          expect(clm.issuerNseSymbol).toBe(sym);
        }

        const events = dossiers[sym].events;
        for (const evt of events) {
          expect(evt.issuerNseSymbol).toBe(sym);
        }

        const contradictions = dossiers[sym].contradictions;
        for (const contra of contradictions) {
          expect(contra.issuerNseSymbol).toBe(sym);
        }
      }
    });
  });

  describe('3. Management Claim Lifecycle & Temporal Semantics Verification', () => {
    it('verifies that all evaluated claims have valid evaluation dates, evaluation evidence links, and substantive basis', () => {
      for (const sym of ALL_10_SYMBOLS) {
        const claims = dossiers[sym].claims;
        const evidenceIds = new Set(dossiers[sym].evidence.map(e => e.evidenceId));

        expect(claims.length).toBeGreaterThanOrEqual(1);

        for (const clm of claims) {
          expect(clm.claimId).toMatch(/^CLM_/);
          expect(clm.statement.length).toBeGreaterThan(15);
          expect(evidenceIds.has(clm.evidenceId), `Claim ${clm.claimId} primary evidence ${clm.evidenceId} missing`).toBe(true);

          if (['ACHIEVED', 'MISSED', 'PARTIALLY_ACHIEVED'].includes(clm.status)) {
            expect(clm.evaluationDate).toBeTruthy();
            expect(clm.evaluationEvidenceId).toBeTruthy();
            expect(evidenceIds.has(clm.evaluationEvidenceId), `Claim ${clm.claimId} evaluation evidence missing`).toBe(true);
            expect(clm.evaluationBasis.length).toBeGreaterThan(15);
          }
        }
      }
    });

    it('verifies Batch 1 (Clean Leaders): all evaluated claims resolve to ACHIEVED or ACHIEVED_EARLY', () => {
      for (const sym of BATCH_1_SYMBOLS) {
        const claims = dossiers[sym].claims;
        for (const clm of claims) {
          expect(['ACHIEVED', 'ACHIEVED_EARLY'], `Batch 1 company ${sym} claim ${clm.claimId} should be ACHIEVED or ACHIEVED_EARLY`).toContain(clm.status);
        }
      }
    });

    it('verifies Batch 2 (Guidance & Capex Delays): accurately identifies MISSED and PARTIALLY_ACHIEVED claims', () => {
      // 1. VMART: Store EBITDA and EBITDA margin misses
      const vmartClaims = dossiers['VMART'].claims;
      expect(vmartClaims.length).toBe(2);
      expect(vmartClaims.every(c => c.status === 'MISSED')).toBe(true);
      expect(vmartClaims[0].actualOutcomeDescription).toContain('loss');

      // 2. TATATECH: 20%+ margin target missed (delivered 18.4%)
      const tataClaims = dossiers['TATATECH'].claims;
      expect(tataClaims.length).toBe(1);
      expect(tataClaims[0].status).toBe('MISSED');
      expect(tataClaims[0].actualOutcomeDescription).toContain('18.4%');

      // 3. HINDCOPPER: Malanjkhand 5.0 MTPA delayed
      const hindClaims = dossiers['HINDCOPPER'].claims;
      expect(hindClaims.length).toBe(1);
      expect(hindClaims[0].status).toBe('MISSED');
      expect(hindClaims[0].actualOutcomeDescription).toContain('deferred');

      // 4. SCI: Disinvestment timeline missed
      const sciClaims = dossiers['SCI'].claims;
      expect(sciClaims.length).toBe(1);
      expect(sciClaims[0].status).toBe('MISSED');
      expect(sciClaims[0].evaluationBasis).toContain('DIPAM');

      // 5. BOROLTD: Capex delivered (ACHIEVED), margin lagged (PARTIALLY_ACHIEVED)
      const boroClaims = dossiers['BOROLTD'].claims;
      expect(boroClaims.length).toBe(2);
      expect(boroClaims.find(c => c.category === 'CAPEX')?.status).toBe('ACHIEVED');
      expect(boroClaims.find(c => c.category === 'MARGIN')?.status).toBe('PARTIALLY_ACHIEVED');
    });
  });

  describe('4. Contradiction Engine & Dual-Evidence Symmetry Verification', () => {
    it('verifies Batch 1 companies have ZERO active adverse contradictions', () => {
      for (const sym of BATCH_1_SYMBOLS) {
        const contras = dossiers[sym].contradictions;
        expect(contras.length).toBe(0);
        expect(dossiers[sym].contradictionPackage.activeContradictionCount).toBe(0);
        expect(dossiers[sym].contradictionPackage.status).toBe('CONFIRMED_ZERO_ADVERSE_CONTRADICTIONS');
      }
    });

    it('verifies Batch 2 companies with misses have valid, symmetric CLAIM_VS_RESULT contradictions', () => {
      for (const sym of BATCH_2_SYMBOLS) {
        const contras = dossiers[sym].contradictions;
        const evidenceIds = new Set(dossiers[sym].evidence.map(e => e.evidenceId));

        expect(contras.length, `${sym} must have exactly 1 contradiction`).toBe(1);
        const contra = contras[0];

        expect(contra.contradictionId).toMatch(/^CONTRA_/);
        expect(contra.type).toBe('CLAIM_VS_RESULT');
        expect(evidenceIds.has(contra.leftEvidenceId), `Left evidence ${contra.leftEvidenceId} must exist`).toBe(true);
        expect(evidenceIds.has(contra.rightEvidenceId), `Right evidence ${contra.rightEvidenceId} must exist`).toBe(true);
        expect(contra.leftEvidenceId).not.toBe(contra.rightEvidenceId);
        expect(contra.status).toBe('OPEN');
        expect(contra.issuerNseSymbol).toBe(sym);
      }
    });
  });

  describe('5. Thesis Breaker Execution Accuracy (Machine-Executable)', () => {
    it('verifies VMART lease-adjusted leverage breaker triggers ACTIVE status (Net Debt / EBITDA = 3.4x > 3.0x)', () => {
      const vmartBreakers = dossiers['VMART'].breakerEvaluation;
      const levBreaker = vmartBreakers.find((b: any) => b.breakerId === 'TB_VMART_LEVERAGE');
      expect(levBreaker).toBeDefined();
      expect(levBreaker.status).toBe('ACTIVE');
      expect(levBreaker.currentObservedValue).toBeGreaterThan(3.0);
      expect(levBreaker.rationale).toContain('3.4');
      expect(dossiers['VMART'].investmentBrief.decisionState.activeThesisBreakers).toBe(1);
    });

    it('verifies SOLARINDS and ARVSMART conservative leverage breakers remain INACTIVE', () => {
      // SOLARINDS: Net Debt / EBITDA 0.35x vs 2.5x threshold -> INACTIVE
      const solarBreakers = dossiers['SOLARINDS'].breakerEvaluation;
      const solarLev = solarBreakers.find((b: any) => b.breakerId === 'TB_SOLAR_LEVERAGE');
      expect(solarLev.status).toBe('INACTIVE');
      expect(solarLev.currentObservedValue).toBe(0.35);

      // ARVSMART: Net Debt / Equity -0.18x vs 0.5x threshold -> INACTIVE
      const arvBreakers = dossiers['ARVSMART'].breakerEvaluation;
      const arvLev = arvBreakers.find((b: any) => b.breakerId === 'TB_ARV_LEVERAGE');
      expect(arvLev.status).toBe('INACTIVE');
      expect(arvLev.currentObservedValue).toBe(-0.18);
    });
  });

  describe('6. Two-Axis ITAS ↔ IICE Reconciliation Contract Verification', () => {
    it('verifies Batch 1 clean compounding leaders resolve to SUPPORTED thesis states', () => {
      for (const sym of BATCH_1_SYMBOLS) {
        const brief = dossiers[sym].investmentBrief;
        expect(brief.decisionState.intelligenceRisk).toBe('LOW');
        expect(brief.decisionState.thesisState).toBe('SUPPORTED');
        expect(['STRONG', 'MODERATE']).toContain(brief.decisionState.quantOpportunity);
      }
    });

    it('verifies Batch 2 guidance miss & delay companies resolve to MIXED, CHALLENGED, or BROKEN thesis states', () => {
      // VMART: STRONG Quant x CRITICAL Risk -> BROKEN Thesis
      const vmartBrief = dossiers['VMART'].investmentBrief;
      expect(vmartBrief.decisionState.quantOpportunity).toBe('STRONG');
      expect(vmartBrief.decisionState.intelligenceRisk).toBe('CRITICAL');
      expect(vmartBrief.decisionState.thesisState).toBe('BROKEN');

      // TATATECH: STRONG Quant x MODERATE Risk -> MIXED Thesis
      const tataBrief = dossiers['TATATECH'].investmentBrief;
      expect(tataBrief.decisionState.quantOpportunity).toBe('STRONG');
      expect(tataBrief.decisionState.intelligenceRisk).toBe('MODERATE');
      expect(tataBrief.decisionState.thesisState).toBe('MIXED');

      // HINDCOPPER: STRONG Quant x HIGH Risk -> CHALLENGED Thesis
      const hindBrief = dossiers['HINDCOPPER'].investmentBrief;
      expect(hindBrief.decisionState.quantOpportunity).toBe('STRONG');
      expect(hindBrief.decisionState.intelligenceRisk).toBe('HIGH');
      expect(hindBrief.decisionState.thesisState).toBe('CHALLENGED');

      // SCI: STRONG Quant x HIGH Risk -> CHALLENGED Thesis
      const sciBrief = dossiers['SCI'].investmentBrief;
      expect(sciBrief.decisionState.quantOpportunity).toBe('STRONG');
      expect(sciBrief.decisionState.intelligenceRisk).toBe('HIGH');
      expect(sciBrief.decisionState.thesisState).toBe('CHALLENGED');

      // BOROLTD: STRONG Quant x MODERATE Risk -> MIXED Thesis
      const boroBrief = dossiers['BOROLTD'].investmentBrief;
      expect(boroBrief.decisionState.quantOpportunity).toBe('STRONG');
      expect(boroBrief.decisionState.intelligenceRisk).toBe('MODERATE');
      expect(boroBrief.decisionState.thesisState).toBe('MIXED');
    });

    it('verifies Credibility Grade calculation invariants across all 10 companies', () => {
      // Rule: Evaluated claims < 2 must strictly yield INSUFFICIENT_HISTORY
      const singleClaimSymbols = ['NOVARTIND', 'BAJAJHLDNG', 'UNOMINDA', 'ARVSMART', 'TATATECH', 'HINDCOPPER', 'SCI'];
      for (const sym of singleClaimSymbols) {
        const grade = dossiers[sym].investmentBrief.decisionState.managementCredibility;
        expect(grade, `${sym} with <2 claims must be INSUFFICIENT_HISTORY`).toBe('INSUFFICIENT_HISTORY');
      }

      // Rule: Multi-claim clean companies yield STRONG or GENERALLY_CREDIBLE
      expect(dossiers['SOLARINDS'].investmentBrief.decisionState.managementCredibility).toBe('STRONG');
      expect(dossiers['BOROLTD'].investmentBrief.decisionState.managementCredibility).toBe('GENERALLY_CREDIBLE');

      // Rule: Multi-claim missed company yields WEAK
      expect(dossiers['VMART'].investmentBrief.decisionState.managementCredibility).toBe('WEAK');
    });
  });

  describe('7. Physical Database Persistence Verification (SQLite)', () => {
    it('verifies that all claims, events, and contradictions are persisted in data/phase2_cohort/iice_cohort.db', async () => {
      expect(fs.existsSync(DB_PATH)).toBe(true);

      const db = new sqlite3.Database(DB_PATH, sqlite3.OPEN_READONLY);

      const queryCount = (sql: string, params: any[] = []): Promise<number> => {
        return new Promise((resolve, reject) => {
          db.get(sql, params, (err, row: any) => {
            if (err) reject(err);
            else resolve(row.count);
          });
        });
      };

      const totalClaims = await queryCount('SELECT count(*) as count FROM ManagementClaims');
      const totalEvents = await queryCount('SELECT count(*) as count FROM IntelligenceEvents');
      const totalContradictions = await queryCount('SELECT count(*) as count FROM Contradictions');

      expect(totalClaims).toBe(22); // Full 20-company cohort database
      expect(totalEvents).toBe(20);
      expect(totalContradictions).toBe(11);

      // Check specific symbol rows in DB
      for (const sym of ALL_10_SYMBOLS) {
        const count = await queryCount('SELECT count(*) as count FROM ManagementClaims WHERE symbol = ?', [sym]);
        expect(count, `Database must contain claims for ${sym}`).toBeGreaterThanOrEqual(1);
      }

      await new Promise<void>(resolve => db.close(() => resolve()));
    });
  });
});

/**
 * tests/unit/test_phase2_batches_1_to_3_verification.test.ts
 *
 * Independent Audit & Verification Test for IICE Phase 2 Batches 1, 2 & 3 (15 Companies):
 * Batch 1: SOLARINDS, ARVSMART, NOVARTIND, BAJAJHLDNG, UNOMINDA
 * Batch 2: VMART, TATATECH, HINDCOPPER, SCI, BOROLTD
 * Batch 3: PURVA, STLNETWORK, SENCO, GMDCLTD, 360ONE
 *
 * Independent Verifications Conducted:
 * 1. Dossier Completeness: All 15 companies have complete 10-file audit packages.
 * 2. Extraction Integrity: Real documents, valid SHA-256 hashes (64 hex), physical page numbers, verbatim quotes.
 * 3. Cross-Issuer Isolation: Zero cross-company citation or claim contamination.
 * 4. Temporal Semantics: Claim periods, evaluation dates, and valid basis.
 * 5. Leverage Breaker Accuracy: Machine execution of leverage ceilings (PURVA 5.8x > 4.5x, STL 4.2x > 3.5x).
 * 6. Dual-Evidence Symmetry: Contradictions require left/right evidence with same issuer and valid linkage.
 * 7. Two-Axis Reconciliation: Decoupled ITAS Quant Opportunity x IICE Intel Risk -> Reconciled Thesis State.
 * 8. SQLite Database Integrity: All claims, events, and contradictions persisted in data/phase2_cohort/iice_cohort.db.
 */

import { describe, it, expect, beforeAll } from 'vitest';
import fs from 'fs';
import path from 'path';
import sqlite3 from 'sqlite3';

const BATCH_1_SYMBOLS = ['SOLARINDS', 'ARVSMART', 'NOVARTIND', 'BAJAJHLDNG', 'UNOMINDA'];
const BATCH_2_SYMBOLS = ['VMART', 'TATATECH', 'HINDCOPPER', 'SCI', 'BOROLTD'];
const BATCH_3_SYMBOLS = ['PURVA', 'STLNETWORK', 'SENCO', 'GMDCLTD', '360ONE'];
const ALL_15_SYMBOLS = [...BATCH_1_SYMBOLS, ...BATCH_2_SYMBOLS, ...BATCH_3_SYMBOLS];

const COHORT_DIR = path.resolve('data', 'phase2_cohort');
const DB_PATH = path.resolve('data', 'phase2_cohort', 'iice_cohort.db');

interface CompanyDossier {
  symbol: string;
  company: any;
  sourceManifest: any[];
  evidence: any[];
  claims: any[];
  events: any[];
  contradictionPackage: any;
  contradictions: any[];
  thesis: any;
  breakerEvaluation: any[];
  itasInput: any;
  investmentBrief: any;
}

function loadDossier(symbol: string): CompanyDossier {
  const dir = path.join(COHORT_DIR, symbol);
  expect(fs.existsSync(dir), `Cohort directory for ${symbol} must exist`).toBe(true);

  const srcRaw = JSON.parse(fs.readFileSync(path.join(dir, 'source-manifest.json'), 'utf8'));
  const contraRaw = JSON.parse(fs.readFileSync(path.join(dir, 'contradictions.json'), 'utf8'));

  return {
    symbol,
    company: JSON.parse(fs.readFileSync(path.join(dir, 'company.json'), 'utf8')),
    sourceManifest: Array.isArray(srcRaw) ? srcRaw : (srcRaw.sources || []),
    evidence: JSON.parse(fs.readFileSync(path.join(dir, 'evidence.json'), 'utf8')),
    claims: JSON.parse(fs.readFileSync(path.join(dir, 'claims.json'), 'utf8')),
    events: JSON.parse(fs.readFileSync(path.join(dir, 'events.json'), 'utf8')),
    contradictionPackage: contraRaw,
    contradictions: Array.isArray(contraRaw) ? contraRaw : (contraRaw.contradictions || []),
    thesis: JSON.parse(fs.readFileSync(path.join(dir, 'thesis.json'), 'utf8')),
    breakerEvaluation: JSON.parse(fs.readFileSync(path.join(dir, 'breaker-evaluation.json'), 'utf8')),
    itasInput: JSON.parse(fs.readFileSync(path.join(dir, 'itas-input.json'), 'utf8')),
    investmentBrief: JSON.parse(fs.readFileSync(path.join(dir, 'investment-brief.json'), 'utf8'))
  };
}

describe('Independent Verification: Phase 2 Cohort Batches 1, 2 & 3 (15 Companies)', () => {
  let dossiers: Record<string, CompanyDossier> = {};

  beforeAll(() => {
    for (const sym of ALL_15_SYMBOLS) {
      dossiers[sym] = loadDossier(sym);
    }
  });

  describe('1. File System Completeness & Metadata Integrity', () => {
    it('verifies that all 15 companies have complete 10-file audit dossiers', () => {
      const requiredFiles = [
        'company.json',
        'source-manifest.json',
        'evidence.json',
        'claims.json',
        'events.json',
        'contradictions.json',
        'thesis.json',
        'breaker-evaluation.json',
        'itas-input.json',
        'investment-brief.json'
      ];

      for (const sym of ALL_15_SYMBOLS) {
        const companyDir = path.join(COHORT_DIR, sym);
        for (const file of requiredFiles) {
          const filePath = path.join(companyDir, file);
          expect(fs.existsSync(filePath), `${sym} missing ${file}`).toBe(true);
          const stat = fs.statSync(filePath);
          expect(stat.size, `${sym}/${file} must not be empty`).toBeGreaterThan(10);
        }
      }
    });

    it('verifies canonical company metadata for all 15 companies', () => {
      for (const sym of ALL_15_SYMBOLS) {
        const comp = dossiers[sym].company;
        expect(comp.symbol).toBe(sym);
        expect(comp.companyName).toBeTruthy();
        expect(comp.bseCode).toMatch(/^\d{6}$/);
        expect(comp.isin).toMatch(/^INE[A-Z0-9]{9}$/);
        expect(['LARGECAP', 'MIDCAP', 'SMALLCAP', 'MICROCAP_SME']).toContain(comp.marketCapTier);
        expect(['MAIN_BOARD', 'SME_EXCHANGE']).toContain(comp.exchangeBoard);
      }
    });
  });

  describe('2. Source & Evidence Extraction Rigor (Zero Hallucinations)', () => {
    it('verifies all source documents have authentic SHA-256 hashes, physical page counts, and filing authorities', () => {
      const sha256Regex = /^[a-f0-9]{64,66}$/;
      const validDocTypes = [
        'ANNUAL_REPORT',
        'STATUTORY_FILING',
        'CONCALL_TRANSCRIPT',
        'INVESTOR_PRESENTATION',
        'EXCHANGE_DISCLOSURE',
        'BSE_DISCLOSURE'
      ];

      for (const sym of ALL_15_SYMBOLS) {
        const sources = dossiers[sym].sourceManifest;
        expect(sources.length).toBeGreaterThanOrEqual(1);

        for (const src of sources) {
          expect(src.documentId).toMatch(/^DOC_/);
          expect(src.documentName).toBeTruthy();
          expect(validDocTypes).toContain(src.documentType);
          expect(src.documentHashSha256).toMatch(sha256Regex);
          expect(src.pageCount).toBeGreaterThan(0);
          expect(src.filingAuthority).toBeTruthy();
          expect(src.publicationDate).toMatch(/^\d{4}-\d{2}-\d{2}$/);
        }
      }
    });

    it('verifies that every evidence span is a substantive verbatim quote tied to an authentic source and page', () => {
      for (const sym of ALL_15_SYMBOLS) {
        const evidenceSpans = dossiers[sym].evidence;
        const sourceIds = new Set(dossiers[sym].sourceManifest.map(s => s.documentId));

        expect(evidenceSpans.length).toBeGreaterThanOrEqual(2);

        for (const ev of evidenceSpans) {
          expect(ev.evidenceId).toMatch(/^EV_/);
          expect(sourceIds.has(ev.documentId), `Evidence ${ev.evidenceId} links to invalid document ${ev.documentId}`).toBe(true);
          const page = ev.pagePhysical !== undefined ? ev.pagePhysical : ev.pagePhysicalNumber;
          expect(page).toBeGreaterThan(0);
          expect(ev.quotedText.length).toBeGreaterThanOrEqual(20);
        }
      }
    });

    it('verifies universal issuer isolation: zero cross-issuer evidence contamination across all 15 companies', () => {
      for (const sym of ALL_15_SYMBOLS) {
        const evidenceSpans = dossiers[sym].evidence;
        for (const ev of evidenceSpans) {
          expect(ev.issuerNseSymbol).toBe(sym);
        }

        const claims = dossiers[sym].claims;
        for (const clm of claims) {
          expect(clm.issuerNseSymbol).toBe(sym);
        }

        const events = dossiers[sym].events;
        for (const evt of events) {
          expect(evt.issuerNseSymbol).toBe(sym);
        }

        const contradictions = dossiers[sym].contradictions;
        for (const contra of contradictions) {
          expect(contra.issuerNseSymbol).toBe(sym);
        }
      }
    });
  });

  describe('3. Batch 3 (High Leverage & Governance Stress) Verification', () => {
    it('verifies PURVA and STLNETWORK leverage breakers trigger ACTIVE status, collapsing thesis to BROKEN', () => {
      // PURVA: Net Debt / EBITDA = 5.8x > 4.5x threshold -> ACTIVE
      const purvaBreakers = dossiers['PURVA'].breakerEvaluation;
      const purvaLev = purvaBreakers.find((b: any) => b.breakerId === 'TB_PURVA_LEVERAGE');
      expect(purvaLev).toBeDefined();
      expect(purvaLev.status).toBe('ACTIVE');
      expect(dossiers['PURVA'].investmentBrief.decisionState.quantOpportunity).toBe('STRONG');
      expect(dossiers['PURVA'].investmentBrief.decisionState.intelligenceRisk).toBe('CRITICAL');
      expect(dossiers['PURVA'].investmentBrief.decisionState.thesisState).toBe('BROKEN');

      // STLNETWORK: Net Debt / EBITDA = 4.2x > 3.5x threshold -> ACTIVE
      const stlBreakers = dossiers['STLNETWORK'].breakerEvaluation;
      const stlLev = stlBreakers.find((b: any) => b.breakerId === 'TB_STL_LEVERAGE');
      expect(stlLev).toBeDefined();
      expect(stlLev.status).toBe('ACTIVE');
      expect(dossiers['STLNETWORK'].investmentBrief.decisionState.quantOpportunity).toBe('STRONG');
      expect(dossiers['STLNETWORK'].investmentBrief.decisionState.intelligenceRisk).toBe('CRITICAL');
      expect(dossiers['STLNETWORK'].investmentBrief.decisionState.thesisState).toBe('BROKEN');
    });

    it('verifies SENCO retail jewelry store delivery is clean and working capital limits remain safe', () => {
      const sencoBrief = dossiers['SENCO'].investmentBrief;
      expect(sencoBrief.decisionState.quantOpportunity).toBe('STRONG');
      expect(sencoBrief.decisionState.intelligenceRisk).toBe('LOW');
      expect(sencoBrief.decisionState.thesisState).toBe('SUPPORTED');

      const sencoBreakers = dossiers['SENCO'].breakerEvaluation;
      const sencoWc = sencoBreakers.find((b: any) => b.breakerId === 'TB_SENCO_WC_UTIL');
      expect(sencoWc.status).toBe('INACTIVE');
      expect(dossiers['SENCO'].claims[0].status).toBe('ACHIEVED');
    });

    it('verifies GMDCLTD mining statutory delays produce CHALLENGED thesis state', () => {
      const gmdcBrief = dossiers['GMDCLTD'].investmentBrief;
      expect(gmdcBrief.decisionState.quantOpportunity).toBe('STRONG');
      expect(gmdcBrief.decisionState.intelligenceRisk).toBe('HIGH');
      expect(gmdcBrief.decisionState.thesisState).toBe('CHALLENGED');
      expect(dossiers['GMDCLTD'].claims[0].status).toBe('MISSED');
      expect(dossiers['GMDCLTD'].contradictions.length).toBe(1);
    });

    it('verifies 360ONE institutional fee compression produces MODERATE risk and MIXED thesis state', () => {
      const wamBrief = dossiers['360ONE'].investmentBrief;
      expect(wamBrief.decisionState.quantOpportunity).toBe('STRONG');
      expect(wamBrief.decisionState.intelligenceRisk).toBe('MODERATE');
      expect(wamBrief.decisionState.thesisState).toBe('MIXED');
      expect(dossiers['360ONE'].claims[0].status).toBe('MISSED');
      expect(dossiers['360ONE'].contradictions.length).toBe(1);
    });
  });

  describe('4. Cohort-Wide SQLite Persistence Verification', () => {
    it('verifies database row counts in data/phase2_cohort/iice_cohort.db across all 15 companies', async () => {
      expect(fs.existsSync(DB_PATH)).toBe(true);
      const db = new sqlite3.Database(DB_PATH, sqlite3.OPEN_READONLY);

      const queryCount = (sql: string, params: any[] = []): Promise<number> => {
        return new Promise((resolve, reject) => {
          db.get(sql, params, (err, row: any) => {
            if (err) reject(err);
            else resolve(row.count);
          });
        });
      };

      const totalClaims = await queryCount('SELECT count(*) as count FROM ManagementClaims');
      const totalEvents = await queryCount('SELECT count(*) as count FROM IntelligenceEvents');
      const totalContradictions = await queryCount('SELECT count(*) as count FROM Contradictions');

      expect(totalClaims).toBe(22); // Full 20-company cohort database
      expect(totalEvents).toBe(20);
      expect(totalContradictions).toBe(11);

      for (const sym of ALL_15_SYMBOLS) {
        const count = await queryCount('SELECT count(*) as count FROM ManagementClaims WHERE symbol = ?', [sym]);
        expect(count, `Database must contain claims for ${sym}`).toBeGreaterThanOrEqual(1);
      }

      await new Promise<void>(resolve => db.close(() => resolve()));
    });
  });
});

import { describe, it, expect } from 'vitest';
import { BlindSpotEngine } from '../../src/server/intelligence/services/BlindSpotEngine.js';
import { UnknownState } from '../../src/server/intelligence/types/ThesisDefinition.js';

describe('Phase 1B: FR-09 Unknown Classification Invariants', () => {
  const engine = new BlindSpotEngine();

  it('generates baseline checklist with all items initialized to NOT_YET_CHECKED', () => {
    const checklist = engine.generateBaselineChecklist('SOLARINDS');

    expect(checklist.length).toBeGreaterThanOrEqual(5);
    checklist.forEach(item => {
      expect(item.state).toBe('NOT_YET_CHECKED');
      expect(item.decisionImpact).toBeDefined();
    });
  });

  it('transitions state to CONFIRMED_ABSENT and excludes it from active blind spots', () => {
    const checklist = engine.generateBaselineChecklist('SOLARINDS');
    const pledgeItem = checklist.find(i => i.domain === 'RELATED_PARTY')!;

    const updated = engine.updateUnknownState(
      pledgeItem,
      'CONFIRMED_ABSENT',
      'Audited Note 34 confirms zero related-party advances or inter-corporate deposits.'
    );

    expect(updated.state).toBe('CONFIRMED_ABSENT');
    expect(updated.searchSummary).toContain('Audited Note 34');

    const activeList = engine.getActiveBlindSpots([updated, checklist[1]]);
    expect(activeList).toHaveLength(1);
    expect(activeList[0].domain).toBe('OFF_BALANCE_SHEET');
  });

  it('keeps SEARCHED_AND_NOT_FOUND distinct from UNRESOLVED', () => {
    const checklist = engine.generateBaselineChecklist('63MOONS');

    const itemA = engine.updateUnknownState(
      checklist[0],
      'SEARCHED_AND_NOT_FOUND',
      'Searched FY24 annual report and concall transcripts; no mention of customer concentration.'
    );

    const itemB = engine.updateUnknownState(
      checklist[1],
      'UNRESOLVED',
      'Litigation note mentions ₹450 Cr claim disputed in High Court with ambiguous outcome.'
    );

    expect(itemA.state).toBe('SEARCHED_AND_NOT_FOUND');
    expect(itemB.state).toBe('UNRESOLVED');
    expect(itemA.state).not.toEqual(itemB.state);
  });
});

/**
 * Suite 16.1: Transaction & Holding Capture Completeness (OBJ-1, OBJ-2)
 * Tests: WM-CAP-01 to WM-CAP-09
 * Focus: Nothing gets lost, nothing gets doubled, and Holdings never drifts from Transactions.
 */
import { describe, test, expect, beforeEach } from 'vitest';
import { createTestDatabase, dbRun, dbAll, dbGet } from '../helpers/seedTestDb';
import { runFIFO } from '../../src/server/fifoEngine';
import crypto from 'crypto';

describe('WM-CAP: Transaction Capture Completeness & Integrity', () => {
  let db: any;

  beforeEach(async () => {
    db = await createTestDatabase();
  });

  test('WM-CAP-01: every row in a contract note is captured exactly once (no silent drops)', async () => {
    const fixtureRows = 47;
    const batchId = `BATCH-${Date.now()}`;

    // Simulate batch insertion of 47 trade lines
    for (let i = 1; i <= fixtureRows; i++) {
      await dbRun(
        db,
        `INSERT INTO Transactions (date, portfolio, type, isin, symbol, quantity, price, gross_amount, net_amount, source, notes)
         VALUES ('2026-08-15', 'TestPF1', 'BUY', 'INE001A01036', 'TESTSTOCK', 10, 150.0, 1500.0, 1500.0, 'CONTRACT_NOTE', ?)`,
        [`import_batch:${batchId}`]
      );
    }

    const captured = await dbAll(
      db,
      `SELECT * FROM Transactions WHERE notes LIKE ?`,
      [`%import_batch:${batchId}%`]
    );

    expect(captured.length).toBe(fixtureRows);
  });

  test('WM-CAP-02: re-importing the same file is a no-op (idempotent duplicate prevention)', async () => {
    const fileHash = crypto.createHash('sha256').update('fixture-contract-note-content-v1').digest('hex');
    const dedupKey = `FILE-HASH-${fileHash}`;

    // First import
    await dbRun(
      db,
      `INSERT INTO mutation_dedup_keys (dedup_key, entity_type, entity_id, created_at)
       VALUES (?, 'CONTRACT_NOTE_IMPORT', 'TestPF1', datetime('now'))`,
      [dedupKey]
    );

    await dbRun(
      db,
      `INSERT INTO Transactions (date, portfolio, type, isin, symbol, quantity, price, gross_amount, net_amount, source)
       VALUES ('2026-08-15', 'TestPF1', 'BUY', 'INE001A01036', 'TESTSTOCK', 100, 200, 20000, 20000, 'CONTRACT_NOTE')`
    );

    const firstCount = await dbGet(db, `SELECT COUNT(*) as n FROM Transactions WHERE portfolio='TestPF1'`);

    // Second import attempt: checks dedup key first
    const existing = await dbGet(db, `SELECT dedup_key FROM mutation_dedup_keys WHERE dedup_key = ?`, [dedupKey]);
    expect(existing).toBeDefined();

    // If duplicate detected, transaction insertion is blocked
    let duplicateBlocked = false;
    if (existing) {
      duplicateBlocked = true; // Blocked from executing duplicate insert
    }

    expect(duplicateBlocked).toBe(true);

    const secondCount = await dbGet(db, `SELECT COUNT(*) as n FROM Transactions WHERE portfolio='TestPF1'`);
    expect(secondCount.n).toBe(firstCount.n); // Row count unchanged
  });

  test('WM-CAP-03: importing overlapping files from two brokers computes union of unique transactions', async () => {
    // Broker A reports 100 shares bought on 2026-01-10
    await dbRun(
      db,
      `INSERT INTO Transactions (date, portfolio, type, isin, symbol, quantity, price, gross_amount, net_amount, source, broker_name)
       VALUES ('2026-01-10', 'TestPF1', 'BUY', 'INE009A01021', 'INFY', 100, 1500, 150000, 150000, 'BROKER_A', 'Zerodha')`
    );

    // Broker B reports 50 shares bought on 2026-02-15
    await dbRun(
      db,
      `INSERT INTO Transactions (date, portfolio, type, isin, symbol, quantity, price, gross_amount, net_amount, source, broker_name)
       VALUES ('2026-02-15', 'TestPF1', 'BUY', 'INE009A01021', 'INFY', 50, 1600, 80000, 80000, 'BROKER_B', 'HDFC Sky')`
    );

    await runFIFO(db);

    const holding = await dbGet(db, `SELECT * FROM Holdings WHERE portfolio='TestPF1' AND isin='INE009A01021'`);
    expect(holding.quantity).toBe(150); // 100 + 50
    expect(holding.total_cost).toBe(230000); // 150000 + 80000
    expect(holding.avg_buy_price).toBeCloseTo(230000 / 150, 2);
  });

  test('WM-CAP-04: bonus issue (1:1) applied before same-day sale is matched against lots', async () => {
    // Initial buy: 100 shares @ ₹200 = ₹20,000
    await dbRun(
      db,
      `INSERT INTO Transactions (date, portfolio, type, isin, symbol, quantity, price, gross_amount, net_amount)
       VALUES ('2024-06-01', 'TestPF1', 'BUY', 'INE001A01036', 'TEST', 100, 200, 20000, 20000)`
    );

    // Ex-date bonus 1:1 on 2024-07-01: 100 -> 200 shares, total cost basis remains 20,000 (INV-2)
    await dbRun(
      db,
      `INSERT INTO Transactions (date, portfolio, type, isin, symbol, quantity, price, gross_amount, net_amount)
       VALUES ('2024-07-01', 'TestPF1', 'BONUS', 'INE001A01036', 'TEST', 100, 0, 0, 0)`
    );

    // Same-day SELL of 150 shares (only valid because bonus made 200 shares available)
    await dbRun(
      db,
      `INSERT INTO Transactions (date, portfolio, type, isin, symbol, quantity, price, gross_amount, net_amount)
       VALUES ('2024-07-01', 'TestPF1', 'SELL', 'INE001A01036', 'TEST', 150, 120, 18000, 18000)`
    );

    await runFIFO(db);

    const holding = await dbGet(db, `SELECT * FROM Holdings WHERE portfolio='TestPF1' AND isin='INE001A01036'`);
    expect(holding.quantity).toBe(50); // 200 - 150

    const gains = await dbAll(db, `SELECT * FROM RealizedGains WHERE portfolio='TestPF1'`);
    const totalCostSold = gains.reduce((s: number, g: any) => s + Number(g.buy_cost ?? g.cost_basis ?? 0), 0);
    // Post-bonus cost basis per share = 20,000 / 200 = ₹100. 150 shares sold -> cost basis = 15,000
    expect(totalCostSold).toBeCloseTo(15000, 1);

    // Audit check: zero cost variance
    const remainingCost = holding.total_cost;
    expect(totalCostSold + remainingCost).toBeCloseTo(20000, 1);
  });

  test('WM-CAP-05: broker amendment creates reversal + correction pair, never in-place mutation', async () => {
    // Original trade
    const orig = await dbRun(
      db,
      `INSERT INTO Transactions (date, portfolio, type, isin, symbol, quantity, price, gross_amount, net_amount, source)
       VALUES ('2026-08-01', 'TestPF1', 'BUY', 'INE001A01036', 'TEST', 100, 200, 20000, 20000, 'ZERODHA')`
    );
    const origId = orig.lastID;

    // Broker correction arrives: true quantity was 90, not 100
    // Immutable ledger creates an offsetting REVERSAL row and a NEW CORRECTION row
    await dbRun(
      db,
      `INSERT INTO Transactions (date, portfolio, type, isin, symbol, quantity, price, gross_amount, net_amount, source, notes)
       VALUES ('2026-08-01', 'TestPF1', 'REVERSAL', 'INE001A01036', 'TEST', -100, 200, -20000, -20000, 'AMENDMENT', 'Reversal of txn #${origId}')`
    );

    await dbRun(
      db,
      `INSERT INTO Transactions (date, portfolio, type, isin, symbol, quantity, price, gross_amount, net_amount, source, notes)
       VALUES ('2026-08-01', 'TestPF1', 'BUY', 'INE001A01036', 'TEST', 90, 200, 18000, 18000, 'AMENDMENT', 'Corrected trade for txn #${origId}')`
    );

    // Verify original row was NOT deleted or mutated
    const originalRow = await dbGet(db, `SELECT * FROM Transactions WHERE id = ?`, [origId]);
    expect(originalRow.quantity).toBe(100);

    // Verify net ledger quantity is 90
    const netTxn = await dbGet(db, `
      SELECT SUM(CASE WHEN type IN ('BUY', 'CORRECTION') THEN quantity WHEN type = 'REVERSAL' THEN quantity ELSE 0 END) as net_qty
      FROM Transactions WHERE portfolio='TestPF1' AND isin='INE001A01036'
    `);
    expect(netTxn.net_qty).toBe(90);
  });

  test('WM-CAP-06: reconciliation flags broker mismatch and never silently overwrites Holdings', async () => {
    await dbRun(
      db,
      `INSERT INTO Holdings (portfolio, isin, symbol, quantity, avg_buy_price, total_cost)
       VALUES ('TestPF1', 'INE001A01036', 'TEST', 50, 120, 6000)`
    );

    // Broker demat statement claims 55 shares
    const brokerReportedQty = 55;
    const dbHolding = await dbGet(db, `SELECT quantity FROM Holdings WHERE portfolio='TestPF1' AND isin='INE001A01036'`);

    const variance = brokerReportedQty - dbHolding.quantity;
    const status = Math.abs(variance) > 0 ? 'RECON_MISMATCH' : 'MATCHED';

    expect(status).toBe('RECON_MISMATCH');
    expect(variance).toBe(5);

    // Critical Invariant: App must NOT silently overwrite Holdings.quantity
    const holdingAfterRecon = await dbGet(db, `SELECT quantity FROM Holdings WHERE portfolio='TestPF1' AND isin='INE001A01036'`);
    expect(holdingAfterRecon.quantity).toBe(50);
  });

  test('WM-CAP-07: Holdings <-> Ledger drift check maintains exact identity across portfolios', async () => {
    // Seed transactions for multiple stocks
    await dbRun(db, `INSERT INTO Transactions (date, portfolio, type, isin, symbol, quantity, price, gross_amount, net_amount)
      VALUES ('2026-01-01', 'TestPF1', 'BUY', 'INE002A01018', 'RELIANCE', 100, 2500, 250000, 250000)`);
    await dbRun(db, `INSERT INTO Transactions (date, portfolio, type, isin, symbol, quantity, price, gross_amount, net_amount)
      VALUES ('2026-03-01', 'TestPF1', 'SELL', 'INE002A01018', 'RELIANCE', 40, 2800, 112000, 112000)`);

    await runFIFO(db);

    const holdings = await dbAll(db, `SELECT * FROM Holdings WHERE portfolio='TestPF1'`);
    for (const h of holdings) {
      const txnAgg = await dbGet(
        db,
        `SELECT 
           SUM(CASE WHEN type IN ('BUY', 'BONUS', 'RIGHTS') THEN quantity ELSE 0 END) -
           SUM(CASE WHEN type = 'SELL' THEN quantity ELSE 0 END) as net_qty
         FROM Transactions WHERE portfolio = ? AND isin = ?`,
        [h.portfolio, h.isin]
      );
      expect(h.quantity).toBeCloseTo(txnAgg.net_qty, 4);
    }
  });

  test('WM-CAP-08: multi-currency transactions capture INR equivalent using date-effective FX rate', async () => {
    const tradeDate = '2026-05-10';
    const fxRateOnDate = 85.50; // Historical FX rate on May 10 2026
    const netUSD = 1000.0;
    const netINR = netUSD * fxRateOnDate;

    await dbRun(
      db,
      `INSERT INTO Transactions (date, portfolio, type, isin, symbol, quantity, price, gross_amount, net_amount, source, notes)
       VALUES (?, 'TestNRI', 'BUY', 'US0378331005', 'AAPL', 5, 200.0, 1000.0, ?, 'IBKR_USD', ?)`,
      [tradeDate, netINR, `currency:USD;fx_rate:${fxRateOnDate};usd_amount:${netUSD}`]
    );

    const txn = await dbGet(db, `SELECT * FROM Transactions WHERE portfolio='TestNRI' AND symbol='AAPL'`);
    expect(txn.net_amount).toBe(85500.0);
    expect(txn.notes).toContain('fx_rate:85.5');
    expect(txn.notes).toContain('usd_amount:1000');
  });

  test('WM-CAP-09: partial fills captured as distinct individual lots with actual execution prices', async () => {
    // An order of 100 shares filled in 3 tranches: 30 @ 500, 50 @ 502, 20 @ 505
    const fills = [
      { qty: 30, price: 500.0, fillId: 'FILL-1' },
      { qty: 50, price: 502.0, fillId: 'FILL-2' },
      { qty: 20, price: 505.0, fillId: 'FILL-3' },
    ];

    for (const f of fills) {
      await dbRun(
        db,
        `INSERT INTO Transactions (date, portfolio, type, isin, symbol, quantity, price, gross_amount, net_amount, notes)
         VALUES ('2026-08-01', 'TestPF1', 'BUY', 'INE001A01036', 'TEST', ?, ?, ?, ?, ?)`,
        [f.qty, f.price, f.qty * f.price, f.qty * f.price, `order_id:ORD-999;fill_id:${f.fillId}`]
      );
    }

    const recordedFills = await dbAll(db, `SELECT * FROM Transactions WHERE notes LIKE '%order_id:ORD-999%' ORDER BY id ASC`);
    expect(recordedFills.length).toBe(3); // Preserved as 3 distinct lots, not merged
    expect(recordedFills[0].price).toBe(500.0);
    expect(recordedFills[1].price).toBe(502.0);
    expect(recordedFills[2].price).toBe(505.0);

    const totalQty = recordedFills.reduce((s: number, r: any) => s + r.quantity, 0);
    expect(totalQty).toBe(100);
  });
});

/**
 * Suite 16.2: Opportunity Screening Trustworthiness & Sizing Caps (OBJ-3, OBJ-4)
 * Tests: WM-OPP-01 to WM-OPP-09
 * Focus: A signal is only "Actionable" if it earned that label via calibration,
 * and sizing never breaks its own caps.
 */
import { describe, test, expect } from 'vitest';

// Pure mathematical Half-Kelly & Sizing Engine per specifications
export function calculateHalfKelly(params: {
  winProb: number;
  payoffRatio: number;
  portfolioDrawdownPct: number;
  portfolioNAV?: number;
  adv20DayValueINR?: number;
  sectorCorrelation?: number;
  existingSectorWeight?: number;
}): {
  rawKelly: number;
  halfKelly: number;
  drawdownPenalty: number;
  correlationHaircut: number;
  preCapPct: number;
  allocatedPct: number;
  allocatedValueINR: number;
  bindingConstraint: 'CIRCUIT_BREAKER' | 'SINGLE_STOCK_CAP' | 'LIQUIDITY_ADV_CAP' | 'HALF_KELLY_OPTIMAL';
} {
  const p = params.winProb;
  const b = params.payoffRatio;
  const dd = params.portfolioDrawdownPct;
  const nav = params.portfolioNAV || 100_000_000; // Default ₹10 Cr
  const adv = params.adv20DayValueINR || 1_000_000_000; // Default ₹100 Cr large-cap ADV (2% = 20M, larger than 5M single-stock cap)

  // Step 1: Raw Kelly & Half-Kelly
  const rawKelly = Math.max(0, p - (1 - p) / b);
  const halfKelly = rawKelly * 0.5;

  // Step 2: Drawdown Penalty (Circuit Breaker)
  let drawdownPenalty = 0;
  if (dd >= 25.0) {
    drawdownPenalty = 1.0; // 100% penalty → Freeze
  } else if (dd >= 10.0) {
    drawdownPenalty = 0.5; // 50% penalty
  }

  // Step 3: Correlation Haircut
  let correlationHaircut = 1.0;
  if ((params.existingSectorWeight || 0) > 0.20 && (params.sectorCorrelation || 0) > 0.60) {
    correlationHaircut = 0.50;
  } else if ((params.sectorCorrelation || 0) >= 0.80) {
    correlationHaircut = 0.60;
  }

  const preCapFraction = halfKelly * (1 - drawdownPenalty) * correlationHaircut;
  const preCapPct = preCapFraction * 100;

  if (drawdownPenalty >= 1.0) {
    return {
      rawKelly,
      halfKelly,
      drawdownPenalty,
      correlationHaircut,
      preCapPct: 0,
      allocatedPct: 0,
      allocatedValueINR: 0,
      bindingConstraint: 'CIRCUIT_BREAKER',
    };
  }

  // Step 4: Independent Hard Caps
  // 1. Single Stock Cap: 5.0% of NAV
  const singleStockCapValue = nav * 0.05;
  // 2. Liquidity Ceiling: 2.0% of 20-day ADV
  const liquidityCapValue = adv * 0.02;
  // 3. Kelly Amount
  const kellyValue = preCapFraction * nav;

  const minAllowedValue = Math.min(kellyValue, singleStockCapValue, liquidityCapValue);
  const allocatedPct = (minAllowedValue / nav) * 100;

  let bindingConstraint: 'CIRCUIT_BREAKER' | 'SINGLE_STOCK_CAP' | 'LIQUIDITY_ADV_CAP' | 'HALF_KELLY_OPTIMAL' = 'HALF_KELLY_OPTIMAL';
  if (minAllowedValue === liquidityCapValue && liquidityCapValue < singleStockCapValue && liquidityCapValue < kellyValue) {
    bindingConstraint = 'LIQUIDITY_ADV_CAP';
  } else if (minAllowedValue === singleStockCapValue && singleStockCapValue <= kellyValue) {
    bindingConstraint = 'SINGLE_STOCK_CAP';
  }

  return {
    rawKelly,
    halfKelly,
    drawdownPenalty,
    correlationHaircut,
    preCapPct,
    allocatedPct,
    allocatedValueINR: minAllowedValue,
    bindingConstraint,
  };
}

// Signal Classifier Engine with Sample Size & Brier Calibration Gates
export function classifySignal(params: {
  strategy: string;
  historicalSampleSize: number;
  brierScore: number;
}): {
  label: 'INFORMATIONAL' | 'ACTIONABLE_RECOMMENDATION';
  reliabilityWeight: number;
  reason?: string;
} {
  if (params.historicalSampleSize < 15) {
    return {
      label: 'INFORMATIONAL',
      reliabilityWeight: 0,
      reason: `Historical sample size (${params.historicalSampleSize}) is below statistical calibration minimum (N >= 15).`,
    };
  }

  if (params.brierScore > 0.25) {
    return {
      label: 'INFORMATIONAL',
      reliabilityWeight: 0,
      reason: `Brier score (${params.brierScore}) exceeds uncalibrated baseline threshold (0.25).`,
    };
  }

  const reliabilityWeight = Math.max(0, 1.0 - params.brierScore * 2);
  return {
    label: 'ACTIONABLE_RECOMMENDATION',
    reliabilityWeight,
  };
}

// Conviction Score Fusion Engine with Sentiment Manipulation Detection
export function fuseConvictionScore(params: {
  symbol: string;
  technical: number;
  fundamental: number;
  institutionalFlow: number;
  retailSentiment: number;
  sentimentSpike?: boolean;
  phraseRepetitionScore?: number;
}): {
  totalScore: number;
  manipulationRisk: 'NORMAL' | 'HIGH';
  componentsUsed: string[];
} {
  let manipulationRisk: 'NORMAL' | 'HIGH' = 'NORMAL';
  const componentsUsed = ['technical', 'fundamental', 'institutionalFlow'];

  if (params.sentimentSpike && (params.phraseRepetitionScore || 0) > 0.80) {
    manipulationRisk = 'HIGH';
    // Excluded from fusion sum
  } else {
    componentsUsed.push('retailSentiment');
  }

  const weights: Record<string, number> = {
    technical: 0.35,
    fundamental: 0.35,
    institutionalFlow: 0.20,
    retailSentiment: 0.10,
  };

  let totalScore = 0;
  let weightSum = 0;
  for (const comp of componentsUsed) {
    const w = weights[comp];
    const val = (params as any)[comp] || 0;
    totalScore += val * w;
    weightSum += w;
  }

  totalScore = (totalScore / weightSum) * 100;

  return {
    totalScore,
    manipulationRisk,
    componentsUsed,
  };
}

describe('WM-OPP: Opportunity Screening Trustworthiness & Sizing Caps', () => {

  test('WM-OPP-01: technical setup with N < 15 samples is always Informational, never Actionable', () => {
    const classification = classifySignal({ strategy: 'BREAKOUT', historicalSampleSize: 8, brierScore: 0.10 });
    expect(classification.label).toBe('INFORMATIONAL');
    expect(classification.label).not.toBe('ACTIONABLE_RECOMMENDATION');
  });

  test('WM-OPP-02: setup with N=15 but poor Brier score (> 0.25) has reliability weight 0', () => {
    const classification = classifySignal({ strategy: 'MOMENTUM', historicalSampleSize: 20, brierScore: 0.31 });
    expect(classification.reliabilityWeight).toBe(0);
    expect(classification.label).toBe('INFORMATIONAL');
  });

  test('WM-OPP-03: manipulation-flagged retail sentiment is excluded from fusion sum', () => {
    const score = fuseConvictionScore({
      symbol: 'SMALLCAP1',
      technical: 0.8,
      fundamental: 0.6,
      institutionalFlow: 0.5,
      retailSentiment: 0.95,
      sentimentSpike: true,
      phraseRepetitionScore: 0.92,
    });
    expect(score.manipulationRisk).toBe('HIGH');
    expect(score.componentsUsed).not.toContain('retailSentiment');
  });

  test('WM-OPP-04: market feed in STALE state halts signal emission (INV-6)', () => {
    const feed = { feed_name: 'UPSTOX_MARKET_FEED', state: 'STALE', last_heartbeat_utc: '2026-09-06T09:00:00Z' };
    const canEmitSignal = feed.state === 'LIVE';
    expect(canEmitSignal).toBe(false);
  });

  test('WM-OPP-05: drawdown > 25% freezes allocation to 0.0% regardless of favorable edge', () => {
    const result = calculateHalfKelly({ winProb: 0.90, payoffRatio: 5.0, portfolioDrawdownPct: 26 });
    expect(result.allocatedPct).toBe(0.0);
    expect(result.bindingConstraint).toBe('CIRCUIT_BREAKER');
  });

  test('WM-OPP-06: 15% drawdown applies 50% penalty AND hard 5% NAV cap independently', () => {
    // p=0.65, b=2.0 -> K* = 0.65 - 0.35/2 = 0.475; Half-Kelly = 0.2375 = 23.75% NAV
    const result = calculateHalfKelly({ winProb: 0.65, payoffRatio: 2.0, portfolioDrawdownPct: 15 });
    // 50% penalty -> 11.875%, but hard cap is 5% NAV
    expect(result.preCapPct).toBeCloseTo(11.875, 2);
    expect(result.allocatedPct).toBe(5.0);
    expect(result.bindingConstraint).toBe('SINGLE_STOCK_CAP');
  });

  test('WM-OPP-07: liquidity (ADV) cap can be the binding constraint when tighter than 5% NAV cap', () => {
    // Small-cap: 2% of ₹6 Cr ADV translates to ₹12 Lakhs (1.2% of ₹10 Cr NAV), tighter than ₹50 Lakhs (5% cap)
    const result = calculateHalfKelly({
      winProb: 0.70,
      payoffRatio: 2.5,
      portfolioDrawdownPct: 0,
      adv20DayValueINR: 60_000_000,  // ₹6 Cr ADV -> 2% = ₹12L
      portfolioNAV: 100_000_000,     // ₹10 Cr NAV -> 5% cap = ₹50L
    });
    expect(result.allocatedValueINR).toBeLessThanOrEqual(1_200_000);
    expect(result.bindingConstraint).toBe('LIQUIDITY_ADV_CAP');
  });

  test('WM-OPP-08: high correlation (> 0.80) with existing position applies proportional haircut', () => {
    const uncorr = calculateHalfKelly({ winProb: 0.70, payoffRatio: 2.5, portfolioDrawdownPct: 0, sectorCorrelation: 0.20 });
    const correlated = calculateHalfKelly({ winProb: 0.70, payoffRatio: 2.5, portfolioDrawdownPct: 0, sectorCorrelation: 0.85 });
    expect(correlated.correlationHaircut).toBeLessThan(uncorr.correlationHaircut);
    expect(correlated.preCapPct).toBeLessThan(uncorr.preCapPct);
  });

  test('WM-OPP-09: adversarial input (p=0.99, b=50) still respects 5.0% NAV hard cap', () => {
    const result = calculateHalfKelly({ winProb: 0.99, payoffRatio: 50, portfolioDrawdownPct: 0 });
    expect(result.allocatedPct).toBeLessThanOrEqual(5.0);
  });
});

/**
 * Suite 16.3: Rebalancing Engine — Wealth-Maximizing Trade Selection (OBJ-5)
 * Tests: WM-REB-01 to WM-REB-10
 * Focus: A rebalance is recommended ONLY when the expected after-tax, after-cost benefit
 * is positive; suppressed when a trade would cause needless friction or is inside a no-trade band.
 */
import { describe, test, expect, beforeEach } from 'vitest';
import { createTestDatabase, dbRun, dbAll, dbGet } from '../helpers/seedTestDb';
import { generateRebalancePlan } from '../../src/server/services/RebalancingEngine';

describe('WM-REB: Rebalancing Engine — Wealth-Maximizing Trade Selection', () => {
  let db: any;

  beforeEach(async () => {
    db = await createTestDatabase();
    await dbRun(
      db,
      `INSERT OR REPLACE INTO Portfolios (portfolio, owner_name, pan, broker_name)
       VALUES ('TestPF1', 'Test User A', 'PAN1', 'Zerodha')`
    );
  });

  test('WM-REB-01: inside no-trade band (42% vs 40% ± 5%) -> no rebalance action recommended', async () => {
    await dbRun(
      db,
      `INSERT INTO TargetAllocations (entity_id, asset_class, target_pct, min_pct, max_pct, rebalance_tolerance_pct)
       VALUES ('PAN1', 'EQUITY_LARGE_CAP', 40.0, 35.0, 45.0, 5.0)`
    );

    // Seed holdings such that actual weight = 42% (e.g. ₹42L out of ₹1 Cr total)
    await dbRun(
      db,
      `INSERT INTO Holdings (portfolio, isin, symbol, quantity, avg_buy_price, total_cost, ltp, current_value)
       VALUES 
       ('TestPF1', 'INE001A01036', 'TESTSTOCK', 4200, 1000, 4200000, 1000, 4200000),
       ('TestPF1', 'INE002A01018', 'FD_CASH', 5800, 1000, 5800000, 1000, 5800000)`
    );

    const plan = await generateRebalancePlan(db, 'PAN1');
    const largeCapAction = plan.actions.find(a => a.asset_class === 'EQUITY_LARGE_CAP');
    expect(largeCapAction).toBeUndefined();
  });

  test('WM-REB-02: outside band (47% vs 40% ± 5%) -> sized to land safely inside band, not overshoot', async () => {
    await dbRun(
      db,
      `INSERT INTO TargetAllocations (entity_id, asset_class, target_pct, min_pct, max_pct, rebalance_tolerance_pct)
       VALUES ('PAN1', 'EQUITY_LARGE_CAP', 40.0, 35.0, 45.0, 5.0)`
    );

    // Seed holdings such that actual weight = 47% (₹47L out of ₹1 Cr total)
    await dbRun(
      db,
      `INSERT INTO Holdings (portfolio, isin, symbol, quantity, avg_buy_price, total_cost, ltp, current_value)
       VALUES 
       ('TestPF1', 'INE001A01036', 'TESTSTOCK', 4700, 1000, 4700000, 1000, 4700000),
       ('TestPF1', 'INE002A01018', 'FD_CASH', 5300, 1000, 5300000, 1000, 5300000)`
    );

    const plan = await generateRebalancePlan(db, 'PAN1');
    const action = plan.actions.find(a => a.asset_class === 'EQUITY_LARGE_CAP');
    expect(action).toBeDefined();
    expect(action?.direction).toBe('SELL');
    // Resulting weight lands inside the band [35%, 45%]
    expect(action?.resultingWeightPct).toBeGreaterThanOrEqual(35);
    expect(action?.resultingWeightPct).toBeLessThanOrEqual(45);
  });

  test('WM-REB-03: prefers LTCG-qualified lot over STCG lot for the same ISIN to minimize tax', async () => {
    await dbRun(
      db,
      `INSERT INTO TargetAllocations (entity_id, asset_class, target_pct, min_pct, max_pct, rebalance_tolerance_pct)
       VALUES ('PAN1', 'EQUITY_LARGE_CAP', 20.0, 15.0, 25.0, 5.0)`
    );

    // Buy lot 1: 400 days old -> LTCG qualified (12.5% rate)
    await dbRun(
      db,
      `INSERT INTO Transactions (date, portfolio, type, isin, symbol, quantity, price, gross_amount, net_amount)
       VALUES ('2025-01-01', 'TestPF1', 'BUY', 'INE001A01036', 'ABC', 100, 100, 10000, 10000)`
    );

    // Buy lot 2: 120 days old -> STCG lot (20% rate)
    await dbRun(
      db,
      `INSERT INTO Transactions (date, portfolio, type, isin, symbol, quantity, price, gross_amount, net_amount)
       VALUES ('2026-05-01', 'TestPF1', 'BUY', 'INE001A01036', 'ABC', 100, 100, 10000, 10000)`
    );

    await dbRun(
      db,
      `INSERT INTO Holdings (portfolio, isin, symbol, quantity, avg_buy_price, total_cost, ltp, current_value)
       VALUES ('TestPF1', 'INE001A01036', 'ABC', 200, 100, 20000, 200, 40000)`
    );

    const plan = await generateRebalancePlan(db, 'PAN1');
    const sell = plan.actions.find(a => a.direction === 'SELL');
    expect(sell).toBeDefined();
    expect(sell?.selectedLot?.gain_type_at_sale).toBe('LTCG');
    // Estimated tax impact of LTCG lot is strictly less than STCG lot alternative
    expect(sell?.estimatedTaxImpact).toBeLessThan(sell?.alternativeIfStcgLotSold?.estimatedTaxImpact || 0);
  });

  test('WM-REB-05: drawdown freeze blocks NEW buys but permits risk-reducing SELLs', async () => {
    await dbRun(
      db,
      `INSERT INTO TargetAllocations (entity_id, asset_class, target_pct, min_pct, max_pct, rebalance_tolerance_pct)
       VALUES 
       ('PAN1', 'EQUITY_LARGE_CAP', 30.0, 25.0, 35.0, 5.0),
       ('PAN1', 'TAX_FREE_NRE_FD', 70.0, 65.0, 75.0, 5.0)`
    );

    // Overweight in Equity (60%), underweight in FD (40%)
    await dbRun(
      db,
      `INSERT INTO Holdings (portfolio, isin, symbol, quantity, avg_buy_price, total_cost, ltp, current_value)
       VALUES 
       ('TestPF1', 'INE001A01036', 'RISKY_STOCK', 6000, 1000, 6000000, 1000, 6000000),
       ('TestPF1', 'INE002A01018', 'FD_CASH', 4000, 1000, 4000000, 1000, 4000000)`
    );

    // Portfolio in acute drawdown (30%)
    await dbRun(
      db,
      `INSERT INTO PortfolioSnapshot (portfolio, as_of_date, current_drawdown_pct)
       VALUES ('TestPF1', '2026-09-06', 30.0)`
    );

    const plan = await generateRebalancePlan(db, 'PAN1');
    const sells = plan.actions.filter(a => a.direction === 'SELL');
    const buys = plan.actions.filter(a => a.direction === 'BUY');

    // Risk-reducing SELL of overweight risky stock is allowed
    expect(sells.length).toBeGreaterThan(0);
    expect(sells.every(s => !s.blockedByCircuitBreaker)).toBe(true);

    // New BUYs are blocked by the drawdown circuit breaker
    expect(buys.every(b => b.blockedByCircuitBreaker === true)).toBe(true);
  });

  test('WM-REB-06: cost-benefit gate suppresses trades whose tax+cost exceeds benefit', async () => {
    await dbRun(
      db,
      `INSERT INTO TargetAllocations (entity_id, asset_class, target_pct, min_pct, max_pct, rebalance_tolerance_pct)
       VALUES ('PAN1', 'EQUITY_LARGE_CAP', 40.0, 38.0, 42.0, 2.0)`
    );

    // Slight drift (43% vs 42% max), but massive tax liability
    await dbRun(
      db,
      `INSERT INTO Holdings (portfolio, isin, symbol, quantity, avg_buy_price, total_cost, ltp, current_value)
       VALUES ('TestPF1', 'INE001A01036', 'HIGH_TAX_STOCK', 430, 10, 4300, 1000, 430000)`
    );

    const plan = await generateRebalancePlan(db, 'PAN1');
    // If marginal benefit does not compensate for tax drag, trade is suppressed or net benefit is positive
    for (const act of plan.actions) {
      if (act.direction === 'SELL') {
        expect(act.estimatedNetBenefit).toBeGreaterThan(0);
      }
    }
    expect(plan.suppressedForCostBenefit).toBeDefined();
  });

  test('WM-REB-07: multi-PAN rebalancing strictly segregates plans and tax lots across PANs (INV-7)', async () => {
    // PAN1 setup
    await dbRun(
      db,
      `INSERT INTO TargetAllocations (entity_id, asset_class, target_pct, min_pct, max_pct)
       VALUES ('AAAAA0001A', 'EQUITY_LARGE_CAP', 30.0, 25.0, 35.0)`
    );
    // PAN2 setup
    await dbRun(
      db,
      `INSERT INTO TargetAllocations (entity_id, asset_class, target_pct, min_pct, max_pct)
       VALUES ('BBBBB0002B', 'EQUITY_LARGE_CAP', 50.0, 45.0, 55.0)`
    );

    const plan1 = await generateRebalancePlan(db, 'AAAAA0001A');
    const plan2 = await generateRebalancePlan(db, 'BBBBB0002B');

    expect(plan1.entityId).toBe('AAAAA0001A');
    expect(plan2.entityId).toBe('BBBBB0002B');

    // Lots and actions do not cross PANs
    const lots1 = plan1.actions.map(a => a.lotId).filter(Boolean);
    const lots2 = plan2.actions.map(a => a.lotId).filter(Boolean);
    const crossLots = lots1.filter(l => lots2.includes(l));
    expect(crossLots.length).toBe(0);
  });

  test('WM-REB-08: accepted rebalance creates audit trail in audit_ledger with SHA-256 hash', async () => {
    await dbRun(
      db,
      `INSERT INTO TargetAllocations (entity_id, asset_class, target_pct, min_pct, max_pct, rebalance_tolerance_pct)
       VALUES ('PAN1', 'EQUITY_LARGE_CAP', 30.0, 25.0, 35.0, 5.0)`
    );

    await dbRun(
      db,
      `INSERT INTO Holdings (portfolio, isin, symbol, quantity, avg_buy_price, total_cost, ltp, current_value)
       VALUES ('TestPF1', 'INE001A01036', 'TEST', 500, 100, 50000, 100, 50000)`
    );

    const plan = await generateRebalancePlan(db, 'PAN1');
    const executed = await plan.execute(db, { approvedBy: 'chief-investment-officer' });

    for (const txn of executed.transactions) {
      expect(txn.source).toBe('REBALANCE_ENGINE');
    }

    const auditRows = await dbAll(db, `SELECT * FROM audit_ledger WHERE event_type = 'REBALANCE_EXECUTED'`);
    expect(auditRows.length).toBe(executed.transactions.length);
    if (auditRows.length > 0) {
      expect(auditRows[0].hash.length).toBe(64); // SHA-256 hex length
    }
  });

  test('WM-REB-10: idempotent rebalancing — identical inputs yield identical plan', async () => {
    await dbRun(
      db,
      `INSERT INTO TargetAllocations (entity_id, asset_class, target_pct, min_pct, max_pct, rebalance_tolerance_pct)
       VALUES ('PAN1', 'EQUITY_LARGE_CAP', 40.0, 35.0, 45.0, 5.0)`
    );

    const planA = await generateRebalancePlan(db, 'PAN1');
    const planB = await generateRebalancePlan(db, 'PAN1');

    expect(JSON.stringify(planA.actions)).toBe(JSON.stringify(planB.actions));
  });
});

/**
 * scripts/build_phase2_pilot_dataset.ts
 *
 * WEALTHOS / ITAS v6.3: PHASE 2 PILOT RESEARCH DATASET BUILDER
 * Extracts, normalizes, validates, and freezes a point-in-time compliant pilot database:
 * - 5 verified liquid NSE equities (BANKBARODA, CANBK, BAJAJFINSV, BAJFINANCE, 5PAISA)
 * - Exact 6-month continuous pilot window (2025-10-01 to 2026-03-31 = 129 sessions per symbol = 645 total bars)
 * - 100% authentic OHLCV, Delivery, and Turnover records (Zero Nulls, Zero Proxies)
 * - Full RAW SOURCE -> NORMALIZED -> RESEARCH DB provenance tracking with cryptographic hashes
 * - Authoritative Trading Calendar (182 sessions: 129 tradable, 53 weekend/holiday)
 * - Historical Investable Universe with eligibility intervals & circular citations
 * - Reconciled Corporate Actions Layer
 * - Point-in-Time Disclosures Registry (Financial Statements & Shareholding Patterns)
 * - FERE Forensic Health Ledger for Arm B Overlay
 */

import sqlite3 from 'sqlite3';
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';

const rootDir = process.cwd();
const srcDbPath = path.resolve(rootDir, 'portfolio.db');
const destDbDir = path.resolve(rootDir, 'data');
const destDbPath = path.resolve(destDbDir, 'portfolio_v6.3_pilot_research.db');

if (!fs.existsSync(srcDbPath)) {
  throw new Error(`Source database not found at ${srcDbPath}`);
}
if (!fs.existsSync(destDbDir)) {
  fs.mkdirSync(destDbDir, { recursive: true });
}

// Remove old pilot DB if exists
if (fs.existsSync(destDbPath)) {
  fs.unlinkSync(destDbPath);
}

const pilotSymbols = ['BANKBARODA', 'CANBK', 'BAJAJFINSV', 'BAJFINANCE', '5PAISA'];
const startDate = '2025-10-01';
const endDate = '2026-03-31';

function openDb(p: string, readonly = false): Promise<sqlite3.Database> {
  return new Promise((resolve, reject) => {
    const mode = readonly ? sqlite3.OPEN_READONLY : sqlite3.OPEN_READWRITE | sqlite3.OPEN_CREATE;
    const db = new sqlite3.Database(p, mode, (err) => {
      if (err) reject(err);
      else resolve(db);
    });
  });
}

function runSql(db: sqlite3.Database, sql: string, params: any[] = []): Promise<void> {
  return new Promise((resolve, reject) => {
    db.run(sql, params, function (err) {
      if (err) reject(err);
      else resolve();
    });
  });
}

function allSql<T = any>(db: sqlite3.Database, sql: string, params: any[] = []): Promise<T[]> {
  return new Promise((resolve, reject) => {
    db.all(sql, params, (err, rows) => {
      if (err) reject(err);
      else resolve(rows as T[]);
    });
  });
}

function getSql<T = any>(db: sqlite3.Database, sql: string, params: any[] = []): Promise<T> {
  return new Promise((resolve, reject) => {
    db.get(sql, params, (err, row) => {
      if (err) reject(err);
      else resolve(row as T);
    });
  });
}

function sha256Object(obj: any): string {
  return crypto.createHash('sha256').update(JSON.stringify(obj)).digest('hex');
}

async function main() {
  console.log('================================================================');
  console.log('   WEALTHOS / ITAS v6.3: PHASE 2 PILOT RESEARCH DATASET BUILDER ');
  console.log(`   Pilot Window: ${startDate} to ${endDate} (6 months)`);
  console.log(`   Pilot Symbols: ${pilotSymbols.join(', ')}`);
  console.log('================================================================\n');

  const srcDb = await openDb(srcDbPath, true);
  const destDb = await openDb(destDbPath, false);

  // Apply Pragmas
  await runSql(destDb, 'PRAGMA foreign_keys = ON');
  await runSql(destDb, 'PRAGMA journal_mode = WAL');

  // Step 1: Create Schema
  console.log('[Step 1/8] Creating authoritative Phase 2 database schema...');
  const schemaSql = fs.readFileSync(path.resolve(rootDir, 'db/migrations/012_phase2_pit_research_schema.sql'), 'utf8');
  await destDb.exec(schemaSql);

  // Create core tables for research engine
  await destDb.exec(`
    CREATE TABLE IF NOT EXISTS DailyOHLCV (
      symbol TEXT NOT NULL,
      trade_date TEXT NOT NULL,
      open REAL NOT NULL,
      high REAL NOT NULL,
      low REAL NOT NULL,
      close REAL NOT NULL,
      volume INTEGER NOT NULL,
      turnover REAL NOT NULL,
      delivery_qty INTEGER NOT NULL,
      delivery_pct REAL NOT NULL,
      no_of_trades INTEGER DEFAULT 0,
      prev_close REAL,
      source TEXT NOT NULL DEFAULT 'NSE_BHAVCOPY_SEC_FULL',
      source_record_id TEXT NOT NULL,
      economic_timestamp TEXT NOT NULL,
      available_at TEXT NOT NULL,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
