      date: dateStr,
      marketOpen,
      marketClose,
      tradable,
      sessionType,
      sessionIdentifier,
      holidayReason,
      source: 'NSE_OFFICIAL_CALENDAR_2025_2026',
      availableAt
    });

    cur.setUTCDate(cur.getUTCDate() + 1);
  }

